window.__D("text/torat-shmuel/c039",{"p":[[2002180422,"ומקבל כמו שהמקבל מקבל ממשפיע, כך המשפיע מקבל מהמקבל גילוי עונג, כי יש עונג במשפיע ע\"י ההשפעה, א\"כ בזה המשפיע הוא מקבל, שזה לא נמצא שיהי' רק משפיע ולא מקבל אלא בכל דבר המשפיע ג\"כ מקבל, ע\"כ ע\"י שסיהרא מקבלת מהשמש עי\"ז ניתוסף ריבוי אור במשפיע. וזהו לפני ה' ישפוך שיחו פי' לפני ה' שנמשך תוס' בשם הוי', וכ\"ז הוא ע\"י שהעשיר משפיע להעני כמו שהעני מקבל מהעשיר השפעה גשמיות כך העשיר מקבל מהעני השפעה רוחני' שעל ידו מזכה זכות ומצוה לעשיר, וגשמיות לגבי רוחניות הרי אין להם ערך כלל. וזהו מ\"ש כל מצותיך צדק שכללות המצות הוא בחי' צדקה, וכי מאי איכפת להקב\"ה אם ישחוט מן הצואר או מן העורף אלא לא ניתנו המצות אלא כדי לצרף הבריות כו'. וע\"י יחוד עשיר ועני שעשיר משפיע לעני עי\"ז נעשה יחוד שמשא וסיהרא, וע\"י יחוד שמשא וסיהרא עי\"ז נעשה תוס' בשמשא כמארז\"ל לית ברכתא שרי' באתר ריקני' אלא באתר שלים, וכמארז\"ל אין נותנין לאדם פרנסה אלא בשביל אשתו ובניו, פי' פרנסה היינו ריווח כי לאדם לבד נותנים רק דבר קצוב כמו שקצוב לו אבל ע\"י אשתו ובניו נותנים לו ריווח, פי' אשתו היינו כנס\"י ובניו היינו בני בכורי ישראל, וע\"י אשתו ובניו נותנים לו ריווח. וכן איתא בזוהר כד עתיקא קדישא שדא ברכאן שדא בהאי עמיקא עילאה, פי' עמיקא היינו בחי' מקבל, וכאשר יש בחי' מקבל אז שדא ברכאן וכמ\"ש זכר ונקבה בראם ויברך אותם, דכאשר יש בחי' משפיע ומקבל אז ויברך אותם אך אם שרי' בלא אשה שרי' בלא ברכה, כי באם לאו הוא פלג גוף כו', א\"כ ע\"י יחוד שמשא וסיהרא נעשה תוס' בשמשא כו'.\n<b>וזהו</b> מ\"ש תפלה לעני כי יעטוף ולפני ה' ישפוך שיחו, שהעני מתרעם מפני מה מגיע לו שיהי' הוא עני ויקבל מעשיר, אך הנה מ\"מ הנה כתי' כי לא יחדל אביון מקרב הארץ, וזהו כמו ע\"ד שאמרו פני משה כפני חמה פני יהושע כפני לבנה, שמשה הי' רק משפיע לבד ולא הי' מקבל משום אדם, הגם שהי' מקבל תורה כמארז\"ל משה קיבל תורה מסיני, היינו שמקבל מלמעלה משם ה' כמ\"ש וכל בניך למודי ה' אבל למטה לא הי' לו שום מלמד כ\"א הי' משפיע, אבל יהושע הי' מקבל ממשה כמ\"ש נער לא ימיש מתוך האוהל, נוצר תאנה יאכל פרי', שהי' תמיד בחי' מקבל, ולזה זקנים שבאותו הדור אמרו אוי לאותה בושה אוי לאותה כלימה, כי אין ערך אור הלבנה לגבי אור השמש שהלבנה רק מקבלת משמש אבל מצד עצמה ל\"ל מגרמה כלום, ואפי' כאשר מקבלת מהשמש היא משנה את אור השמש ומאיר אח\"כ אור שלה, ע\"כ אמרו אוי לאותה בושה כו'.\n<b>וזהו</b> מ\"ש תפלה לעני כי יעטוף ולפני ה' ישפוך שיחו, פי' שיחו הוא לשון תרעומות שיש לעני תרעומות על הקב\"ה למה הוא צריך לסבול צער ויסורים ויקבל מהעשיר, שבאמת אנו רואים שיש עניים שהם דומים לעשירים ויש עניים שהם טובים מעשירים, ואעפי\"כ צריך לקבל מהעשיר, וכמ\"ש בגמ' רב חסדא ורבה תרווייהו צדיקי גמורי נינהו ולר\"ח סמידתא לכלבא לא מתבעי ורבה לא הוה לי' קמחא דשערי אפי' ללחם, כי באמת מזוני לאו בזכותא תלי' אלא במזלא תלי', והיינו",[]],[2002180423,"בחי' מזל דא\"א שהוא למעלה מן השכל וטעם ודעת. ולפי שזה שהוא עני ואין לו כלום הוא בלי טעם, ע\"כ יש לעני תרעומות גדולה. וזהו שארז\"ל (מנחות כ\"ט לגבי ר\"ע) זו תורה וזו שכרה והשיב שתוק כך עלה במחשבה, הגם שזהו למעלה מהטעם שטעם הגלוי לא נמצא ע\"ז אבל יש טעם הכמוס, רק שתוק כך עלה במחשבה שלא נמצא ע\"ז טעם הגלוי. כך העני מתרעם למה הוא צריך לסבול זה, דהן אמת שמוכרח להיות עני ועשיר מפני שבסדר השתלשלות יש משפיע ומקבל ע\"כ עי\"ז נעשה יחוד עני ועשיר, אבל הוא מתרעם מפני מה הוא העני, מדוע לא יהי' העשיר עני, והעני עשיר, מפני מה מגיע לו בגורלו שיהי' הוא העני.\n<b>אך</b> אעפי\"כ בכלל מההכרח שיהיו עניים דהנה כתי' הרם כשופר קולך, כמו ששופר צדו א' קצר וצדו א' רחב כך מן המצר קראתי י\"ה ענני במרחב י\"ה, כדי לקרוא בחי' שם ה' מחדש היינו מן המצר כמ\"ש ממעמקים קראתיך ה', מן המצר דוקא, דהיינו שיהי' מיצר לו בבחי' פנימי', דהנה איתא בת\"ז לית מחשבה תפיסא בי' כלל ופי' בזהר אפי' מחשבה ויובלא דלא אתפריש לעלמין, פי' יובלא היינו שער הנו\"ן דבינה ומחשבה הוא בחי' חכמה, מ\"מ אפי' מחשבה אינו תופס כלל באוא\"ס, אבל נתפס הוא ברעו\"ד דהיינו בחי' רצון פשוט. דהנה אית רצון ואית רצון, אית רצון שעפ\"י שכל שרצון זה נמשך משכל, הגם שבכחות הנפש רצון הוא למעלה משכל מ\"מ רצון זה הוא מקבל משכל, אבל אית רצון שלמעלה מן השכל וטעם. והנה ברצון שעפ\"י שכל א\"א להשיג באלקות, אבל ברעו\"ד שהוא בחי' רצון שלמעלה מן השכל נתפס עצמות אוא\"ס ממש. וזהו מן המצר קראתי י\"ה דהיינו בחי' מיצר שהוא בחי' רצון פשוט. וזהו\"ע תקיעת שופר, כי הנה האדם הוא מובחר מכל הנבראים כמ\"ש כל העולם כולו לא נברא אלא לצוות לזה, נעשה אדם בצלמינו כדמותינו פי' כדמותינו כמ\"ש על דמות הכסא דמות כמראה אדם שהאדם הוא בצלם ודמות שלמעלה, מ\"מ משימים א\"ע כבהמה, וזהו תקיעת שופר שעצם השופר הוא בחי' קרן של איל בהמה והקול הולך מאדם ע\"י קול פשוט עי\"ז א\"ל לבחי' דלים ושפלים ועי\"ז א\"ל<sup data-n=\"1226\">7</sup> לבחי' תכלית הידיעה שלא נדע, ועי\"ז נמשך מלמעלה למטה בחי' לא נדע כו', ובלשון החסידות היינו המשכה מסוכ\"ע בממכ\"ע כו'.\n<b>והנה</b> כדי להגיע לבחי' מיצר זה יוכל העני להגיע יותר וכמ\"ש רעבים גם צמאים נפשם בהם תתעטף ויצעקו אל ה' בצר להם, שע\"י רעבים וצמאים עי\"ז ויצעקו אל ה' בצר להם, וכמארז\"ל במד\"ר צריך יהודאי לחרובא עביד תשובה, כאשר אין אצלו רק בחי' חרובא אז עביד תשובה בבחי' רצון פשוט לפי שהעני מגיע יותר לבחי' מיצר, וכמ\"ש ה' בצר פקדוך צקון לחש מוסרך למו, ואיתא בזוהר אימתי מוסרך למו בשעתא דפקיד לון הקב\"ה ברצועה וימא סעיר וגלגלוהי זקפין ומאחוריהם פרעה ואבני גירין ובליסטראין כדין ויצעקו אל ה' בצר להם, א\"כ כדי",[["1226","7","<b>עי\"ז א\"ל . . ועי\"ז א\"ל</b>: עי\"ז אפשר לבוא . . ועי\"ז אפשר לבוא (או: אפשר להגיע)."]]],[2002180424,"להגיע לבחי' מיצר יוכל העני להגיע יותר, א' מפני שרעבים גם צמאים עי\"ז ויצעקו, ושנית מפני שטענתו חזקה שאם הי' זה מפני שחטא מצד החטא ממילא הי' זה כפרה ונקיון על החטא אבל כיון שזהו מפני שבסדר השתלשלות יש משפיע ומקבל ע\"כ צריך להיות עני ועשיר א\"כ מפני מה מגיע לו שיהי' הוא עני מדוע העשיר לא יהי' עני, ע\"כ ע\"י המיצר עי\"ז הצעקה גדולה יותר. וזהו תפלה לעני כי יעטוף, שהעני מתעטף בצער שהוא מיצר לו, וזהו כי רוח מלפני יעטוף ופרש\"י שהוא ע\"ד תפלה לעני כי יעטוף, פי' רוח מלפני שע\"י שמיצר לו בבחי' רצון פשוט עי\"ז לפני ה' ישפוך שיומשך תוס' בשם הוי' כו'.\n<b>ובעבודה</b> בנפש האדם הנה ארז\"ל כל המנבל א\"ע הקב\"ה מגביהו, אם נבלת בהתנשא, וזהו ענין הוידוים בר\"ה ויוהכ\"פ שכל אדם הוא מתוודה הגם שלא נמצא אצלו כלל כ\"כ מ\"מ נמצא אצלו בדקות, ועוד מפני שנש\"י הם קומה שלימה ע\"כ אומר א' מפני חבירו. וזהו בר\"ה ויוהכ\"פ, ובכל השנה היינו ענין המרירות שבנפש והיינו כשמתבונן איך שירדה נפשו האלקי' פלאים להתלבש בגוף ונה\"ב שמתחלה היתה עומדת באהוי\"ר כמ\"ש חי ה' אשר עמדתי לפניו, פי' עמדתי היינו בביטול כמו שמצינו במלאכים דכתי' ויעמידם לעד לעולם שעומדים בביטול א\"כ מלאכים שהם רק מחיצוני' הכלים מ\"מ הם עומדים בביטול מכ\"ש נשמות שהם מפנימי' הכלים, ונתלבשה בגוף שהגוף הוא מסתיר וגם נפשו הבהמית הגם ששרשה נלקחה מפני שור שבמרכבה שהם עומדים ברום עולם ומשמיעים ביראה ואומרים קדוש וברוך, אך כאשר מתלבשת בגוף ונה\"ב לא די מה שהיא אינה חפיצה ליכלל בה' אחד הנה היא מקררת גם הנה\"א שיומשך אחר תענוגים גשמי' ולשכוח על ה' אחד ממכ\"ע וסוכ\"ע, וזהו השטן וזהו היצה\"ר מתחילה מסית בתאוות היתר ואח\"כ בתאוות איסור כו'.\n<b>וזהו</b> שאומרים סלח לנו בשמו\"ע דלכאורה אינו מובן מפני מה אומרים זה בשמ\"ע שהי' מהנכון לומר כן קודם התפלה שקודם שיתחיל להתפלל יתוודה על חטאיו, אך הענין הוא דהנה קודם התפלה דרך איש ישר בעיניו שמאחר שאינו עושה עבירה בפ\"מ ומקיים ג\"כ מצות הרי הוא בעיני עצמו נחשב לצדיק, אבל ע\"י התפלה שמתחיל תחלה הודו לה' קראו בשמו שמתחיל להודות שענין הודאה הגם שאינו משיג כן מ\"מ הוא מודה, ואח\"כ ע\"י פסוד\"ז שמזמר עריצים ומכרית כל החוחים כמו בכרם שאילן שענפיו יבשים צריך לחתוך אותם כדי שלא יקלקלו האילן כך פסוד\"ז הוא מזמר עריצים, ואח\"כ בברכת ק\"ש כשמתבונן בשרשו ומקורו איך שגם שורש ומקור הנה\"ב ג\"כ בטל לאלקות עי\"ז מתעורר בנפשו הבהמית ג\"כ בחי' ביטול, ולכה\"פ שלא תעכב את נפשו האלקית, ובאמת זהו בנקל להבין כי בשורש גם נה\"ב בטל לאלקות ולמטה לכה\"פ שלא יהי' מעכב על נה\"א, ע\"כ עי\"ז יוכל למס\"נ בק\"ש בה' אחד. ואחרי אשר פועל ישועות בנפשו שיוכל לבוא לידי רצון פשוט ליכלל בה' אחד הסוכ\"ע אזי רואה איך שהוא רחוק מאלקות בתכלית לכן אומר סלח לנו כי חטאנו, משא\"כ קודם התפלה אינו יודע כלל שהוא רחוק מאלקות ע\"כ אינו שייך",[]],[2002180425,"לומר סלח לנו אך ע\"י התבוננות אז הוא מבין איך שהוא רחוק מאלקות. ולזה ארז\"ל כל המנבל א\"ע הקב\"ה מגביהו, שע\"י שמנבל א\"ע שמשפיל א\"ע עד קצה האחרון הקב\"ה שהוא סוכ\"ע מגביהו, כי שם אין שייך מעלה ומטה כי מתחת זרועות עולם כי מצד העיגול הגדול אין שייך מעומ\"ט, ע\"כ ע\"י שמשפיל א\"ע שהוא בחי' עני דוקא עי\"ז הקב\"ה מגביהו.\n<b>וזהו</b> תפלה לעני כי יעטוף, שע\"י שמתעטף בצער, והאמת טענתו חזקה מאד ע\"כ הצעקה גדולה, ע\"כ עי\"ז לפני ה' ישפוך שיחו שממשיכים תוס' בשם ה', והקב\"ה מגביה אותו. וזהו תפלה לעני כי יעטוף דוקא ע\"י שהוא בחי' עני עי\"ז לפני ה' כו'.",[]],[2000470083,"<h3>[מי כה\"א] לה\"ע ר\"ח</h3>\n<b>ב\"ה, שר\"ח מ\"ח נח</b>\n<b></b>להבין ענין ר\"ח. יו\"ט של נשים כו' חטא העגל כו' טעות פרעה עזב ה'\nנח, שר\"ח מ\"ח\n<b>להבין</b> ענין ר\"ח<sup data-n=\"1\">1</sup>, שנק' ראש חדש שכמו הראש הוא כלליות חיות האדם כן ראש החדש הוא הכולל כלליות החיות<sup data-n=\"2\">2</sup> של כל החדש כולו, וכמו ראש השנה הוא כלליות חיות<sup data-n=\"3\">3</sup> כל השנה כן ר\"ח הוא כלליות חיות כל החדש שכולל חיות כלליות של שלשים יום, וצ\"ל ענינו, וגם צ\"ל מפני מה ר\"ח הוא יו\"ט של נשים<sup data-n=\"4\">4</sup> שמשמרות אותו יותר מהאנשים<sup data-n=\"5\">5</sup>, והוא מפני שלא רצו ליתן את נזמיהן לבעליהן במעשה העגל, ובשכר זה נתן הקב\"ה שכרן שיהיו משמרות ר\"ח יותר מאנשים, אשר לכאורה זהו נגד מה שהנשים פטורי' ממ\"ע שהזמ\"ג<sup data-n=\"6\">6</sup>, ור\"ח הוא התלוי בזמן ומפני מה יהיו הנשים שפטורי' מדבר התלוי בזמן יהיו משמרות ר\"ח התלוי בזמן יותר מאנשים שחייבים בכ\"ד התלוי בזמן (ומה שהיו מקדשי' ע\"פ הראי' ולא תלוי בזמן, הלא ידוע ממ\"ש במשנה שהי' גם ע\"פ חשבון<sup data-n=\"7\">7</sup> רק שהיו צריכים לבוא עדים שראו מולד הלבנה, וגם עכשיו שאין מקדשי' ע\"פ הראי' באמת מכוונים ע\"פ חשבון<sup data-n=\"8\">8</sup> לבד",[["1","1","<b>להבין ענין ר\"ח</b>: בספר התולדות של כ\"ק אדמו\"ר מהר\"ש קה\"ת תש\"ז — ברשימת מאמרי שנה זו — ע' 51 אודות מאמר זה כותב כ\"ק אדמו\"ר: ”יו\"ט של נשים כו' חטא העגל כו' טעות פרעה עזב ה'\".\nלמאמר זה ראה מאמרי אדה\"ז על ענינים ע' שפג ואילך. ונו\"א שם ע' שפד ואילך. אוה\"ת תשא ע' א'תתקפה ואילך.\nלקמן בחלק ההנחות נדפסה הנחה ממאמר זה ושם הפתיחה: מי כה\"א המגביהי לשבת.\nבאג\"ק כ\"ק אדמו\"ר מהר\"ש ע' כא מאור ליו' ב' ה' תשרי תר\"ם כותב: חושב אני לשבות אי\"ה פ' נח בפאריז, כי לפי החשבון נבוא אי\"ה צלחה שעה 9.45 יום ועש\"ק בקר לפאריז, ומשם הוא 18 שעות למאנטרע. אמנם ממאמר זה וכן ממאמר הבא ד\"ה ואעשך לגוי גדול משמע שעדיין הי' בליובאוויטש. ראה גם לקמן מאמר ד\"ה כמגדל דוד צוארך ובהערה 1."],["2","2","<b>ר\"ח. . כלליות החיות</b>: ראה שפע טל ש\"ח, פ\"ג (טל קמא, סע\"ב). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380951\" data-slug=\"likkutei-torah\" data-id=\"4001380951\">לקו\"ת ר\"ה נח, א</a>. מאמרי אדה\"ז תקס\"ז ע' נג. עט\"ר ג, ב. אוה\"ת קרח ע' תרפט."],["3","3","<b>ראש השנה. . כלליות חיות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380883\" data-slug=\"likkutei-torah\" data-id=\"4001380883\">לקו\"ת תבא מא, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380934\" data-slug=\"likkutei-torah\" data-id=\"4001380934\">ר\"ה נג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380951\" data-slug=\"likkutei-torah\" data-id=\"4001380951\">נח, א</a>. עט\"ר שם."],["4","4","<b>ר\"ח הוא יו\"ט של נשים</b>: ראה ירושלמי פסחים רפ\"ד. פדר\"א פמ\"ה וברד\"ל שם. רש\"י מגילה כב, ב ד\"ה ראשי חדשים. אוה\"ת חנוכה כרך ה' ע' 1864<sup data-n=\"e4\">א</sup>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081326\" data-slug=\"likkutei-sichot\" data-id=\"1300081326\">לקו\"ש</a> ר\"ח תמוז כרך ח ע' 315 הערה 8."],["5","5","<b>יותר מהאנשים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381116\" data-slug=\"likkutei-torah\" data-id=\"4001381116\">לקו\"ת ברכה צז, סע\"ב</a> ואילך. אוה\"ת בראשית ע' כד. רד\"ק לשמואל-א כ, יט. לקו\"ש וארא כרך ג ע' 862 הערה 49. לקמן בהנחה כאן."],["6","6","<b>שהנשים פטורי' ממ\"ע שהזמ\"ג</b>: קדושין כט, א במשנה. ראה גם סה\"מ תרל\"ח ע' קנח ואילך. וש\"נ."],["7","7","<b>במשנה. . ע\"פ חשבון</b>: ראה ר\"ה פ\"ב, מ\"ו ואילך."],["8","8","<b>עכשיו. . ע\"פ חשבון</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161094\" data-slug=\"likkutei-sichot\" data-id=\"1300161094\">לקו\"ש בא כרך טז ע' 94</a> הערה 10.\n\n<b>א</b>  הובא גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה רני ושמחי על יד הערה 52 ואילך."]]],[2000470084,"ג\"כ, וא\"כ הוא תלוי בזמן כו'). ויובן בהקדם כלליות ענין מעשה העגל שאמרו הערב רב לישראל בראותם כי בשש משה<sup data-n=\"9\">9</sup> לרדת מן ההר, וכי בא שש ולא בא, שיעשו העגל והצליח מע\"ש ואמרו אלה אלקיך ישראל<sup data-n=\"10\">10</sup> אשר העלוך מאמ\"צ, שזהו באמת פלאי פלאות וכ\"ש על דור דיעה<sup data-n=\"11\">11</sup> שיחשבו כן שעגל זהב עשוי מדומם גשמי יהי' הוא האלקה, והוא אשר הוציא את ישראל ממצרים, שהחוש מכחישו שכולם ראו שלא הי' עגל בעת צאתם ממצרים, ואם הי' משה בא תחלה לא הי' מקום כלל לערב רב לאמר לישראל ולפתותם על מעשה העגל, רק מפני טעותם ויום המעונן<sup data-n=\"12\">12</sup> אשר לפי דעתם איחר זמנו אז הי' מקום לערב רב לפתותם והצליח מע\"ש כו' שעשו כו'. אך לכאורה אינו מובן לעינינו כלל, ושייכותו לענין מה שאיחר משה לבוא לפי דעתם כו'.\n<b>והענין</b> הוא כי הנה עיקר טעות פרעה<sup data-n=\"13\">13</sup> מלך מצרים שאמר מי הוי' אשר אשמע בקולו, לא ידעתי את הוי'<sup data-n=\"14\">14</sup>, אשר ע\"כ לא אשלח את ישראל, ועד\"ז גם שארי הכופרים באמונה כו' אין הענין שמכחישים באמיתיות המצאו ממש, כי כולם יודעים אותו, שהוא יוצר כל היצורים והוא נצחי, וכמ\"ש כי ממזרח שמש עד מבואו<sup data-n=\"15\">15</sup> גדול שמי בגוים ובכ\"מ מוקטר כו' וכמארז\"ל דקרו לי' אלקא דאלקייא<sup data-n=\"16\">16</sup>, וכדכתיב הודו לאלקי האלקים<sup data-n=\"17\">17</sup>, אלא שענין טעותם שהוא<sup data-n=\"18\">*18</sup> שאומרים עזב ה' את הארץ<sup data-n=\"19\">18</sup> ביד המזלות ושרים העליונים, ונתן להם הכח שיהיו הם המנהיגים את הארץ כפי רצונם ואות נפשם, ואין לו ית' שום חלק בההנהגה כלל, להיות כי הוא מרומם ונעלה מערך ההגשמה הנעשה ע\"פ האדמה, וה\"ה השפלה לפניו ית' להשפיל א\"ע בעלולים השפלים שלמטה ולכן עזב אותם בידי השרים והמזלות שהם ינהגו אותם, וזהו שאה\"כ השמים שמים להוי'<sup data-n=\"20\">19</sup> והארץ נתן לבנ\"א, פי' השמים אין כוונתו על השמים הגשמי' כ\"א ע\"ד כמו שמים לרום<sup data-n=\"21\">20</sup> וכמו כגבוה שמים מארץ<sup data-n=\"22\">21</sup>, והוא להרחיק הרוחניות מהגשמיות, ולהבדיל ביניהם זהו ע\"י אומרו כהבדל שבין שמים שהוא הנראה לעין גשמי' מרומם ונבדל מן הארץ שהוא דבר היותר שפל והיותר תחת, כן כל דברים הרוחני' כמו המלאכים וכלליות בי\"ע רוחניים זהו להוי' שהוא המנהיגם בהשגחה פרטיות, אמנם הארץ וכל אשר בה הנה מצד היותם עלולים היותר שפלים ה\"ז השפלה לפניו ית' להשפיל א\"ע להשגיח בהם השגחה פרטי' ולכן נתן הכח להמזלות ושרים שלמעלה שיהיו הם המנהיגים והמשגיחים כפי רצונם",[["9","9","<b>כי בשש משה</b>: תשא לב, א (וברש\"י שם). שבת פט, א."],["10","10","<b>אלה אלקיך ישראל</b>: תשא שם, ד. ח."],["11","11","<b>דור דיעה</b>: ראה זהר בשלח סב, ב. פע\"ח שחה\"מ שכ\"א, פ\"א. מאמרי אדה\"א דברים ח\"א ע' עו. וש\"נ. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה והנה כובע על יד הערה *109: הצד\"ג."],["12","12","<b>טעותם ויום המעונן</b>: ראה רש\"י תשא ושבת שם."],["13","13","<b>טעות פרעה</b>: ראה ספר הערכים חב\"ד כרך ב מערכת אוה\"ע ע' רעז ואילך."],["14","14","<b>מי הוי'. . את הוי'</b>: שמות ה, ב."],["15","15","<b>כי ממזרח שמש עד מבואו</b>: מלאכי א, יא [ושם: ועד — אבל כ\"ה גם באוה\"ת כאן]."],["16","16","<b>דקרו לי' אלקא דאלקייא</b>: מנחות בסופה. ראה סה\"מ תרל\"ב ח\"א ע' נג בהערה."],["17","17","<b>הודו לאלקי האלקים</b>: תהלים קלו, ב."],["18","*18","<b>שהוא</b>: אוצ\"ל: הוא."],["19","18","<b>עזב ה' את הארץ</b>: יחזקאל ח, יב. ט, ט."],["20","19","<b>השמים שמים להוי'</b>: תהלים קטו, טז."],["21","20","<b>שמים לרום</b>: משלי כה, ג."],["22","21","<b>כגבוה שמים מארץ</b>: תהלים קג, יא."]]],[2000470085,"ואות נפשם אשר נתן הוא ית' בהם כח כו' להשגיח השגחה פרטי' בכל פרטי דברים הנמצאים בעלולים השפלים אשר בארץ הגשמי שלמטה, וזהו והארץ נתן לבני אדם כו', וזה\"ע אלקא דאלקייא, פי' אלקייא הם השרים והמזלות שלדעתם וטעותם הנה הם הם המשפיעים לארץ ולדרים עלי' ולכן הם עובדים אותם, וכמו שבארץ יון שהשפעת חיותם הוא ממזל בתולה ולכן על הרוב נקבות הם המנהיגים את המלוכה, וקורים אותם אלקות<sup data-n=\"23\">22</sup> שלפ\"ד הם הם המשפיעים חיות בארץ ההיא (והגם כי באמת כל השפעה שנשפע בארץ עובר דרך המושל המושל<sup data-n=\"24\">24</sup> ושולט<sup data-n=\"25\">23</sup> על הארץ ההיא, אך הנה זהו רק מה שעובר ע\"י אבל איננו הוא עצמו המשפיע והגורם בזה, כ\"א ע\"ד האומן שפועל פעולתו ע\"י הכלים, הגם כי העושים הם הכלים אמנם הוא ע\"י האומן הפועל ע\"י הכלים והרי משבחים את האומן שהוא אומן מופלא שעשה מלאכה מופלאת כזה, ולא הכלים הפועלים, ועד\"ז יובן הגם כי עובר דרך השר כו' עכ\"ז ה\"ה ככלי האומן שאומן פועל ע\"י שדרך מעבר הכלי עובר הכח הנעשה ונפעל, ועכ\"ז אינו מתייחס להכלי כלל), ואומרים שהבורא ית' הוא אלקא דאלקייא פי' שהוא המקור להם, אבל אינו מושל ושולט כלל בארץ, רק אלקא דאלקייא בלבד, כי הארץ נתן כו' שהשרים של מעלה והמזלות הם ינהגו את הארץ, מפני שהוא השפלה לפניו ית' כנ\"ל לכן הוא רם בבחי' רוממות והתנשאות אשר ע\"כ על השמים לרום כבודו<sup data-n=\"26\">25</sup> כו' וכנ\"ל. וזהו שאמר פרעה לא ידעתי את הוי' שאינו שייך לי כלל להיותו בבחי' רם כו' ועזב ההנהגה השייכה לארץ בידי המזלות והשרים, וא\"כ מי הוי' אשר אשמע בקולו לשנות ההנהגה שלמטה שישראל היו נתונים אצלו בעבודה קשה, לשלחם מעל פניו שיעבדו את ה' במדבר ולכן לא אשלח את ישראל כו'.\n<b>אמנם</b> באמת טעות הוא אצלם, והמגביהי לשבת הנה הוא משפילי<sup data-n=\"27\">26</sup> לראות בשמים ובארץ בשוה, ולכן ישראל מאמינים בני מאמינים<sup data-n=\"28\">27</sup> שאין מזל לישראל<sup data-n=\"29\">28</sup> יודעים ומאמינים בהשגחתו ית' בבחי' השגחה פרטיות על כל דבר שלמטה בארץ ואשר במים מתחת לארץ, וזהו שאמר משה בהכותו את פרעה וכל מצרים, למען תדע שאין כמוני בכל הארץ<sup data-n=\"30\">29</sup>, בכל הארץ דוקא, וכן למען ספר שמי בכל הארץ<sup data-n=\"31\">30</sup>, שזהו להוציא מדעתם וטעותם שעזב ה' את הארץ שיתנהגו ע\"י המזלות לבד ואין לו ית' חלק בזה, כ\"א שאין כמוני בכל הארץ דוקא שימחה בידו לשנות טבע וההנהגה",[["23","22","<b>שבארץ יון. . אלקות</b>: ראה גם מאמרי אדה\"ז על ענינים כאן ע' שפג. לקמן (בחלק ההנחות) בהנחה כאן."],["24","24","<b>המושל המושל</b>: כ\"ה בהכת\"י."],["25","23","<b>כל השפעה. . המושל ושולט</b>: ראה אגה\"ק סכ\"ה (קלט, ב). שע\"ת ו, א ובהערה 3. מאמרי אדה\"א דברים ח\"א ע' קסד. וש\"נ."],["26","25","<b>על השמים. . כבודו</b>: תהלים קיג, ד."],["27","26","<b>והמגביהי לשבת. . משפילי לראות</b>: תהלים קיג, ה. ו. ראה גם לקמן בסיום המאמר. סידור שער תפלת ר\"ה רלז, ג. מאמרי אדה\"א דברים ח\"ג ריש ע' א'לה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680166\" data-slug=\"torat-chaim\" data-id=\"2300680166\">תו\"ח ויחי רמד, סע\"ד</a>, ואילך."],["28","27","<b>מאמינים בני מאמינים</b>: שבת צז, א. וראה אוה\"ת בראשית כרך ג ע' 1104. תשא ע' א'תתעט."],["29","28","<b>שאין מזל לישראל</b>: שבת קנו, א. ראה מאמרי אדה\"א שמות ח\"ב ע' שפ. וש\"נ."],["30","29","<b>למען תדע שאין. . הארץ</b>: וארא ט, יד [ושם: כי אין]."],["31","30","<b>למען ספר. . הארץ</b>: וארא שם, טז [ושם: ולמען]."]]],[2000470086,"אשר בארץ דוקא, וכמו אמונת ודעת ישראל שהם מאמינים ויודעים כמו שמקובלים ממרע\"ה מפי הגבורה וידעת היום<sup data-n=\"32\">31</sup> והשבות אל לבבך כי הוי' הוא האלקים בשמים ממעל ועל הארץ מתחת אין עוד, פי' כי פרעה א' מי הוי' כו' אבל מש' אלקים ידע<sup data-n=\"33\">32</sup>, והיינו כי עצם פי' לשון ש' אלקים הוא לשון כח<sup data-n=\"34\">33</sup> ויכולת כמו ואת אילי הארץ<sup data-n=\"35\">34</sup>, וכמו שא' לו יוסף אלקים יענה את שלום פרעה<sup data-n=\"36\">35</sup>, שהבין לפי דעתו שהכח המשפיע לו יענה שלומו כו', אמנם באמת הוי' הוא האלקים שכל כחות אלו המשפיעים הם הם עצמם הוי' שהוא הנותן לך כח לעשות חיל<sup data-n=\"37\">36</sup>, והוא הוא המשגיח בהשגחה פרטית על כל דרכי בנ\"א לתת לאיש כדרכיו וכפרי מעלליו<sup data-n=\"38\">37</sup> ע\"י השרים והכחות המשפיעים שהם כגרזן ביד החוצב<sup data-n=\"39\">38</sup> בו כו', וזהו שא' בשמים ממעל ובארץ מתחת אין עוד פי' שכמו בשמים ממעל גם לפי דבריכם שם משכן כבודו והשגחתו הפרטיות כן גם בארץ מתחת אין עוד כלל כו', פי' אין עוד שבחי' הכח של המזל והשר המשפיע כמו מט\"ט שהוא שרו של עולם<sup data-n=\"40\">39</sup> אינו נחשב כלל אפי' לבחי' עוד שהוא דבר נוסף על עצמותו, כ\"א אין עוד כלל שאין דבר נוסף כלל והיינו כמו שהגרזן אינו דבר נוסף על האומן הפועל ע\"י, והוא מפני שאין להגרזן שום בחירה לעשות או שלא לעשות וכל הבחירה בכלליות עשייתו או בפרטי' בטיב עשיותיו הכל תלוי בידי האומן באופן השגתו וטיב אימן ידיו כו' ולכן אינו מתייחס כלל עשיית הדבר לכלי העושה כ\"א לפועל הפועל ע\"י הכלי, ומ\"ש אין אומן בלא כלים<sup data-n=\"41\">40</sup> אין הכוונה ליחס עצם עשיית האומן להכלי אלא שבלא הכלי אינו יוצא מהעלם אל הגילוי בחי' כח ואימן יד האומן וה\"ה כאילו אינו כו', ועד\"ז יובן בכל פרטי דברים הגשמיות בדצח\"ם עם היות שיש לכל מין בכלל, ולכל או\"א בפרט המין ההוא בפרט, כח וחיות פרטי עכ\"ז איננו דבר נוסף על עצמותו ית' כ\"א הכח הזה עצמו הוא הוי' שזהו כוונת אומרו כי הוי' הוא האלקים ל' רבים<sup data-n=\"42\">41</sup> שכל כחות הרבים בכל מינים הפרטים שנבראו ונוצרו ונעשו בשי\"ב, וכן בכל מין פרטי רבות נבראים בדצח\"מ, הכל הוא הוא הוי' המהווה אותם בתחילת בריאתם וכמאז כן עתה בלתי שום שינוי",[["32","31","<b>וידעת היום</b>: ואתחנן ד, לט. ראה גם לקמן מאמר ד\"ה סמוכים לעד ספ\"ב."],["33","32","<b>פרעה. . מש' אלקים ידע</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370193\" data-slug=\"torah-or\" data-id=\"3901370193\">תו\"א מקץ מג, רע\"א</a>. סידור שער החנוכה ערא, סע\"ב."],["34","33","<b>אלקים הוא לשון כח</b>: ראה שו\"ע אדה\"ז דין כוונת הברכות ס\"ה, ס\"ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540393\" data-slug=\"torat-chaim\" data-id=\"2300540393\">תו\"ח וארא ח\"א עה, ב</a>. וש\"נ."],["35","34","<b>ואת אילי הארץ</b>: יחזקאל יז, יג."],["36","35","<b>אלקים. . שלום פרעה</b>: מקץ מא, טז."],["37","36","<b>שהוא הנותן לך כח לעשות חיל</b>: עקב ח, יח."],["38","37","<b>על כל דרכי. . מעלליו</b>: ירמי' לב, יט."],["39","38","<b>כגרזן ביד החוצב</b>: מו\"נ ח\"ג פכ\"ט. זהר בראשית לו, א. ישעי' י, טו."],["40","39","<b>מט\"ט שהוא שרו של עולם</b>: ראה יבמות טז, ב ובתוס' שם. לקמן מאמר ד\"ה כמגדל דוד צוארך על יד הערה 20. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה רני ושמחי (פיסקאות והנה פי' ולפ\"ז) ובהנחת כ\"ק אדמו\"ר מהורש\"ב שם על יד הערה 13. מאמרי אדה\"א ויקרא ח\"ב ע' תתעא. במדבר ח\"ב ע' תשצ. דברים ח\"ג ע' תשצד."],["41","40","<b>אין אומן בלא כלים</b>: לקמן (בחלק ההנחות) בהנחה כאן בשם רז\"ל — ראה גבול בנימין לר' בנימין הכהן אמשטרדם תפ\"ז ח\"א בתחילתו: אמרו המושלים. פמ\"ג לאו\"ח (בהקדמה) באגרת הראשונה."],["42","41","<b>האלקים ל' רבים</b>: רש\"י וירא כ, יג. וישלח לה, ז. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370252\" data-slug=\"torah-or\" data-id=\"3901370252\">תו\"א וארא נו, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540095\" data-slug=\"torat-chaim\" data-id=\"2300540095\">תו\"ח שם ס, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380212\" data-slug=\"likkutei-torah\" data-id=\"4001380212\">לקו\"ת אמור לא, ג</a>."]]],[2000470087,"כלל, וא\"ת מחי' אלא מהוה<sup data-n=\"43\">42</sup> בכל עת ובכל רגע וכמ\"ש ובטובו מחדש בכי\"ת מע\"ב וכמ\"ש מזה במ\"א שבטובו העצמי שבטבע הטוב להטיב<sup data-n=\"44\">44</sup> הוא מחדש הישינות בכי\"ת כו', ול\"ד בכ\"י אלא בכל עת רק מפני שבכ\"י ניכר קצת כמו התחדשות<sup data-n=\"45\">43</sup> כו' כמ\"ש במ\"א, ולהוסיף ולחזק הדבר שא' תחלה ביאר אח\"כ אין עוד שאין שום עוד היינו דבר נוסף על עצמותו כמו ענין השיתוף<sup data-n=\"46\">45</sup> שנת' במ\"א, שבכדי לשלול גם דבר זה אמר אין עוד כו', וע\"ז היו כל האותות והמופתים שעשו לפרעה ולכל מצרים לאמת אצלם שאין כמוני בכל הארץ, וממילא אין עוד, שהרי הראה להם שאין כח כלל לבחי' מזל מצרים למנוע ולעמוד נגדו ית' חלילה, והוא מפני כי בעצם אינו דבר נוסף כלל כ\"א כמו כלי המחרישה לחרוש בהם, וכלי הגרזן לחצוב בו וכדומה כו', ובראותם כולם ונתאמת אצלם ע\"י גודל המפלות שעשה ה' שפטים בהם ובאלקיהם האמינו כולם לפי שעה ע\"י שראו שמזל מצרים לא הי' יכול להתקומם נגדו ית' להצילם מידם, אין זה כ\"א שאצבע אלקים הוא המושל ושולט בכל, היינו גם בארץ כו', ולא כפי טעותם שעזב כו' כנ\"ל.\n<b>ואמנם</b> הנה הע\"ר רצו אח\"כ לכפור בזה, כאשר בשש משה לרדת מן ההר, והוסיפו סרה שרצו שגם ישראל יסורו, השמיע<sup data-n=\"47\">46</sup> לישראל שהאמת הוא כאשר דימו מתחלה שמנהיגי העולם הם המזלות והשרים שלמעלה כנ\"ל, ומה שלקו המצרים ושלא הי' ביכולת המזל שלהם לעוזרם, ואדרבה שגם באלקיהם עשה שפטים<sup data-n=\"48\">47</sup>, א\"ז מחמת שהוי' הוא המנהיג בהשגחה פרטיות ואין עוד מלבדו, כ\"א מסיבה אחרת, והוא כי יען שיש י\"ב מזלות ברקיע<sup data-n=\"49\">48</sup>, ומזל מצרים הוא מזל טלה<sup data-n=\"50\">49</sup>, וכמ\"ש משה לפרעה הן נזבח את תועבת מצרים לעיניהם<sup data-n=\"51\">50</sup> כו', וכידוע שכל עיקר ענין מצות קרבן פסח<sup data-n=\"52\">51</sup> הי' בשביל זה לשחוט שה<sup data-n=\"53\">52</sup>, ועצם לא תשברו בו<sup data-n=\"54\">53</sup>, ולא תאכלו<sup data-n=\"55\">54</sup> כו' כ\"א ראשו על כרעיו ועל קרבו, להראות איך שאין ממש באלקי מצרים שהוא מזל טלה, ואשר מטעם זה בסיפור מעשה דיוסף עם השבטים אמר ג\"כ כי לא יוכלון המצרים לאכול עם העברים<sup data-n=\"56\">55</sup>, והתחכמו הע\"ר להשמיע לישראל כי מזל שור",[["43","42","<b>וא\"ת מחי' אלא מהוה</b>: ראה שער היחוה\"א פ\"ב ובמ\"מ, הגהות והע\"ק שם. הערה בסה\"מ תש\"ד ע' 20."],["44","44","<b>שבטבע הטוב להטיב</b>: ראה עמק המלך שער שעשועי המלך בתחילתו. שומר אמונים ויכוח שני סי\"ד. שער היחוה\"א פ\"ד ובמ\"מ הגהות והע\"ק לשם. ולהעיר משו\"ת חכם צבי סי\"ח."],["45","43","<b>וכמ\"ש ובטובו מחדש. . התחדשות</b>: ברכת יוצר. ראה גם הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת בראשית כרך ו ע' 2040. סה\"מ תרל\"ו ח\"ב ס\"ע רנא. תרע\"ח ע' קכ. לקמן ע' תטז. וש\"נ."],["46","45","<b>אין עוד. . ענין השיתוף</b>: ראה סה\"מ תרכ\"ט ע' קנה ואילך ובהנסמן שם. סה\"מ מלוקט א' ע' נה."],["47","46","<b>השמיע</b>: כ\"ה בהכת\"י."],["48","47","<b>שגם באלקיהם עשה שפטים</b>: ראה מסעי לג, ד. בא יב, יב."],["49","48","<b>י\"ב מזלות ברקיע</b>: ברכות לב, ב. רמב\"ם הל' יסוה\"ת פ\"ג, ה\"ו."],["50","49","<b>ומזל מצרים. . טלה</b>: ראה זהר פינחס רנ, ב. זח\"א בהשמטות רנו, א (סכ\"ב)."],["51","50","<b>הן נזבח. . לעיניהם</b>: וארא ח, כב."],["52","51","<b>שכל עיקר ענין מצות קרבן פסח</b>: ראה זהר ורע\"מ פינחס רנא, א ואילך."],["53","52","<b>לשחוט שה</b>: בא יב, ו."],["54","53","<b>ועצם. . בו</b>: בא שם, מו."],["55","54","<b>ולא תאכלו</b>: שם שם, ט [ושם: אל תאכלו]."],["56","55","<b>כי לא. . עם העברים</b>: מקץ מג, לב [ושם: את — ראה גם מאמרי אדה\"ז כאן]. ראה תרגום אונקלוס שם. וראה גם לקו\"ש ויחי כרך ה ע' 266 שולי הגליון הב'."]]],[2000470088,"הי' נלחם במצרים עם מזל טלה וגבר עליו, וע\"ד שמצינו שהמזלות נלחמים זע\"ז כמ\"ש בדניאל<sup data-n=\"57\">56</sup> כו', ועד\"ז הי' במצרים, אבל מ\"מ המנהיגים בארץ הם המזלות, ולכן יעצו להם לעשות עגל מסכה והכוונה הוא להכשילם שיעבדו למזל שור מפני כי לפ\"ד הוא גבר על מזל טלה.\n<b>אך</b> הנה הנשים לא רצו בזה ולכן לא השתתפו עמהם ולא נתנו נזמיהם לעשות העגל, והוא מצד שרש נשמותיהם שה\"ע היותם מעלמא דנוקבא, אשר מלכותו בכל משלה<sup data-n=\"58\">56</sup>, בחי' מל' ראש על כל הע\"ש שלמעלה, וידעו והרגישו בנפשותם איך שאין ממש במזלות ושרים הנ\"ל יותר מאשר ידעו והרגישו האנשים, שנשמותיהם מעלמא דדכורא, בחי' ז\"א דאצי' שמרומם ונשגב למעלה מעלה מערך בי\"ע<sup data-n=\"59\">57</sup> לגמרי, אשר ע\"כ אומרים המכחישים בהשגחה פרטיות שעל השמים כבודו של מקום הוא בחי' ז\"א דאצי', ועזב את הארץ היינו בחי' מל'<sup data-n=\"60\">58</sup>, ולכן הם מונים לחמה<sup data-n=\"61\">59</sup> ולא ללבנה מטעם הנ\"ל, ועם היות כי החמה היא למעלה במדרגה מהלבנה היא הנותנת שבזה עצמו הוא טעותם באמרם שעל השמים כבודו בבחי' הרוחניות ואין לו חלק בגשמיות כלל כו', וישראל המונים ללבנה כלומר להיותו אלקי הארץ כמו אלקי השמים מעלה ומטה שוים לפניו ית' שעם היות שהארץ היא למטה במדרגה משמים מ\"מ הנה הוא משפילי לראות בהשגחה פרטיות בשמים ובארץ בשוה ממש, והיינו מפני היותו מגביהי לשבת, שלכן הוא משפילי לראות בשמים ובארץ בשוה כו', כי באמת גם השמים הם בחי' ירידה והשפלה לפניו, אך הנה הנשים לפי ששרשם מבחי' המל' דוקא, ולכן כמו שבלבנה יש מיעוט וריבוי בכל חדש כן הוא עונת הנשים<sup data-n=\"62\">60</sup> בוסתן משלשים יום לשלשים יום שטמאה ומתקדשת, ולכן הם לא קיבלו מהע\"ר בענין העגל כאשר קיבלו האנשים שהם מעלמא דדכורא, ולכן ביו\"ט<sup data-n=\"63\">61</sup> של ר\"ח שהוא יו\"ט של הלבנה ועת התעלותה כו' ניתן לנשים יותר מאנשים מטעם הנ\"ל, והגם כי בכל מ\"ע שהזמן גרמא הנשים פטורות מ\"מ ר\"ח אינו דומה לזה להיות כי שרשם הוא בעלמא דנוקבא כו'.",[["57","56","<b>שהמזלות נלחמים. . בדניאל</b>: ראה שם פ\"י ואילך."],["58","56","<b>מלכותו בכל משלה</b>: ע\"פ תהלים קג, יט."],["59","57","<b>ז\"א. . למעלה מעלה מערך בי\"ע</b>: ראה אוה\"ת כאן ס\"ע א'תתקפז ואילך."],["60","58","<b>הארץ. . מל'</b>: ראה זהר תוספתא בראשית לא, ב."],["61","59","<b>הם מונים לחמה</b>: סוכה כט, א."],["62","60","<b>שבלבנה. . עונת הנשים</b>: ראה אוה\"ת כאן ע' א'תתקפז."],["63","61","<b>ביו\"ט</b>: אוצ\"ל: יו\"ט."]]],[2000470089,"<h3>ואעשך לגוי גדול</h3>\n<b>בס\"ד.</b>\nואעשך לגוי גדול<sup data-n=\"64\">1</sup> ואברכך ואגדלה שמך והי' ברכה<sup data-n=\"65\">2</sup>. וארז\"ל בפב\"ת דפסחים דף קי\"ז ע\"ב א\"ר שמעון בן לקיש ואעשך לגוי גדול זהו שאומרים אלקי אברהם ואברכך זהו שאומרי' אלקי יצחק ואגדלה שמך זהו שאומרי' אלקי יעקב יכול יהו חותמין בכולם ת\"ל והי' ברכה בך חותמין ואין חותמין בכולן. והענין הוא כי הנה נודע ממארז\"ל אר\"ש<sup data-n=\"66\">3</sup> האבות הן הן המרכבה<sup data-n=\"67\">4</sup>, והיינו בחי' מרכבתא עילאה<sup data-n=\"68\">5</sup> דחג\"ת דאצי' כי אברהם הי' מרכבה למדת החסד<sup data-n=\"69\">6</sup> דאצי' ולכן איתא<sup data-n=\"70\">7</sup> בפרד\"ס<sup data-n=\"71\">8</sup> בשם ספר הבהיר<sup data-n=\"72\">9</sup> שאמרה מדת החסד כל ימי היות אברם בארץ<sup data-n=\"73\">10</sup> לא הוצרכתי לעשות מלאכתי שהרי אברם עומד ומשמש במקומי שנא' וישמור משמרתי<sup data-n=\"74\">11</sup> ששמר משמרת מדת החסד וא\"כ הי' במקום מדת החסד דאצי'. ולכן איתא בס' או\"צ<sup data-n=\"75\">12</sup> שאברהם הי' נדיב בין בנפשו בין בגופו בין בממונו, ויצחק הי'",[["64","1","<b>ואעשך לגוי גדול</b>: בספר התולדות של כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"e5\">א</sup> נרשם אודות מאמר זה: ”האבות ה\"ה המרכבה כו' הוי' שבנפש\".\nמאמר זה נאמר גם בפ' לך תרל\"ו ונדפס בסה\"מ תרל\"ה ח\"ב ע' תסה ואילך. והוא הגהות לפ\"א ממאמר ד\"ה זה באוה\"ת לך כרך ד תרצה, ב ואילך. ועם הגהות בסה\"מ תרמ\"ג ע' ט ואילך [ושם הפתיחה: ויאמר גו' לך לך].\nלכמה ענינים המבוארים במאמר זה ראה מאמר ד\"ה ויאמר יהושע ליל ב' דפסח תש\"כ.\nמאמר זה (דשנת תרל\"ו) הובא גם בהמשך מים רבים תרל\"ו ע' טו. וכנראה שהובא גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 643.\nהנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה בשנת תרל\"ו נדפסה בסה\"מ תרל\"ה ח\"ב ע' תקג.\nעל המאמר לא נרשם תאריך אמירתו בבוך זה 2208. אמנם ממה שמאמר זה נאמר לאחר המאמר מפ' נח שנדפס לעיל, וכן מההתחלה משמע שנאמר בפ' לך לך. ראה עוד בנידון מאמר זה שכנראה נאמר בליובאוויטש — לעיל מאמר ד\"ה להבין ענין ר\"ח הערה 1."],["65","2","<b>ואעשך. . והי' ברכה</b>: לך יב, ב."],["66","3","<b>אר\"ש</b>: בב\"ר (שבהערה הבאה) ובסה\"מ תרל\"ה: אמר ר\"ל."],["67","4","<b>האבות הן הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670263\" data-slug=\"torat-chaim\" data-id=\"2300670263\">תו\"ח נח מט, ד</a> ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."],["68","5","<b>האבות. . מרכבתא עילאה</b>: ראה זהר ואתחנן רסב, ב. ועוד."],["69","6","<b>אברהם הי' מרכבה למדת החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם."],["70","7","<b>איתא בפרד\"ס</b>: ראה שער טעם האצילות ש\"ב, פ\"ב. שער הכנויים שכ\"ב, פ\"ד (בשינוי קל). ראה גם סה\"מ תרס\"ג ח\"ב ע' צא."],["71","8","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["72","9","<b>ספר הבהיר</b>: סקצ\"א (בשינוי קל). זח\"א בהשמטות רסד, ריש ע\"ב."],["73","10","<b>בארץ</b>: וכ\"ה בשער הכנויים שם לקמן מאמר ד\"ה גור ארי' יהודה על יד הערה 51 לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 643 ועוד.\nאמנם לקמן (בחלק ההנחות) הנחה ד\"ה כמים הפנים על יד הערה 30 סה\"מ תרכ\"ז ע' קסא: בעולם. וכ\"ה בס' הבהיר בזח\"א ובפרדס שער טעם האצילות."],["74","11","<b>וישמור משמרתי</b>: תולדות כו, ה."],["75","12","<b>בס' או\"צ</b>: באוה\"ת וירא ע' 180 תצוה\nע' א'תשכ תזריע ע' תקכא<sup data-n=\"e6\">ב</sup> ועוד: אורחות צדיקים. באוה\"ת ש\"ש ע' א'תקכד: (ארחות הצדיקים). ישעי' ע' קכח: (הארחות צדיקי'). סה\"מ תרל\"ב ח\"א ע' ז תרל\"ה ח\"ב ע' תפב תרפ\"ה ע' רסח<sup data-n=\"e7\">ג</sup> מאמר ד\"ה יהי ה\"א עמנו תר\"צ: ארחות צדיקים [במהדורת זאלקווי תקס\"ד: ”ארחות צדיקים\"]. בסה\"מ תרמ\"ח ע' קצב בשם: אורחות חיים. בסה\"מ עזר\"ת ע' נז: באוצ\"ח (אוצ\"ל: באוח\"צ). לקמן במאמר ד\"ה גור ארי' יהודה ספ\"ב לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה והנה כובע על יד הערה 51 מציין: בשער י\"ז הוא שער הנדיבות.\n\n<b>א</b>  קה\"ת תש\"ז – ברשימת מאמרי תרל\"ו – ריש ע' 43.\n\n<b>ב</b>  נדפס גם בסה\"מ תרל\"ה ח\"א ע' קצט.\n\n<b>ג</b>  ויש להוסיפו במפתח שמות ספרים שם ע' תז. ולעיל שם ע' מז ואי' בספרי' — ויש להוסיפו (שם ע' תז) בערך ספרים."]]],[2000470090,"מרכבה למדת הגבורה<sup data-n=\"76\">13</sup> ולכן נא' ופחד יצחק הי' לי<sup data-n=\"77\">14</sup>, ונמצא שכינה ליצחק ש' אחד כמו למדת הגבורה שכמו מדת הגבורה קורי' מקובלי' הראשוני' בשם מדת הפחד<sup data-n=\"78\">15</sup> כן יצחק נק' פחד שז\"ע אומרו פחד יצחק, ויעקב הי' מרכבה למדת הת\"ת<sup data-n=\"79\">16</sup> לכן כמו שהת\"ת כולל ב' בחי' דחו\"ג כן יעקב עשה לו מקל לבנה לח ולוז וערמון כמ\"ש ויקח לו יעקב<sup data-n=\"80\">17</sup> מקל לבנה לח ולוז וערמון ויפצל בהן פצלות לבנות פי' שלקח לו מדה זו שכולל חו\"ג להיות מרכבה לה להיות במקומה, ולכן בירך יעקב את בניו כשירדו למצרים ברחמים<sup data-n=\"81\">18</sup> כמ\"ש ואל שדי יתן לכם רחמים<sup data-n=\"82\">19</sup> להיות כי כל ימיו הי' עבודתו בבחי' זו עד שנתאחד בה כו', וא\"כ מה שאומרי' אלקי אברהם היינו בחי' שלמעלה מהחסד דאצי' והוא בחי' חכמה עילאה דאצי', וכמ\"ש בזהר ח\"ב פ' בשלח דנ\"ה ע\"ב אלקי אבי וארוממנהו<sup data-n=\"83\">20</sup> כמד\"א אלקי אברהם וכ' המק\"מ פי' אבא שהוא אלקה של חסד, א\"ר יוסי אי הכי אמאי וארוממנהו דהא אלקי אברהם לעילא הוא, פי' כי הוא בח\"ע וא\"צ הרמה, א\"ל אפי' הכי אצטריך, והיינו להעלותו לבחי' אריך כו', נשמע דאלקי אברהם הוא בחי' אוא\"ס המלובש בחכ' עילאה דאצי', ולכן מקדימין שבח זה לשבח האל הגדול הגבור שהוא בהתפשטות ההמשכה במדות חג\"ת, אבל אלקי אברהם הוא בחכ', וא\"כ זה שיתעלה אברהם כ\"כ שיהי' מרכבה עילאה זהו ואעשך לגוי גדול כו', ועי\"ז זכה לעמוד<sup data-n=\"84\">*21</sup> אומה שנק' גוי גדול<sup data-n=\"85\">21</sup>.",[["76","13","<b>ויצחק הי' מרכבה למדת הגבורה</b>: ראה פרדס שער הכנויים שם. מאמרי אדה\"ז שם ובהנסמן במ\"מ לשם."],["77","14","<b>ופחד יצחק הי' לי</b>: ויצא לא, מב."],["78","15","<b>מדת הגבורה. . הפחד</b>: ראה ס' הבהיר סק\"צ. פרדס שער עה\"כ שכ\"ג, פי\"ז מערכת פחד. מאו\"א מערכת פחד סל\"ט וביאיר נתיב שם."],["79","16","<b>ויעקב הי' מרכבה למדת הת\"ת</b>: ראה זהר סתרי תורה ויצא קנז, ב. ח\"ג תוספות שב, א. פרדס שער הכנויים שם. לקמן המשך זאת חנוכת המזבח פ\"כ. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אל יתהלל על יד הערה 19. לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 644. ד\"ה עטרת תפארת שיבה על יד הערה 96. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי בחגוי הסלע על יד הערה 129. ד\"ה אשריכם זורעי על כל מים על יד הערה 38. ד\"ה עטרת תפארת שיבה על יד הערה 75."],["80","17","<b>ויקח לו יעקב</b>: ויצא ל, לז. ראה זהר ויצא קסא, ב. אוה\"ת ויצא רכא, ב (ביאוה\"ז להצ\"צ כרך ב ס\"ע תשב). סה\"מ תרמ\"ד ע' קצ. תרע\"ח ע' קו. תרצ\"ט ע' 108."],["81","18","<b>יעקב. . ברחמים</b>: ראה זהר לך פז, ב. לקמן המשך זאת חנוכת המזבח פ\"כ. מאמרי אדה\"א בראשית ע' קנו. וש\"נ."],["82","19","<b>ואל שדי יתן לכם רחמים</b>: מקץ מג, יד."],["83","20","<b>אלקי אבי וארוממנהו</b>: בשלח טו, ב."],["84","*21","<b>לעמוד</b>: אוצ\"ל: להעמיד."],["85","21","<b>גוי גדול</b>: נסמן בסמוך בהערה 23."]]],[2000470091,"<b>וביאור</b> ענין לגוי גדול, הנה ארז\"ל במד\"ר<sup data-n=\"86\">22</sup> עפ\"ז ואעשך לגוי גדול אותה אומה דכתי' בה ומי גוי גדול<sup data-n=\"87\">23</sup> ממך אני מעמיד אותה, שנק' גדולי' ע\"ש גדול הוי' ומהולל מאד<sup data-n=\"88\">24</sup> בעיר אלקינו, וכתי' כי חלק הוי' עמו<sup data-n=\"89\">25</sup> שיש בכאו\"א ש' הוי'<sup data-n=\"90\">26</sup> ולכן נק' גדול ע\"ש גדול הוי' כו' ומקורם אברהם חסד עליון. והענין הוא דהנה ארז\"ל ברבות ע\"פ ויעש אברהם משתה גדול<sup data-n=\"91\">27</sup>, גדול העולמי' הי' שם, וכן בפ' איננו גדול<sup data-n=\"92\">28</sup> פי' במד\"ר וישב פ' פ\"ז<sup data-n=\"93\">29</sup> על גדול הוי' ומהולל מאד ע' במד\"ר שם ובמת\"כ שם, וא\"כ פי' גוי גדול שגדולת הוי' הוא גם בחלק הוי' עמו, ולכן כל רואיהם יכירום<sup data-n=\"94\">30</sup> ע\"ד וראו כו' כי ש' הוי' נק' עליך<sup data-n=\"95\">31</sup>. וביאור ענין ש' הוי' שיש בכאו\"א<sup data-n=\"96\">32</sup> מישראל<sup data-n=\"97\">33</sup> הנה היו\"ד הוא בחי' הביטול שלמעלה מן החכ' ולמעלה משכל המושג שאין רצונו להיות נפרד מאלקות בלי שום טו\"ד ומה שעושה איזהו דברים אשר לא כדת נדמה לו שעי\"ז לא יהי' נפרד מאחדותו<sup data-n=\"98\">34</sup> ית', אבל אם הי' יודע שעי\"ז יפרד מאחדותו ית' לא הי' רוצה בשו\"א בעולם שהרי גם הנשים והקטנים וקלי הדעת אינם רוצים ליפרד מאחדותו ית' שזהו מפני שמושרש בכ\"י בירושה לנו מאבותינו הביטול שלמעלה מן הטו\"ד<sup data-n=\"99\">35</sup> כלל, והה' הוא בחי' התבוננות באורך ורוחב באריכות ההתבוננות איך שמה רבו מעשיך ה'<sup data-n=\"100\">36</sup> הוא בחי' ריבוי התהוות הנבראי' שנתהוו",[["86","22","<b>במד\"ר</b>: ראה ב\"ר פל\"ט, יא. במדב\"ר פי\"א, ב."],["87","23","<b>ומי גוי גדול</b>: ואתחנן ד, ח. וכ\"ה בסה\"מ תרמ\"ג כאן ע' יג. אבל במדרש שם הובא הכתוב כי מי גוי גדול ואתחנן ד, ז. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316500158\" data-slug=\"or-hatorah-hb\" data-id=\"8316500158\">אוה\"ת לך ח\"א ס\"ע 158</a>."],["88","24","<b>גדול הוי' ומהולל מאד</b>: תהלים מח, ב."],["89","25","<b>כי חלק הוי' עמו</b>: האזינו לב, ט. ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה כמים הפנים סוף פיסקא א. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"ד ד\"ה וככל."],["90","26","<b>שיש בכאו\"א ש' הוי'</b>: ראה גם סה\"מ תרל\"ה ח\"ב כאן ע' תסו הערה 18. תרכ\"ט ע' רטז. וש\"נ. מאמרי אדה\"א שמות ח\"ב ע' תפב. וש\"נ. ש\"א יח, ב ובהערה 24. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"ה. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת פיסקא הנה יו\"ד. (בחלק ההנחות) הנחה ד\"ה שובה ישראל [הא' והב' על יד הערות 131. 134]."],["91","27","<b>ויעש אברהם משתה גדול</b>: וירא כא, ח. ראה ב\"ר פנ\"ג, י."],["92","28","<b>איננו גדול</b>: וישב לט, ט."],["93","29","<b>פ' פ\"ז</b>: ס\"ה. ראה גם אוה\"ת (יהל אור) תהלים ע' קפב."],["94","30","<b>כל רואיהם יכירום</b>: ישעי' סא, ט."],["95","31","<b>וראו. . נק' עליך</b>: תבוא כח, י."],["96","32","<b>ש' הוי' שיש בכאו\"א</b>: בהבא לקמן ראה לקו\"ת ר\"פ ראה. סה\"מ תרל\"ה ח\"ב כאן ע' תסז הערה 25. לקמן המשך יונתי פ\"ד."],["97","33","<b>מישראל</b>: קודם תיבה זו נרשם כנראה בגוכתי\"ק כ\"ק אדמו\"ר: / [וכן הוא להלן כמצויין שם]. וכנראה הכוונה שכאן נמצא הוספה בסה\"מ תרמ\"ג כאן ע' י שו\"ה ענין — ישראל."],["98","34","<b>שאין רצונו להיות. . נפרד מאחדותו</b>: ראה תניא פי\"ד. פי\"ח. פכ\"ד. פכ\"ה. תו\"א מג\"א צט, ב<sup data-n=\"e8\">ד</sup>. סה\"מ תרנ\"ח ע' רט. השי\"ת ע' 114 ואילך."],["99","35","<b>בירושה לנו. . שלמעלה מן הטו\"ד</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>. פי\"ט."],["100","36","<b>מה רבו מעשיך ה'</b>: תהלים קד, כד. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370252\" data-slug=\"torah-or\" data-id=\"3901370252\">תו\"א וארא נו, ב</a>. סה\"מ תרכ\"ו ריש ע' קה. תרמ\"ד מהדורת תשס\"ב ע' שיג. וש\"נ. לקמן (בחלק ההנחות) הנחה ד\"ה ויאמר משה על יד הערה 41 ואילך. לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 118 ואילך. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת פיסקא הנה יו\"ד. (ראה גם הנחה ד\"ה יפה שעה הג' על יד הערה 56). סה\"מ תשי\"א ע' 139.\n\n<b>ד</b>  הועתק לקמן בהמשך מצה זו פכ\"ו על יד הערה 854."]]],[2000470092,"ריבוי בחי' דומם<sup data-n=\"101\">37</sup> כמו מן האבנים הפשוטי' עד אבנים טובות שמאירים בזוהר ניצוצים שנתזי' מהם שיש ריבוי מינים בהם שכל אחד מובדל מזולתו הן באיכותו והן בזיו זוהרו כו', וכן בצומח יש ריבוי מינים אילנות ודשאים וצמחי' רבים מספר עצום מאד<sup data-n=\"102\">38</sup>, וכל מין נבדל מזולתו במראיתו וטעמו ופעולתו, וכן בחי יש ריבוי מינים מאד בהמות חיות ועופות ושקצים ורמשים, וכל א' מובדל מזולתו בטבעו והנהגתו וציורו כו', וכן באדם<sup data-n=\"103\">39</sup> יש כמה וכמה מינים וכל אחד טבעו משונה מזולתו ובציורו אין אחד מהם דומה לחבירו<sup data-n=\"104\">40</sup> הגם כי כל אחד נטבע בחותם של אדה\"ר כמארז\"ל במשנה בספ\"ג<sup data-n=\"105\">41</sup> דסנהדרין, ועז\"נ מה רבו מעשיך ה', וכתי' מה גדלו מעשיך ה'<sup data-n=\"106\">42</sup> שקאי על נבראי' הגדולים מלאכי' שכלים נבדלים<sup data-n=\"107\">43</sup> שמלאך בשליש העולם עומד<sup data-n=\"108\">44</sup>, והשמש והירח וכוכבי' ומזלות וגלגלי' שהם נבראי' הגדולי' וג\"כ כ\"א מובדל מזולתו בכל פרטי פרטיהם וכחותיהם אשר ניתן להם ועבודתם משונה זמ\"ז ועלי' נא' מה גדלו מעשיך ה', וכלליות כולם נבראו מאות א' בהבראם בה' בראם<sup data-n=\"109\">45</sup>, וכלליות עוה\"ב הוא ג\"כ מאות א' ביו\"ד נברא העוה\"ב, וכמארז\"ל ע\"פ כי בי\"ה הוי' צור עולמים<sup data-n=\"110\">46</sup> ביו\"ד נברא העוה\"ב ובה' נברא העוה\"ז שדעת לנבון נקל",[["101","37","<b>ריבוי בחי' דומם</b>: ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה מי כה\"א על יד הערה 40. לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 124. מאמר ד\"ה וזהו שרש יונתי על יד הערה 32. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתמג<sup data-n=\"e9\">ה</sup>. סה\"מ תשי\"א שם."],["102","38","<b>בצומח. . ודשאים. . מספר עצום מאד</b>: ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 125. ד\"ה וזהו שרש יונתי על יד הערה 34. מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע רכו. תקס\"ה שם. שע\"ת ע, א ובהערה 13. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540133\" data-slug=\"torat-chaim\" data-id=\"2300540133\">תו\"ח וארא ח\"א ס, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550078\" data-slug=\"torat-chaim\" data-id=\"2300550078\">יתרו ח\"ב ערה, ג</a>."],["103","39","<b>ריבוי מינים מאד בהמות. . וכן באדם</b>: ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי ד\"ה וזהו שרש יונתי מאמרי אדה\"ז תקס\"ה [ותו\"ח יתרו] שם. (וראה גם בנוגע לאדם (לקמן בחלק ההנחות) הנחה ד\"ה ויאמר משה פיסקא וכמו שנת\"ל]."],["104","40","<b>אין אחד מהם דומה לחבירו</b>: נסמן בהערה הבאה. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ס\"ע תתקטז ואילך."],["105","41","<b>בספ\"ג</b>: וכ\"ה בסה\"מ תרמ\"ג כאן ע' יא. אוצ\"ל: בספ\"ד (סנהדרין לז, א)."],["106","42","<b>מה גדלו מעשיך ה'</b>: תהלים צב, ו. ראה תו\"א שם. סה\"מ תרכ\"ו ריש ע' קה. לקמן (בחלק ההנחות) הנחה ד\"ה ויאמר משה על יד הערה 24 ואילך. לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 119 ואילך. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת פיסקא הנה יו\"ד. סה\"מ תשי\"א שם."],["107","43","<b>מלאכים שכלים נבדלים</b>: ראה מו\"נ ח\"ב פ\"ב-פ\"ו. וראה שם ח\"א פמ\"ט. רמב\"ם הל' יסודי התורה פ\"ב, ה\"ג ובפירוש שם. ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ז. סידור שער הק\"ש פג, סע\"ד ואילך. שם תפלת ר\"ה רלו, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380492\" data-slug=\"likkutei-torah\" data-id=\"4001380492\">לקו\"ת שלח מה, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380496\" data-slug=\"likkutei-torah\" data-id=\"4001380496\">מו, א</a>. ביאוה\"ז בשלח מ, רע\"ג. מאמרי אדה\"א שמות ח\"א ע' קט. במדבר ח\"ב ע' תתס. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת מסעי ע' א'שצח</a>. ספר החקירה ע' יג. לקמן המשך זאת חנוכת המזבח רפ\"ג."],["108","44","<b>שמלאך בשליש העולם עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. מורה נבוכים ח\"ב, פ\"י. לקו\"ת נצבים<sup data-n=\"e10\">ו</sup> עד, סע\"ד ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ו ע' ק ”שהוא ק\"ס שנה\". סידור שער החנוכה רעו, א ”קס\"ו וב\"ש שנה\"."],["109","45","<b>בהבראם בה' בראם</b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב. פרש\"י עה\"פ."],["110","46","<b>כי בי\"ה הוי' צור עולמים</b>: ישעי' כו, ד. ראה מנחות ופרש\"י הנ\"ל.\n\n<b>ה</b>  נדפס גם ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550078\" data-slug=\"torat-chaim\" data-id=\"2300550078\">תו\"ח יתרו ח\"ב ערה, ג</a>.\n\n<b>ו</b>  ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי ובהערה 122."]]],[2000470093,"שגם באדם שהוא נברא פרטי אינו תופס מקום כלל ב' אותיות<sup data-n=\"111\">47</sup> נגד מה שיוכל לדבר אפי' ביום אחד וכ\"ש נגד כלליות הדיבור של האדם, וכ\"ש לגבי אוא\"ס ב\"ה הסוכ\"ע וממכ\"ע<sup data-n=\"112\">48</sup>, אשר גם בחי' נשגב הוא אוא\"ס הסוכ\"ע הוא ג\"כ רק שמו לבדו<sup data-n=\"113\">49</sup> כו', וע\"י התבוננות זו יבא לדבקה בו ית' כי למה יחפוץ במה שנתהוה מב' אותיות ולמה לא ירצה יותר לאוא\"ס ב\"ה עצומ\"ה שבב' אותיות ברא הכל וכתי' כי עמך מקו\"ח<sup data-n=\"114\">50</sup> שמקור החיים ומקור התענוגים הוא עמך שבטל וטפל לך ובמה יחפוץ יותר אם בדבר הטפל אם במי שנטפל לו כו', וכאשר יאריך הרבה בהתבוננו' זו בהעמקת הדעת יבין גם שכלו הגשמי איך שהוא האמת באמת לאמיתו ויבא לדבקה בו בדיבוק אמיתי וקשר חזק בל תמוט, וגם נפשו הבהמית לא ימנע אותו מאחר שגם ע\"פ שכל אנושי שהוא מקור למקור לשכל המדות דכח המתאוה דיצה\"ר יבין בטוב טעם ודעת איך שמה טוב ומה נעים<sup data-n=\"115\">51</sup> ההתדבקות באלקי' חיים ומלך עולם<sup data-n=\"116\">52</sup>, וזשא\"ה ואתם הדבקי'<sup data-n=\"117\">53</sup> בה' אלקיכם חיים כולכם היום פי' שע\"י ההתדבקות לאלקות תהי' כולכם חיים בחיי החיים גם בבחי' היום שהוא בחי' היום לעשותם<sup data-n=\"118\">54</sup> בעוה\"ז הגשמי, ולא יחי' בחיי בשרים ושכל הגשמי כמו שהוא בלי בחי' התבוננות הנ\"ל שממשיך לאדם לפנות אחר ההבל ויהבלו לפנות כל היום וכל הלילה אחרי תאוות גשמים, וכל עסקו כל היום להיות בקנאה עבור התאוה והכבוד שהם מוציאי' את האדם מן העולם<sup data-n=\"119\">55</sup> היפך בחי' החיים הנ\"ל, או מי שהוא רודף לבצעו כל היום הוא ג\"כ כנ\"ל בכדי שיוכל להשיג מה שלבו מתאוה או כבוד המדומה או שארי תאוות או שמתאווה לעצם הממון שיש מי שהוא משוקע בתאוה זו ג\"כ לאהוב עצם המעות ולא הבכן שיוצא מזה שהרי הוא לא יתאוה כלל לקנות לעצמו חפצים יקרים או לפזר עבור להשיג כבוד יותר גדול מהראוי מפני כי חס על ממונו, וגם הנצרך לגופו ג\"כ יקמץ בזה מפני שממונו חביב עליו מגופו<sup data-n=\"120\">56</sup>, וכ\"ש לעשות איזה מצוה שעולה בדמים יקרים שיפלא בעיניו האיך יוותר ממונו אשר זהו כל חיותו ותענוגו לפי הסכמת שכלו המשוקע בתאוות גשמיות ורצונות זרים, לא זהו הדרך אשר ישכון בה אור הוי' ונמשל כבהמות נדמו<sup data-n=\"121\">57</sup> שהלא הבהמה היא<sup data-n=\"122\">58</sup> שרודפת אחר מאכל וכדומה מבלי",[["111","47","<b>באדם. . ב' אותיות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/tanya/3401310025\" data-slug=\"tanya\" data-id=\"3401310025\">תניא פ\"כ</a> ואילך."],["112","48","<b>הסוכ\"ע וממכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["113","49","<b>נשגב. . שמו לבדו</b>: תהלים קמח, יג. ראה לקמן המשך מצה זו פכ\"ו ובהערה 856."],["114","50","<b>כי עמך מקו\"ח</b>: תהלים לו, י. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380213\" data-slug=\"likkutei-torah\" data-id=\"4001380213\">לקו\"ת אמור לא, ד</a>. (הוספות ויקרא) נא, ד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540522\" data-slug=\"torat-chaim\" data-id=\"2300540522\">תו\"ח שמות ח\"א ה, ג</a>. וש\"נ. לקמן מאמר ד\"ה סמוכים לעד פ\"ב. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה צאינה וראינה על יד הערה 87. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פי\"ד. ד\"ה עטרת תפארת שיבה על יד הערה 66. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אני לדודי הא' על יד הערה 29. ד\"ה עטרת תפארת שיבה על יד הערה 56. (בחלק ההנחות) הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 50. ד\"ה אני לדודי הא' על יד הערה 28."],["115","51","<b>שמה טוב ומה נעים</b>: תהלים קלג, א."],["116","52","<b>באלקי' חיים ומלך עולם</b>: ברכת יוצר. ירמי' י, י."],["117","53","<b>ואתם הדבקי'</b>: ואתחנן ד, ד. ראה גם אדר\"נ ספל\"ד. סה\"מ תרל\"ח ע' רפח ובהערה 41."],["118","54","<b>היום לעשותם</b>: ואתחנן ז, יא."],["119","55","<b>בקנאה. . התאוה והכבוד. . העולם</b>: אבות פ\"ד, מכ\"א."],["120","56","<b>שממונו חביב עליו מגופו</b>: ברכות סא, ב. ספרי ואתחנן ו, ה."],["121","57","<b>ונמשל כבהמות נדמו</b>: תהלים מט, יג. כא."],["122","58","<b>הוא</b>: בסה\"מ תרל\"ה כאן: היא."]]],[2000470094,"השיג יותר והאדם הרודף אחר דברים שטוב לו לחיי גופו או כבודו ה\"ה גרוע מהבהמה שהרי לבהמה לא ניתן שכל יותר שתשכיל איזה דבר יותר ולא יש בה נפה\"א שישכיל דבר מה בהתבוננות הבורא יחיד ומיוחד, אבל האדם אשר ניתן לו להשכיל דבר חכמה בהתבוננות אלקות ומניח זאת לרדוף אחר ההבל כבהמה הרי הוא גרוע יותר הרבה שה\"ה אדם ועושה מעשה בהמה, ואוי לו לנפשו שירדה פלאים מתחת כסה\"כ לבוא בגוף הגשמי שירידתה היא צורך עלי'<sup data-n=\"123\">59</sup>, וזה שנמשך אחר ההבל לא די לו שלא תיקן מאומה הרי הורידה ממקום כבודה שהיתה עומדת באהוי\"ר כמ\"ש חי ה' אשר עמדתי לפניו<sup data-n=\"124\">60</sup> שענין העמידה הוא כמ\"ש שרפי' עומדים<sup data-n=\"125\">61</sup> שעמידתם הוא בביטול, והגם כי לא יש שם מונע מ\"מ ה\"ה כמו שצריך להיות, אבל כשירדה בגוף ונמשכה אחר ההבל הרי ירדה ממהותה לגמרי, וצלל במים אדירים שהי' יכול להתדבק בבחי' אדיר במרום ה'<sup data-n=\"126\">63</sup> והעלה בידו חרס<sup data-n=\"127\">62</sup>, ולא עוד אלא שעי\"ז נעשה כתמים בנפשו שצריכה זיכוך וטהרה לרפאותה מחוליתה ע\"י גיהנם וכף הקלע<sup data-n=\"128\">64</sup> עד שמזככי' אותה, והלואי תהי' השבה למעליותא כנתינתה עכ\"פ שטהורה היא עכ\"פ כמאמר נשמה שנתת בי טהורה<sup data-n=\"129\">65</sup>, והוא עשה בה כתמים ופצעים רבים מכף ראשה עד רגלה בכל ציור קומה הן בשכל והן במדות אין בה מתום<sup data-n=\"130\">66</sup> כלל, וכאשר יעמיק דעת גודל עוצם העלאתה ע\"י התבוננות והעמקת הדעת כנ\"ל נגד ירידתה עשר מעלות אחורנית<sup data-n=\"131\">67</sup> כאשר נמשכה אחר ההבל יעורר ר\"ר על נפשו איך שירדה פלאים כו' והוא רחום יכפר עון<sup data-n=\"132\">68</sup> להוציאה מחוליתה ושתבוא לדבקה בו ית' אוא\"ס חיי החיים<sup data-n=\"133\">69</sup> ע\"י התבוננות הנ\"ל.\n<b>והוא\"ו</b> הוא בחי' מדות ע\"ד דכתי' לך ה' הגדולה והגבורה<sup data-n=\"134\">70</sup> והת\"ת והנצח וההוד כי כל בשמים ובארץ לך ה' הממלכה, והיינו שכל מדותיו יהי' בבחי' לך היינו בחי' אוא\"ס דלאו מכל אינון מדות<sup data-n=\"135\">71</sup> איהו כלל, והיינו שיהי' מדת חסדו לה'",[["123","59","<b>שירידתה היא צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["124","60","<b>חי ה' אשר עמדתי לפניו</b>: מלכים-ב ה, טז. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370281\" data-slug=\"torah-or\" data-id=\"3901370281\">תו\"א בשלח סב, סע\"ד</a>. לקמן המשך זאת חנוכת המזבח פ\"א. מאמר ד\"ה סמכוני באשישות על יד הערה 34. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה זאת חנוכת המזבח ובהערה 18. (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 42. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"ו. פ\"ח. פי\"ד. סה\"מ תרכ\"ט ע' רלה. תרל\"ח ע' ת. וש\"נ. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' נט ובהנסמן שם."],["125","61","<b>שרפי' עומדים</b>: ישעי' ו, ב. ראה סוטה לט, א (צויין אליו ב) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380390\" data-slug=\"likkutei-torah\" data-id=\"4001380390\">לקו\"ת נשא כ, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380398\" data-slug=\"likkutei-torah\" data-id=\"4001380398\">כב, ג</a>."],["126","63","<b>אדיר במרום ה'</b>: תהלים צג, ד."],["127","62","<b>וצלל במים אדירים. . והעלה בידו חרס</b>: ראה בבא קמא צא, סע\"א. רמב\"ם הל' קדוש החדש פי\"א, ה\"ב."],["128","64","<b>גיהנם וכף הקלע</b>: ראה ש\"א ו, א ובהנסמן במ\"מ לשם."],["129","65","<b>נשמה שנתת בי טהורה</b>: ברכת אלקי נשמה."],["130","66","<b>מכף ראשה עד רגלה. . אין בה מתום</b>: ועד\"ז הובא לקמן בהמשך זאת חנוכת המזבח על יד הערה 376. ע\"פ ישעי' א, ו."],["131","67","<b>עשר מעלות אחורנית</b>: ע\"פ מלכים-ב כ, י. יא. ישעי' לח, ח."],["132","68","<b>והוא רחום יכפר עון</b>: תהלים עח, לח."],["133","69","<b>חיי החיים</b>: יומא עא, א."],["134","70","<b>לך ה' הגדולה והגבורה</b>: דבהי\"א כט, יא."],["135","71","<b>דלאו מכל אינון מדות</b>: ת\"ז בהקדמה יז, ב."]]],[2000470095,"להרבות בצדקה וכמו שלמעלה נא' מכלכל חיים בחסד<sup data-n=\"136\">72</sup> כן יהי' הוא משפיע לדל להחיות נפשו ע\"י השפעת מדת חסדו, ובחי'<sup data-n=\"137\">73</sup> הגבורה הוא להיות בבחי' איזהו גבור<sup data-n=\"138\">74</sup> הכובש את יצרו להיות סור מרע ועשה טוב<sup data-n=\"139\">75</sup> ולהגביר על יצרו להיות גומל לחייבים טובות<sup data-n=\"140\">76</sup> כו', ומדת<sup data-n=\"141\">77</sup> הת\"ת הוא לבוא לבחי' רחמים לרחם על הבריות ולהיות טוב לשמים וטוב לבריות<sup data-n=\"142\">78</sup> כו'. והנצח<sup data-n=\"143\">79</sup> הוא בבחי'<sup data-n=\"144\">80</sup> עבודה כל היום להיות נשאר הסכם חזק אצלו כל היום בל תמוט כי הרי לא יוכל להיות בהתבוננות כל היום כ\"א בעת תפלה או בעת מן העתים שיבחר להיות בהתבוננו' ועל כל היום צ\"ל הסכם חזק על בחי' סור מרע ועשה טוב, והוד הוא בחי' ההודאה שהרי בשכלו הדל לא יכול להבין הכל ולכן צריך להודות שכן הוא וכמ\"ש כי לך טוב להודות<sup data-n=\"145\">81</sup> וכתי' טוב להודות לה'<sup data-n=\"146\">82</sup>, כי כל בשוב\"א הוא בחי' ההתקשרות כנודע שבחי' יסוד הוא בחי' התקשרות<sup data-n=\"147\">83</sup>, לך ה' הממלכה הוא בחי' קעומ\"ש שמקבל ע\"ע עול מלכותו ברצון שזהו הקדמה לעול מצות קבלו מלכותי ואח\"כ קבלו גזרותי<sup data-n=\"148\">84</sup> וכמארז\"ל במשנה למה קדמה שמע לוהא\"ש<sup data-n=\"149\">85</sup> כדי שיקבל עליו עומ\"ש ואח\"כ יקבל עליו עול מצות, והה' אחרונה דש' הוי' הוא בחי' צדקה כי צדקה הוא צדק ה'<sup data-n=\"150\">86</sup>, כי על הצדקה כתי' וצדקה כנחל איתן פי' שעי\"ז זוכה להמשיך מבחי' איתן שהוא כמשמעו קשה<sup data-n=\"151\">87</sup> למעלה מן השכל המושג, ולכן קודם התפלה צ\"ל כמארז\"ל ר\"א יהיב פרוטה לעני<sup data-n=\"152\">88</sup> והדר מצלי ע\"ש אני בצדק אחזה פניך<sup data-n=\"153\">89</sup> שע\"י הקדמת הצדקה עי\"ז זוכה לבוא בתפלה ע\"י ההתבוננו' לבחי' איתן קוש\"י ובחי' יו\"ד הנ\"ל שהוא ג\"כ למעלה משכל המושג עדיין כנ\"ל, וזהו שנק' כי<sup data-n=\"154\">90</sup> גוי גדול ע\"ש בחי' גדול הוי' שנמצא בכאו\"א מישראל לפי ערכו כו', וזהו ואעשך לגוי גדול אותה אומה דכתי' בה ומי גוי גדול ממך אני",[["136","72","<b>מכלכל חיים בחסד</b>: נוסח שמו\"ע."],["137","73","<b>ובחי'</b>: קודם תיבה זו נרשם [ראה לעיל הערה 33]: / וי\"ל — ראה סה\"מ תרמ\"ג כאן ע' יב שו\"ה לדל — וי\"ל."],["138","74","<b>איזהו גבור</b>: אבות פ\"ד, מ\"א."],["139","75","<b>סומ\"ר ועש\"ט</b>: תהלים לד, טו."],["140","76","<b>גומל לחייבים טובות</b>: ע\"פ ברכת הגומל."],["141","77","<b>ומדת</b>: קודם תיבה זו נרשם [ראה לעיל הערה 33]: / והנה — ראה סה\"מ תרמ\"ג כאן ע' יב שו\"ה ועש\"ט — והנה."],["142","78","<b>טוב לשמים וטוב לבריות</b>: קדושין מ, א. ראה סה\"מ תרל\"ח ע' כט ואילך."],["143","79","<b>והנצח</b>: קודם תיבה זו נרשם [ראה לעיל הערה 33]: / ובעבודה — ראה סה\"מ תרמ\"ג כאן ע' יב שו\"ה ולהיות — ובעבודה."],["144","80","<b>בבחי'</b>: בסה\"מ תרמ\"ג כאן ע' יג: בחי'."],["145","81","<b>כי לך טוב להודות</b>: סוף הלל (יהללוך)."],["146","82","<b>טוב להודות לה'</b>: תהלים צב, ב."],["147","83","<b>יסוד. . התקשרות</b>: ראה אגה\"ק סט\"ו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680302\" data-slug=\"torat-chaim\" data-id=\"2300680302\">תו\"ח וישב רט, ב</a> ובהערה 25."],["148","84","<b>קבלו מלכותי ואח\"כ קבלו גזרותי</b>: ראה מכילתא ויל\"ש יתרו כ, ג (הובא ברמב\"ן שם ב). תו\"כ ורש\"י אחרי יח, ב. ראה גם סה\"מ תרכ\"ט ע' רנג. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300031084\" data-slug=\"likkutei-sichot\" data-id=\"1300031084\">לקו\"ש אחרי כרך ג' ע' 84</a> ואילך."],["149","85","<b>למה קדמה שמע לוהא\"ש</b>: ראה ברכות פ\"ב, מ\"ב (יג, א). ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה והנה כובע על יד הערה 76 ואילך."],["150","86","<b>צדקה הוא צדק ה'</b>: ראה זהר אחרי עב, א. מאמרי אדה\"א דברים ח\"ב ע' שצד. וש\"נ. שמות ח\"א ע' קכה. וש\"נ. סה\"מ תרל\"ה ח\"ב כאן הערה 58. לקמן המשך מצה זו פכ\"ד על יד הערה 720."],["151","87","<b>וצדקה כנחל איתן. . קשה</b>: עמוס ה, כד. סוטה מו, סע\"א. ראה לעיל הערה 32."],["152","88","<b>ר\"א יהיב פרוטה לעני</b>: ב\"ב י, א. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316610216\" data-slug=\"or-hatorah-hb\" data-id=\"8316610216\">אוה\"ת</a> פ' שופטים ע' תתמה. סה\"מ תרל\"ג ח\"ב ע' תסה וע' תסו. מאמר ד\"ה אתם נצבים תשט\"ז."],["153","89","<b>אני בצדק אחזה פניך</b>: תהלים יז, טו."],["154","90","<b>כי</b>: כ\"ה גם בסה\"מ תרל\"ה ח\"ב כאן ריש ע' תעא."]]],[2000470096,"מעמיד כו', וי\"ל כי ע\"י בחי' גדול זה ממשיכי' שיומשך מאוא\"ס ב\"ה מבחי' שמו הגדול ש' הוי' דלעילא ע\"ק וז\"ע לגוי גדול שהם עצמם בחי' גדול ע\"ש שהם מעוררי' בעצמם בחי' גדול הוי' שבכאו\"א ועי\"ז ממשיכים מבחי' שמו הגדול ש' הוי' דלעילא בחי' ע\"ק כו'.\n<b>וענין</b> אלקי יצחק הוא בחי' קו השמאל בג\"ה<sup data-n=\"155\">91</sup> והו\"ע ההעלאה מלמטלמ\"ע כו', כענין<sup data-n=\"156\">93</sup> עבודת הקרבנות<sup data-n=\"157\">92</sup> וכענין הבארות שחפר יצחק<sup data-n=\"158\">94</sup> כמ\"ש ענינם בת\"א בד\"ה אלה תולדות יצחק<sup data-n=\"159\">95</sup> ובהגהות לשם<sup data-n=\"160\">96</sup>, ועז\"נ ואברכך פי' וענין הברכה שיהי' ההעלאה והצמיחה בברכה וריבוי וכמ\"ש בלק\"ת פ' נשא<sup data-n=\"161\">97</sup> בד\"ה כה תברכו בפי' יברכך<sup data-n=\"162\">98</sup> ה', ולכן<sup data-n=\"163\">99</sup> מצינו שיצחק בירך את יעקב ויתן לך האלקי'<sup data-n=\"164\">101</sup> מטל השמים כי שרשו מקו המדה בוצינא<sup data-n=\"165\">102</sup> דקרדוניתא<sup data-n=\"166\">100</sup> שמשם באה הברכה, ואגדלה שמך זהו שאומרים ואלקי יעקב כי יעקב הוא בריח התיכון<sup data-n=\"167\">103</sup> המבריח מן הקצה אל הקצה ונאמר בו לשון ואגדלה שענין הברכה בריבוי שזהו ואברכך דיצחק פועל הגדלה באדם הנתברך<sup data-n=\"168\">104</sup> וכמ\"ש ויגדל האיש הלוך וגדל<sup data-n=\"169\">105</sup> שהוא ע\"י שנתברך בריבוי שהוא ע\"י הברכה שברכו הוי' שמצא מאה שערים<sup data-n=\"170\">106</sup> עי\"ז נתגדל הלוך וגדל עד כי גדל מאד כמ\"ש בפ' תולדות<sup data-n=\"171\">107</sup>, וגם<sup data-n=\"172\">108</sup> כולל ענין אברהם דכתי' ואעשך לגוי גדול והיינו",[["155","91","<b>קו השמאל בג\"ה</b>: ראה זהר רע\"מ בהעלותך קנג, ב. פרדס שער סדר עמידתן ש\"ו, פ\"א. בד קודש פ\"ב<sup data-n=\"e11\">ז</sup>. מאמרי אדה\"א בראשית ע' שיז. וש\"נ."],["156","93","<b>כענין</b>: וכ\"ה באוה\"ת כאן ס\"ע 1390. בסה\"מ תרל\"ה כאן תרמ\"ג כאן ע' יג: בענין."],["157","92","<b>ההעלאה. . קרבנות</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו על יד הערה 40. ד\"ה ואתה תצוה על יד הערה 39. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ושאבתם מים פ\"א (ובהערה 10 16). מאמרי אדה\"א קונטרסים ע' תקעד."],["158","94","<b>הבארות שחפר יצחק</b>: תולדות כו, יח ואילך."],["159","95","<b>בת\"א בד\"ה אלה תולדות יצחק</b>: יז, ג."],["160","96","<b>ובהגהות לשם</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490277\" data-slug=\"or-hatorah-hb\" data-id=\"8316490277\">אוה\"ת תולדות כרך ד ע' תתח</a> ואילך. ע' 1628 ואילך. וראה גם מאמרי אדה\"ז תקס\"ח ח\"א ע' תקיז ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680196\" data-slug=\"torat-chaim\" data-id=\"2300680196\">תו\"ח תולדות קמד, ד</a> ואילך. פלח הרמון תולדות עז, ב ואילך. סה\"מ תרע\"ח ע' עג ואילך. תרח\"ץ ע' קמז ואילך."],["161","97","<b>בלק\"ת פ' נשא</b>: כו, ג."],["162","98","<b>יברכך ה'</b>: נשא ו, כד."],["163","99","<b>ולכן</b>: קודם תיבה זו נרשם [ראה לעיל הערה 33]: / והיינו — ראה סה\"מ תרמ\"ג כאן ע' יג שו\"ה בפי' — והיינו."],["164","101","<b>ויתן לך האלקי'</b>: תולדות כז, כח."],["165","102","<b>בוצינא דקרדוניתא</b>: ראה זהר בראשית טו, א [ובמפרשים שם]. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370177\" data-slug=\"torah-or\" data-id=\"3901370177\">תו\"א מקץ לט, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370476\" data-slug=\"torah-or\" data-id=\"3901370476\">שמות קז, ד</a>. מאמרי אדה\"א נ\"ך ע' עא. וש\"נ. אוה\"ת שלח ע' תצג ואילך."],["166","100","<b>שיצחק. . מקו המדה בוצינא דקרדוניתא</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370097\" data-slug=\"torah-or\" data-id=\"3901370097\">תו\"א תולדות כא, רע\"א</a>."],["167","103","<b>יעקב הוא בריח התיכון</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. תרומה קעה, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט. סה\"מ תרכ\"ט ע' קיז. וש\"נ. תרנ\"ג ע' רנח ואילך."],["168","104","<b>הנתברך</b>: וכ\"ה בסה\"מ תרמ\"ג כאן. בסה\"מ תרל\"ה: המתברך."],["169","105","<b>ויגדל האיש הלוך וגדל</b>: תולדות כו, יג [בדילוג — ראה סה\"מ תרמ\"ג כאן ע' יד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680236\" data-slug=\"torat-chaim\" data-id=\"2300680236\">תו\"ח תולדות קנב, ג</a>]."],["170","106","<b>שמצא מאה שערים</b>: תולדות כו, יב."],["171","107","<b>עד כי גדל מאד. . בפ' תולדות</b>: כו, יג."],["172","108","<b>וגם</b>: קודם תיבה זו נרשם [ראה לעיל הערה 33]: / והיינו — ראה סה\"מ תרמ\"ג כאן ע' יד שו\"ה תולדות — והיינו.\n\n<b>ז</b>  נדפס גם באגרות קודש אדמו\"ר האמצעי ח\"א ע' רצ ואילך."]]],[2000470097,"כנ\"ל שיעקב הי' מרכבה למדת הת\"ת שכולל ב' בחי' חו\"ג וכמ\"ש אלקי אבי אברהם<sup data-n=\"173\">109</sup> ופחד יצחק הי' לי כו'. והיה ברכה, יכול יהו חותמין בכולן ת\"ל והי' ברכה בך חותמין, כי אברהם בחי' חסד נק' יומם דאזיל עם כולהו יומין, בזח\"ג אמור ק\"ג ע\"ב<sup data-n=\"174\">110</sup>, שכל הו\"ק מקבלי' ממנו כי החסד מקבל מהבינה, ואזיל עם כולי יומין, ונמצא מקשר אור הג\"ר כח\"ב בכל הו\"ק וסיומן הוא ביסוד, וז\"ע בקר דאברהם ובקר דיוסף בזח\"ג פי' בלק דף ר\"ד סע\"א וע\"ב וע' בזהר נשא דקמ\"ב ע\"א.",[["173","109","<b>אלקי אבי אברהם</b>: ויצא לא, מב [בדילוג — ראה הנסמן בסמוך]. ראה לקמן ח\"ב הנחה ד\"ה כנשר יעיר קנו (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) על יד הערה 17. (בחלק ההנחות) על יד הערה 19. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370083\" data-slug=\"torah-or\" data-id=\"3901370083\">תו\"א תולדות יז, ג</a>. סידור שער הלולב רסב, א. מאמרי אדה\"א ויקרא ח\"ב ע' תשסג. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540885\" data-slug=\"torat-chaim\" data-id=\"2300540885\">תו\"ח בא ח\"א קכז ג</a>. וש\"נ."],["174","110","<b>יומם. . בזח\"ג אמור ק\"ג ע\"ב</b>: ראה גם הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'לה."]]],[2000470098,"<h3>כמגדל דוד צוארך</h3>\n<b></b>מים עליונים ומ\"ת כו' גדול ה' ב' פירושים\nתולדות\n<b>כמגדל</b> דוד צוארך<sup data-n=\"175\">1</sup> בנוי לתלפיות<sup data-n=\"176\">2</sup> כו' וכמארז\"ל ברכות פ\"ד ד\"ל א' תל שכל פיות פונים בו. כי הנה צואר זה הוא בהמ\"ק וא' בכאן שני מעלות על בהמ\"ק הא' שהוא כמגדל דוד, הב' שהוא בנוי לתלפיות כמשי\"ת. וביאור הענין הנה ארז\"ל בשני מה היו אומרים גדול הוי' ומהולל מאד בעיר אלקינו הר קדשו<sup data-n=\"177\">4</sup> ופרש\"י בר\"ה דל\"א ע\"א על מארז\"ל ע\"ש שחילק מעשיו<sup data-n=\"178\">3</sup> כו' וז\"ל הבדיל רקיע בין עליונים לתחתונים ונתעלה וישב במרום דוגמת שכנו בעירו והר קדשו ע\"כ. ולהבין מה שתלה זב\"ז היינו ענין ההבדלה של הרקיע דומה לשכנו בעירו כו', הנה מתחלה י\"ל ענין ההבדלה דרקיע שהיתה בין מים למים ומבואר בדרז\"ל שמתחלה הי' העולם מים במים<sup data-n=\"179\">5</sup> כו' היינו שהי' מ\"ת מעורבים במ\"ע ואח\"כ הבדיל ביניהם ע\"י הרקיע מ\"ע מעל לרקיע ומ\"ת ירדו מתחת לרקיע כו'.",[["175","1","<b>כמגדל דוד צוארך</b>: אודות מאמר זה כותב כ\"ק אדמו\"ר בספר התולדות של כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"e12\">א</sup>: ”מים עליונים ומ\"ת כו' גדול ה' ב' פירושים\".\nמאמר זה נדפס גם בסה\"מ תר\"ל ע' כד<sup data-n=\"e13\">ב</sup>. והוא הנחת ר' הלל<sup data-n=\"e14\">ג</sup> מדרוש כ\"ק אדמו\"ר הצ\"צ משבת פ' במדבר לאחר סעודה שלישית שנת תרי\"ב עם איזה תיקונים מכ\"ק אדמו\"ר מהר\"ש.\nלמאמר זה ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770411\" data-slug=\"or-hatorah-hb\" data-id=\"8316770411\">אוה\"ת שה\"ש ח\"ב ס\"ע תיא</a> ואילך. ע' תטז ואילך. (יהל אור) תהלים ע' קעט ואילך.\nמאמר זה נדפס כאן ע\"פ הנרשם בספר התולדות של כ\"ק אדמו\"ר מהר\"ש ושם: ”תולדות\". בבוך זה 2208 לא נרשם מאמר זה. ולהעיר ממכתב של כ\"ק אדמו\"ר מהר\"ש מ”יום ה' ך\"ז מ\"ח תרום<sup data-n=\"e15\">ד</sup> לפ\"ק מאנטרעאוקס נדפס באג\"ק שלו מהדורת תשס\"ב ע' קיא ואילך. ואולי לא נאמר בליובאוויטש. וראה גם לעיל מאמר ד\"ה להבין ענין ר\"ח הערה 1."],["176","2","<b>כמגדל דוד. . לתלפיות</b>: שה\"ש ד, ד."],["177","4","<b>גדול. . בעיר אלקינו הר קדשו</b>: תהלים מח, ב [סיום הכתוב הובא בסוף מס' תמיד]."],["178","3","<b>בשני. . שחילק מעשיו</b>: ר\"ה לא, א."],["179","5","<b>שמתחלה הי' העולם מים במים</b>: ראה ב\"ר פ\"ה, ב. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כנשר יעיר קנו על יד הערה 90. (בחלק ההנחות) שם על יד הערה 112. ד\"ה ושאבתם מים על יד הערה 68. שה\"א נג, ב הערה 16.\n\n<b>א</b>  קה\"ת תש\"ז — ברשימת מאמרי תר\"ל — ע' 31.\n\n<b>ב</b>  נאמר בפ' תולדות ועוה\"פ בפ' תצוה.\n\n<b>ג</b>  יודפס בע\"ה בדרושיו בפלח הרמון במדבר.\n\n<b>ד</b>  כ\"ה בגוכתי\"ק."]]],[2000470099,"<b>וביאור</b> הדברים הנה מים הוא מקור כל מיני השפעות עונג כי המים מצמיחים כל מיני תענוג<sup data-n=\"180\">6</sup> וכן באדם הנה מקור המים והלחלוחי' הרוחני' הוא במוח<sup data-n=\"181\">7</sup> והוא מצמיח שכל ותענוג כי בשכל מלובש התענוג<sup data-n=\"182\">*8</sup> ולכן בהשכלת שכל חדש ימצא בה תענוג מורגש כו', ומקור המצמיח שניהם הוא הלחלוחי' הרוחני' שבמוח כו', וכ\"ה למעלה הנה מקור הממשיך כל מיני עונג בעולמות נק' בשם מים, ויש ב' מיני מים כו', הא' בחי' מ\"ע והוא מ\"ש ונהר יוצא מעדן<sup data-n=\"183\">8</sup> להשקות את הגן שבחי' עדן הוא מקור כל התענוגי' עליונים שבאצי', והוא מקור התענוג המלובש בח\"ע דאצי' ע\"ד מקור התענוג המלובש במוח ולחלוחית שבמוח האדם כו', ונהר הוא ההמשכה<sup data-n=\"184\">9</sup> הנמשך בכל עולם האצי' עד שנמשך בגעה\"ע להיות הנשמות נהנין מזיו השכינה<sup data-n=\"185\">11</sup> כו' וזהו בחי' מ\"ע כו', ומה שנמשך מבריאה ליצי' להיות תענוג לנשמות בג\"ע דיצי' וכן מיצי' לעשי' להיות תענוג לנשמות בג\"ע דעשי'<sup data-n=\"186\">10</sup> כ\"ז נכלל בכל<sup data-n=\"187\">12</sup> מ\"ת לגבי בחי' תענוג הנשמות שבגעה\"ע כו', אך לגבי המשכות תענוג הגשמי' כ\"ז נק' מ\"ע כו', ומ\"ת הוא בחי' מקור כל התענוגי' שבעולם העשי' הגשמי' המשפיע תענוג גשמי' כו'. והנה בתחלה קודם הבדלת הרקיע הי' בחי' מקור כל התענוגי' הגשמי' שבעולם העשי' הגשמי נכלל בבחי' התענוג הרוחני שבעולמות הרוחני' ולא הי' נבדל ממנו, נמצא שהי' הפסולת מעורב בטוב והטוב כו', אך אחר שאמר יהי רקיע<sup data-n=\"188\">13</sup> אזי נתברר ונבדל התענוג גשמי מן הרוחני. והנה כמו עד\"מ חביות יין<sup data-n=\"189\">14</sup> המעורבת בשמרים כ\"ז שלא נבדלו השמרים מן היין אז לא נגלה בהיין טוב טעמו והשמרים אינם נראים גסים כ\"כ, אך כשעומדת זמן מה השמרים נבדלים מן היין ונופלים למטה והיין עומד על שמריו ועי\"ז נגלה ביין טוב טעמו ובהשמרים נגלה גסותם בתכלית, כך למעלה ע\"י הבדלת הרקיע נתעלו בחי' מ\"ע יותר והיינו שנתגלה בהם גילוי אוא\"ס בעילוי",[["180","6","<b>כי המים מצמיחים כל מיני תענוג</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310006\" data-slug=\"tanya\" data-id=\"3401310006\">תניא פ\"א</a>. סידור שבהערה הבאה. המשך וככה תרל\"ז פ\"נ."],["181","7","<b>מקור המים והלחלוחי' הרוחני' הוא במוח</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא</a> פ\"ג ובמ\"מ הגהות והע\"ק לשם. סידור כוונת המקוה קנו, א."],["182","*8","<b>בשכל מלובש התענוג</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מצה זו ובהערה 49."],["183","8","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["184","9","<b>ונהר הוא ההמשכה</b>: ראה גם מאמר ד\"ה להבין וכו' האותות והמופתים תקס\"ה נדפס ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540047\" data-slug=\"torat-chaim\" data-id=\"2300540047\">תו\"ח שמות ח\"א לו, ג</a> ובהערה 11."],["185","11","<b>נהנין מזיו השכינה</b>: ראה ברכות יז, א."],["186","10","<b>בגעה\"ע. . מבריאה. . בג\"ע דיצי'. . בג\"ע דעשי'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370152\" data-slug=\"torah-or\" data-id=\"3901370152\">תו\"א מקץ לב, ד</a>. מאמרי אדה\"ז הנחות הר\"פ ע' קכג. מאמרי אדה\"א במדבר ח\"ג ע' א'רב ובהנסמן שם ס\"ע א'רעט ואילך. אוה\"ת שה\"ש כרך ג' ע' א'יז. (לקמן בחלק ההנחות) הנחה ד\"ה כמים הפנים על יד הערה 45."],["187","12","<b>בכל</b>: וכ\"ה בבוך 1139 קפא, סע\"ב (בהנחת ר' הלל — שכנראה ממנו הועתק). בסה\"מ תר\"ל כאן ע' כה: בכלל. ובהערה לשם: בכת\"י כתוב: בכל. בבוך 744 (הנחת ר' הלל): בכלל."],["188","13","<b>יהי רקיע</b>: בראשית א, ו. ראה גם אמ\"ב שער הק\"ש פ\"ב. אוה\"ת תהלים כאן ע' קפ. סה\"מ תרכ\"ו ע' כ. ע' לג. וע' נח. תרל\"ד ע' רנא. המשך מים רבים תרל\"ו פק\"ל. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כנשר יעיר קנו על יד הערה 91. (בחלק ההנחות) שם על יד הערה 113."],["189","14","<b>עד\"מ חביות יין</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380481\" data-slug=\"likkutei-torah\" data-id=\"4001380481\">לקו\"ת שלח מב, ב</a>."]]],[2000470100,"יותר ע\"י הבדלת הפסולת מהם שהם תענוגי' הגשמי' כו' ומציאות תענוגי' הגשמי' ירדו למטה ונתגשמו ביותר כו', וזהו מ\"ת בוכים<sup data-n=\"190\">15</sup> כי מצד הריחוק גורם בהם תגבורת התשוקה לעלות לשרשם הקדום כו'. וזהו כוונת רש\"י ז\"ל הבדיל בין עליונים לתחתונים ונתעלה וישב במרום, והכוונה שע\"י הבדלה הנ\"ל נתגלה יותר במרום שהם מ\"ע שנתגלה בהם אוא\"ס בעילוי יותר כו', ומש\"א אח\"כ דוגמת שכנו בעירו כו' הכוונה שכמו שעשה הבדלה שיהי' עיקר גילוי במרום וכמא' ומושב יקרו בשמים ושכינת עוזו<sup data-n=\"191\">16</sup> כו', כן בארץ גופא בחר לו מקום להיות עיקר שכינתו שם והוא בעירו והר קדשו כו'.\n<b>וביאור</b> הענין יובן בהקדים מ\"ש אי לך ארץ שמלכך נער כו' וכתי' אשריך ארץ שמלכך בן חורים (קהלת י\"א<sup data-n=\"192\">17</sup> ט\"ז י\"ז) הכוונה שבח\"ל מקור ההשפעה הוא מבחי' נער שהוא בחי' מט\"ט הנק' שרו ש\"ע<sup data-n=\"193\">19</sup> שהוא בבחי'<sup data-n=\"194\">21</sup> ו\"ק דיצי'<sup data-n=\"195\">22</sup> שהכלי שבהם מוגבלים ומעלימים אור האלקי הבלתי מוגבל כו' וכמארז\"ל נער הייתי גם זקנתי שרו ש\"ע<sup data-n=\"196\">20</sup> אמרו כו', משא\"כ בארץ ובירושלים ובהמ\"ק שם מאיר מבחי' ו\"ק דאצי'<sup data-n=\"197\">18</sup> שגם הכלים שבהם בחי' אלקות<sup data-n=\"198\">23</sup> והם בלתי מוגבלים<sup data-n=\"199\">24</sup> כו', רק ששם גופא יש חילוקי מדרגו' באופן הגילוי דו\"ק דאצי' והוא משארז\"ל עשר קדושות הן<sup data-n=\"200\">25</sup> כו', וזהו אשריך ארץ שמלכך בן חורין<sup data-n=\"201\">27</sup> והוא בחי' ז\"א דאצי'<sup data-n=\"202\">26</sup> הנק' בן חורין להיות<sup data-n=\"203\">28</sup> שורש התגלות' הוא מבחי' אימא עילאה בינה<sup data-n=\"204\">29</sup> דאצי' עולם החירות<sup data-n=\"205\">30</sup> כו' משא\"כ בחו\"ל א' אי לך ארץ שמלכך נער שמקבלי' מבחי' ו\"ק דאצי' כמו שמתלבשי' בו\"ק דיצי' הנק' מט\"ט שנק' נער. והטעם לזה ידוע שיש אנפי רברבי",[["190","15","<b>מ\"ת בוכים</b>: ראה ת\"ז ת\"ה (יט, ב). הנסמן במאמרי אדה\"א בראשית ע' קג. שמות ח\"א ריש ע' לו."],["191","16","<b>ומושב יקרו. . עוזו</b>: ע\"פ תפלת עלינו."],["192","17","<b>י\"א</b>: כנצ\"ל: י'."],["193","19","<b>נער. . שרו ש\"ע</b>: תהלים לז, כה. ראה יבמות טז, ב ובתוס' שם."],["194","21","<b>מט\"ט. . בבחי'</b>: בסה\"מ תר\"ל: מט\"ט. . בחי'. אבל כ\"ה בבוך 234 (שממנו נדפס). ובבוך 1139 הנ\"ל."],["195","22","<b>מט\"ט. . דיצי'</b>: ראה ע\"ח שער סדר אבי\"ע שמ\"ז, פ\"ו. תו\"ח בא ח\"א צח, ריש ע\"ב ובהערה 85."],["196","20","<b>מט\"ט הנק' שרו ש\"ע</b>: ראה גם לעיל מאמר ד\"ה לה\"ע ר\"ח ובהערה 39."],["197","18","<b>שבח\"ל. . מט\"ט. . ו\"ק דיצי'. . בארץ. . ו\"ק דאצי'</b>: באוה\"ת כאן רס\"ה מציין: במג\"ע ר\"י רי\"ח. ראה גם לקמן הערה 24."],["198","23","<b>דאצי' שגם הכלים. . אלקות</b>: ראה אגה\"ק ס\"כ. אוה\"ת ויצא ע' 364."],["199","24","<b>דאצי' שגם הכלים. . בלתי מוגבלים</b>: ראה סה\"מ תרל\"ג ח\"ב ס\"ע תלד ואילך. וש\"נ. תרמ\"ג ע' קיח ואילך. וראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה להבין שרש ענין מקיפים דבינה פ\"ד. וש\"נ. ד\"ה ויובן כו' הני ששה ועשרים הודו ובהערה 114."],["200","25","<b>עשר קדושות הן</b>: כלים פ\"א, מ\"ו. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301470217\" data-slug=\"likkutei-sichot\" data-id=\"1301470217\">לקו\"ש תרומה כרך לא ע' 149</a> ואילך. וש\"נ."],["201","27","<b>חורין</b>: בהכתוב וכן הובא לעיל: חורים. אבל כ\"ה בכ\"מ — ראה זהר לך צה, ב. אוה\"ת כאן. פלח הרמון אמור ע' שעא."],["202","26","<b>בן חורין. . ז\"א דאצי'</b>: ראה זהר לך צה, ב. אוה\"ת ואתחנן ע' צ. ס\"ע קכט ואילך."],["203","28","<b>להיות</b>: בסה\"מ תר\"ל ליתא. אבל כ\"ה בביכלאך הנ\"ל."],["204","29","<b>אימא עילאה בינה</b>: ראה ע\"ח שער או\"א שי\"ד, פ\"ח."],["205","30","<b>בינה. . עולם החירות</b>: ראה מאו\"א מערכת דרור אות יג וביאיר נתיב שם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380684\" data-slug=\"likkutei-torah\" data-id=\"4001380684\">לקו\"ת מסעי צ, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380960\" data-slug=\"likkutei-torah\" data-id=\"4001380960\">ר\"ה ס, ב</a>."]]],[2000470101,"ואנפי זוטרי<sup data-n=\"206\">31</sup> ועד\"ז ההפרש בין גדול לקטן שהציור של האברים שיש בגדול הוא ממש בדוגמא זאת בקטן רק שבקטן האברי' קטנים ובגדול האברי' גדולים יותר, וכן ברוחני' הנפש אותן הכחות שישנם בגדול שהוא בחי' שכל ומדות אותם הבחי' ממש ישנם בקטן ג\"כ רק שבקטן הם בתכלית הקטנות להשכיל דברים קטנים ביותר וממילא המדות הם לפ\"ע השכל להתפעל מדברים קטנים, משא\"כ בגדול נתגדל שכלו להשכיל דברים גדולים ביותר וממילא ההתפעלות שלו הוא ג\"כ מדברים גדולים ביותר, נמצא שההפרש בין גדול לקטן הוא בענין הכלים הן בגשמי' הן ברוחני', אבל באור וחיות הרוחני' אין הפרש רק בענין ההעלם וגילוי שבגידול הכלים נתגלה החיות ביותר ובקטנות הכלים הוא בהעלם והעדר התפשטו' כו', אבל בעצם החיות אין שינוי כלל כו', כן למעלה בבחי' הכלים דאצי' שהם בחי' אלקות לכן בחי' התגלות אוא\"ס בהם הוא בתכלית ההתגלות והתרחבות משא\"כ בו\"ק דיצי' שהם מוגבלים לכן התגלות אור האלקי בהם בבחי' צמצום והגבלה מאד.\n<b>וזהו</b> ג\"כ ענין אתוון בינונים ואתוון זעירין<sup data-n=\"207\">32</sup> שאין נ\"מ בעצם ציור האותיות רק בבחי' הקטנות וההגדלה, כן למעלה צירופי' ואותיות שנבראו בהם שו\"א הם בתכלית ההעלם והסתר בתוך הנבראי' לכן נק' אתוון זעירין משא\"כ בעולם האצי' שהאותיות הנק' בשם כלים<sup data-n=\"208\">33</sup> אינם מלובשי' בבחי' העלם והסתר לכן נק' בשם אתוון בינוני' כו'. והנה ידוע שמבחי' ההגדלות<sup data-n=\"209\">34</sup> הכלים נמשך בחי' חסד ורחמים, עד\"מ הגדול בדעת מלא רחמים וסובל ההיפוך ואינו מתפעל ברוגז, משא\"כ הקטן בדעת הוא מלא רוגז והיינו מפני צמצום האור וחיות שבו גורם צמצומי' ודינים גם בבחי' ההשפעה לזולתו, משא\"כ כשהאור וחיות שם הוא בו בהתרחבות גורם המשכת השפע בהתרחבות גם לזולתו, לכן אמר אשריך ארץ כו' שמלכך בן חורין שבארץ הוא מקור החסד וטוב ע\"ש שמקבלת מבחי' גדולת<sup data-n=\"210\">35</sup> הכלים שבאצי' כו' משא\"כ בחו\"ל שמקבלת מבחי' הכלים דיצי' לכן ההשפעה באה בבחי' דינים וצמצומים כו'. ולזה אמר דוגמת שכנו בעירו והר קדשו, שכמו שיש הפרש בין מ\"ע למ\"ת שבמ\"ע הוא התגלות אוא\"ס שהוא בחי' ש' הוי', משא\"כ בבחי' מ\"ת מוסתר אור האלקי בתכלית ע\"י ריבוי צמצומים דש' אלקי', כן יש הפרש זה בין השראתו בחו\"ל שהוא בתכלית הצמצום וההסתר שהוא בבחי' ההתלבשות בשם אלקי' כו', ולכן ההנהגה שם בדרך הטבע, משא\"כ בעירו והר קדשו הוא התגלות ש' הוי' ובלתי הסתר בשם אלקי' כו', לכן שם הוא מקום גילוי אותות ומופתים שלמעלה מן הטבע כמו אש שלמעלה ע\"ג המזבח<sup data-n=\"211\">36</sup> ומקום הארון אינו מן המדה<sup data-n=\"212\">37</sup> כו', וזהו שהיו אומרים בשני",[["206","31","<b>אנפי רברבי ואנפי זוטרי</b>: ראה חגיגה יג, ב. הנסמן ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550147\" data-slug=\"torat-chaim\" data-id=\"2300550147\">תו\"ח משפטים ח\"ב רפז, ג</a>."],["207","32","<b>אתוון בינונים ואתוון זעירין</b>: ראה מאו\"א מערכת אות סנ\"ב נעתק לקמן בהמשך זאת חנוכת המזבח פכ\"א. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770411\" data-slug=\"or-hatorah-hb\" data-id=\"8316770411\">אוה\"ת שה\"ש ח\"ב ס\"ע תיא</a> ואילך."],["208","33","<b>שהאותיות הנק' בשם כלים</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א. שהיחוה\"א ספ\"ד. שע\"ת לח, ב הערה 13. לקמן המשך זאת חנוכת המזבח פכ\"א."],["209","34","<b>ההגדלות</b>: בבוך 744: ההגדלת."],["210","35","<b>גדולת</b>: שם: גדלות."],["211","36","<b>אש שלמעלה ע\"ג המזבח</b>: תו\"כ ויקרא א, ז. יומא כא, ב."],["212","37","<b>ומקום הארון אינו מן המדה</b>: יומא כא, א."]]],[2000470102,"גדול הוי' ומהולל כו' בעיר אלקינו היינו שהתגלות ש' הוי' כמ\"ש בבחי' א\"ס שנק' גדול הוא בעיר אלקינו דייקא כו'.\n<b>והנה</b> זהו פי' א' בפסוק הנ\"ל דגדול הוי', והנה יש פי' ב' בפסוק הנ\"ל והוא משארז\"ל אימתי גדול<sup data-n=\"213\">38</sup> כשהוא בעיר אלקינו כו' דלפ\"ז משמעו דשם הוי' מצד עצמו אינו עדיין בבחי' גדול רק כשהוא בעיר אלקינו אז נעשה גדול וכ\"ה בזה\"ק ויקרא ד\"ה א' דמלכא בלא מטרוניתא לא<sup data-n=\"214\">39</sup> הוא מלכא ולאו הוא גדול כו'. ולהבין ענין זה יש להקדים ענין מה שמצינו במרע\"ה שהי' כבד פה וכבד לשון<sup data-n=\"215\">40</sup> וידוע שזהו מצד יתרון מעלתו בבחי' ביטול דמ\"ה דחכ' בעצם ולכן לא הי' יכול להשפיל א\"ע בבחי' דבור וא\"כ מה זה שמצינו אח\"כ שבשעת מ\"ת זכה לדבור נחשב לו זה ליתרון מעלה כיון שהוא ירידה והשפלה להלביש א\"ע בדבור. ועוד י\"ל המאמר ומתלמידי יותר מכולם<sup data-n=\"216\">41</sup> האיך יתכן שהרב המשפיע יקבל מן התלמיד המקבל ממנו כו'. אך באמת הנה אנו רואים שכאשר ידבר החכם איזו חכ' עמוקה בדבור שיתוסף לו<sup data-n=\"217\">42</sup> בשעת מעשה חדשות ממקור החכ' כו', והטעם לזה כי שרש אותיות הדבור אינם נמשכי' מן המוצאות רק עצם שרשם הוא מבחי' מקור החכ'<sup data-n=\"218\">43</sup> שלמעלה מבחי' גילוי החכ' מאין<sup data-n=\"219\">44</sup> כו'. ועתה יובן ענין הנ\"ל במשה כי אע\"פ שמתחלה הי' במעלה גבוה בחי' מ\"ה דחכ' ולכן הי' כבד פה אך אח\"כ זכה למעלה יותר גבוה שזכה למקור החכ' שממנו תמצא החכ' מאין כו' ולכן הי' בכחו להשפיל א\"ע בדבור הנמשך ממקור החכ' כו'. וזהו הטעם דמתלמידי יותר מכולם, כי ע\"י דבורו לתלמידו מעורר מקור חכמתו להתגלות בשכלו בשעת מעשה ולכן ניתוסף לו חדשות בעילוי יותר ממה שהשכיל בתחלה כו'. ועתה יובן ענין אימתי גדול כשהוא בעיר אלקינו, כי הנה ידוע שהאותיות נק' אבנים<sup data-n=\"220\">45</sup> וצירופי האותיות נק' בשם בתים ועיר אלקינו הוא מקור כל הצירופי' שהוא בחי' המל' מקור הדבור<sup data-n=\"221\">46</sup>, וזהו גדול הוי' שבחי' ש' הוי' הוא בחי' המדות דאצי' כמ\"ש מקבלי' המוחי' דח\"ע, והנה נא' אני הוי' הוא שמי<sup data-n=\"222\">47</sup> שהוא בחי' שם בלבד לגבי עצמות המאציל ונמשך בבחי' צמצום מעצמות",[["213","38","<b>אימתי גדול</b>: ראה זהר פקודי רלה, א. ויקרא ה, א. מאמרי אדה\"א נ\"ך ע' פ. וש\"נ. סה\"מ תרכ\"ז ס\"ע ר. וש\"נ."],["214","39","<b>לא</b>: אוצ\"ל: לאו."],["215","40","<b>במרע\"ה שהי' כבד פה וכבד לשון</b>: שמות ד, י. ראה גם סידור שער בהמ\"ז קי, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370234\" data-slug=\"torah-or\" data-id=\"3901370234\">תו\"א שמות נב, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540543\" data-slug=\"torat-chaim\" data-id=\"2300540543\">תו\"ח שמות ח\"א מז, ד</a> ואילך. מאמרי אדה\"א שמות ח\"ב ע' שלב ואילך. אוה\"ת יתרו ע' תשפג ואילך. סה\"מ תרכ\"ז ע' עח."],["216","41","<b>ומתלמידי יותר מכולם</b>: תענית ז, א. ראה גם לקמן המשך מצה זו פי\"ז ובהערה 538."],["217","42","<b>שכאשר ידבר החכם. . שיתוסף לו</b>: ראה ביאוה\"ז פינחס קיג, ב ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'תלד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540525\" data-slug=\"torat-chaim\" data-id=\"2300540525\">תו\"ח שמות ח\"א מז, ג</a>. וש\"נ. סה\"מ תרל\"ה ח\"ב ע' שמ. וש\"נ. לקמן המשך מצה זו פי\"ז ובהערה 537. סה\"מ מלוקט ו' ע' פא."],["218","43","<b>שרש אותיות הדבור. . מקור החכ'</b>: ראה אגה\"ק ס\"ה."],["219","44","<b>גילוי החכ' מאין</b>: איוב כח, יב."],["220","45","<b>שהאותיות נק' אבנים</b>: ראה ס\"י פ\"ד, מי\"ב. מאמרי אדה\"א נ\"ך ע' תקלב. לקמן המשך זאת חנוכת המזבח פי\"ד ואילך. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה על יד הערה 35 ואילך."],["221","46","<b>המל'. . הדבור</b>: ראה זהר לך פו, ב. ע\"ח שער מוחין דצלם שכ\"ג, ספ\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפב. וש\"נ."],["222","47","<b>אני הוי' הוא שמי</b>: ישעי' מב, ח."]]],[2000470103,"המאציל ולכן האות ראשונה דש' הוי' הוא היו\"ד שמורה על בחי' הצמצום<sup data-n=\"223\">48</sup> והיינו הצמצום מעצמות המאציל בח\"ע כו', אך ע\"י היחוד דהוי' בבחי' המל' דאצי' ניתוסף אורות בש' הוי' עצמו מעצמות המאציל, והטעם לזה להיות כי עיקר כוונת המאציל בבחי' אצי' הי\"ס באו\"כ הי' כדי שיומשך על ידם בבחי' המל' דאצי' בכדי להיות לו דירה בתחתוני'<sup data-n=\"224\">49</sup> כו' לזאת כאשר נעשה כן נשלם כוונה הפנימי' ועי\"ז מתגלה עונג הפנימי המלובש במקור ח\"ע הנק' ח\"ס ומתגלה להאיר בתוס' אור בח\"ע כו' וכענין מתלמידי יותר מכולם כנ\"ל. ובחי' זאת נק' אתוון רברבין<sup data-n=\"225\">50</sup> כו', ואז נק' ש' הוי' בחי' גדול ע\"ש שנמשכים בו בחי' מוחין דגדלות האמיתי' שלמעלה מבחי' הצמצום דח\"ע כו', וע' בסידור בענין קי\"ס<sup data-n=\"226\">51</sup> במא' ששת ימים השני בענין המעיין בע\"ח יראה כו' יעו\"ש.\n<b>ועם</b> כל הנ\"ל יובן ענין כמגדל דוד צוארך כי הנה הצואר יש בו ג' בחי' שר המשקים ושר הטבחים ושר האופי', שר המשקים בקדושה הוא בבחי' התורה שנק' מים ויין שהוא העיון בפנימי' התו' וחיצוני' התו'<sup data-n=\"227\">52</sup> עד שיוקלט בלבבו כו', ושר הטבחי' הוא בחי' אהבה ברשפי אש<sup data-n=\"228\">53</sup> שהוא בחי' מס\"נ בק\"ש ותפלה ועש\"ז נק' עיקר הצואר כי צואר אותיות רצוא<sup data-n=\"229\">54</sup> כו', ושר האופים הוא בחי' דיבור דתורה<sup data-n=\"230\">55</sup> כו', וכ\"ז הי' בבהמ\"ק שהי' ענין ניסוך המים וניסוך היין כו' וקרבנות כו' ולחה\"פ ושתי הלחם כו', ועי\"ז נעשה בחי' חיבור סוכ\"ע שהוא בחי' אתוון רברבין שהוא בחי' הגילוי שלמעלה מן הח\"ע בבחי' ח\"ע ומל' דאצי' וכנ\"ל, וזהו כמגדל דוד צוארך כי דוד הוא בחי' המל'<sup data-n=\"231\">56</sup> דאצי' ונק' מגדל ע\"ש שהוא פועל מקור הגדולה וההמשכה בש' הוי' כנ\"ל בענין אימתי גדול, ולכן אמר שגם בהמ\"ק שלמטה שהוא בחי' צואר דכנ\"י הוא כמו מגדל דוד העליון שהוא פועל המשכת מקור הגדולה בשם הוי' ע\"י העבודות שהיו עובדים בקרבנות וניסוך המים כו' כנ\"ל, ואח\"כ אמר מעלה יותר גדולה על בהמ\"ק שהוא בנוי לתלפיות, תל שכל פיות פונים בו כו', הנה הטעם שארז\"ל שכאו\"א יכוין את לבו כנגד בית קה\"ק<sup data-n=\"232\">57</sup>",[["223","48","<b>היו\"ד. . הצמצום</b>: ראה אגה\"ת פ\"ד. סה\"מ תרל\"ח ע' קו. וש\"נ."],["224","49","<b>להיות לו דירה בתחתוני'</b>: ראה לקמן המשך מצה זו ספנ\"ט הערה 1693."],["225","50","<b>אתוון רברבין</b>: נסמן לעיל בהערה 32."],["226","51","<b>בסידור בענין קי\"ס</b>: שער חג המצות רפט, ג."],["227","52","<b>שר המשקים. . מים ויין. . בפנימי'. . וחיצוני' התו'</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670064\" data-slug=\"torat-chaim\" data-id=\"2300670064\">תו\"ח לך צא, ג</a>. מאמרי אדה\"א בראשית ע' תפא. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370454\" data-slug=\"torah-or\" data-id=\"3901370454\">תו\"א תו\"א ויחי קב, ד</a>. מאמרי אדה\"ז תקס\"ג ח\"א ע' פא ואילך. ע' צ ואילך."],["228","53","<b>ושר הטבחי'. . אהבה ברשפי אש</b>: ראה תו\"א שם. מאמרי אדה\"ז שם ע' פב וע' צא. מאמרי אדה\"א שם ע' תפב."],["229","54","<b>צואר אותיות רצוא</b>: ראה לקו\"ת להאריז\"ל פ' עקב ע\"פ ארץ חטה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770408\" data-slug=\"or-hatorah-hb\" data-id=\"8316770408\">אוה\"ת</a> בראשית כרך ג ע' 966. שבועות ע' קכב. שה\"ש ח\"ב ע' תח. סה\"מ תרל\"ח ריש ע' שפג."],["230","55","<b>ושר האופים. . דיבור דתורה</b>: ראה תו\"א ומאמרי אדה\"ז שם. מאמרי אדה\"א שם ע' תפד ואילך."],["231","56","<b>דוד. . המל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דוד. הנסמן המאמרי אדה\"א דברים ח\"ג ע' תתקט."],["232","57","<b>שכאו\"א יכוין. . קה\"ק</b>: ברכות ל, א. שו\"ע אדה\"ז הל' תפלה ר\"ס צד."]]],[2000470104,"היינו להיות כי ענין התפלה הוא התעוררות רצה\"ע שלמעלה אפי' ממקור החכ'<sup data-n=\"233\">58</sup>, ולכן יוכל להפך ממות לחיים כי אעפ\"י שנמדד ע\"פ משפט התו' כו' יוכל ע\"י התפלה להתהפך לחיים, והיינו כי עצם הרצון הוא אין טעם לרצון<sup data-n=\"234\">59</sup> אפי' טעם הכמוס שהוא מקור הטעם לא יכיל אותו, ולכן כאשר יתעורר הרצון יהפך הכל וכמא' מחוק ברחמיך הרבים<sup data-n=\"235\">60</sup> כו', ולכן נק' התפלה בקשת הרחמים שהוא התעוררות ר\"ר מעצם הרצון. וז\"ע סמיכת גאולה לתפלה<sup data-n=\"236\">61</sup>, כי מס\"נ שבק\"ש עולה לעצמות הרצון ועי\"ז מעוררי' שפע עצמות הרצון להיות נמשך ביחוד העליון הנק' גואל, וצריך להסמיכו לבחי' המל' דאצי' הנק' תפלה<sup data-n=\"237\">62</sup> בכדי שיהי' ההיפוך למטה בצירופי' ואותיות הנמשכי' במדת המלוכה להפך ממות לחיים בפו\"מ.\n<b>וזהו</b> עיקר אתוון רברבין שהוא המשכת האותיות שבעצמי' הרצון שלמעלה ממקור החכ', ועז\"נ ג\"כ ולגדולתו אין חקר<sup data-n=\"238\">63</sup> כו', והנה עיקר התגלו' עצמות הרצון הוא בבחי' הבינה דאצי' כידוע דהתגלות ע\"י הוא בבינה<sup data-n=\"239\">64</sup> כו', ולכן נק' הבינה פום ממלל רברבן<sup data-n=\"240\">65</sup> שהוא ממשיך בחי' אתוון רברבין שבעצמות הכתר, ולכן צריך לכוין תפלתו נגד קדה\"ק שהוא ג\"כ בבחי'<sup data-n=\"241\">66</sup> הבנה<sup data-n=\"242\">67</sup> כידוע, וז\"ע בנוי לתלפיות תל שכל פיות פונים אליו שהוא קיבוץ כל הפיות ע\"י ביטול רצון שמתאחדים כולם ונכללי' בבחי' פה העליון הנק' פום ממלל רברבן כנ\"ל ועי\"ז פועלים המשכת הרצון כו'. והנה מעלה זאת נכלל ג\"כ בבחי' מגדל דוד כי ענין המגדל הוא הבולט למעלה מן החומה כו', כך למעלה יש בחי' ממכ\"ע והוא השפע המתלבשת בבחי' כלים ואותיות ונק' עיר אלקינו כו' ושרש ומקור השפע זאת הוא מבחי' ח\"ע דאצי' כו', אך בחי' המקיפי' הוא נק' בחי' חומה לעיר כו' והוא בחי' מקור דח\"ע כו' שמאיר בבחי' מקיפי', אך המגדל הוא למעלה מן החומה, ולמעלה הוא בחי' המשכת עצמות הרצון שלמעלה אפי' ממקור החכ' שבזה מלובש אור העצמות שלמעלה מבחי' סובב כו', וזהו כמגדל דוד שהצואר שהוא בבחי' בהמ\"ק מגיע בבחי' מגדל דוד שהוא אור העצמות שלמעלה מסובב וממלא כו'.",[["233","58","<b>התפלה הוא התעוררות רצה\"ע. . החכ'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381302\" data-slug=\"likkutei-torah\" data-id=\"4001381302\">לקו\"ת שה\"ש מג, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מקץ מב, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370193\" data-slug=\"torah-or\" data-id=\"3901370193\">מג, סע\"א</a> ואילך. סידור שער החנוכה רעג, ב ואילך. לקמן המשך זאת חנוכת המזבח רפכ\"ב."],["234","59","<b>אין טעם לרצון</b>: ראה של\"ה ד, ב. מאמרי אדה\"א דברים ח\"א ע' כא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540394\" data-slug=\"torat-chaim\" data-id=\"2300540394\">תו\"ח בא ח\"א פט, ד</a>. וש\"נ."],["235","60","<b>מחוק ברחמיך הרבים</b>: נוסח רבש\"ע בק\"ש שעהמ\"ט."],["236","61","<b>סמיכת גאולה לתפלה</b>: ברכות ט, ב."],["237","62","<b>המל'. . תפלה </b>: ראה פע\"ח שער התפלה בתחלתו. סה\"מ תרל\"ח ע' מג. וש\"נ."],["238","63","<b>ולגדולתו אין חקר</b>: תהלים קמה, ג."],["239","64","<b>דהתגלות ע\"י הוא בבינה</b>: ראה זהר קרח קעח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670111\" data-slug=\"torat-chaim\" data-id=\"2300670111\">תו\"ח לך פא, ב</a>. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["240","65","<b>הבינה פום ממלל רברבן</b>: דניאל ז, ח. כ [ושם: ופם]. ראה ע\"ח שער טנת\"א ש\"ה, פ\"ג. מאו\"א מערכת פה אות ב וביאיר נתיב שם."],["241","66","<b>קדה\"ק. . בבחי' הבינה</b>: ראה ביאוה\"ז להצ\"צ כרך ב פ' יתרו ע' תשפד. לקמן המשך מצה זו ספט\"ז."],["242","67","<b>הבנה</b>: בבוך 744: הבינה."]]],[2000470105,"<b>ואח\"כ</b> א' אלף המגן<sup data-n=\"243\">68</sup> תלוי עליו כל שלטי הגבורים, כי הנה שלטי הגבורים הם אותם הגבורים הכובשים את יצרם כו' וכמארז\"ל איזהו גבור<sup data-n=\"244\">69</sup> כו' ונק' גבורי כח<sup data-n=\"245\">70</sup> שהתגברות זאת נמשך מבחי' כח מ\"ה דחכ'<sup data-n=\"246\">71</sup>, והנה ע\"י שכובשים את יצרם גורם למעלה ג\"כ בחי' המשכת הרצון ורחמים לכבוש את הכעס וכמא' יה\"ר<sup data-n=\"247\">72</sup> מלפניך<sup data-n=\"248\">73</sup> שיכבשו רחמי את כעסי כו', וזהו אלף המגן תלוי עליו כי מגן הוא בעולם הבריאה הנמשך מש' הוי' דאצי' ע\"י פרסא המפסיק<sup data-n=\"249\">74</sup> שזהו ענין כי שמש ומגן<sup data-n=\"250\">75</sup> הוי' אלקי', ומ\"ש אלף המגן כי בעולם הבריאה המספר הוא אלף בגי' אל שדי<sup data-n=\"251\">76</sup> במילואו עם הכולל שמאיר שם הנ\"ל בעולם הבריאה<sup data-n=\"252\">77</sup> והוא נמשך מבחי' שם אל שבדיקנא כמבואר באד\"ר<sup data-n=\"253\">78</sup>, ולכן נאמר ג\"כ בה\"ר דרביעא על אלף טורין<sup data-n=\"254\">79</sup> שהוא ג\"כ ירידת המל' דאצי' בעולם הבריאה שהוא מספר אלף, ולזה א' שכל אלף המגן עיקר קיומם הוא מבחי' בהמ\"ק הנ\"ל ששם המשכות הרצה\"ע וכו'. וזהו ג\"כ כל שלטי הגבורים, כי הכח לכבוש את יצרם הוא ג\"כ נמשך מלמעלה כמא' אלו<sup data-n=\"255\">80</sup> הקב\"ה עוזרו<sup data-n=\"256\">81</sup> לא הוי יכול לו כו', וזהו ג\"כ מצד המשכת עצמי' הרצון כו'.",[["243","68","<b>אלף המגן</b>: המשך הכתוב כמגדל דוד צוארך."],["244","69","<b>איזהו גבור</b>: אבות פ\"ד, מ\"א."],["245","70","<b>גבורי כח</b>: תהלים קג, כ."],["246","71","<b>כח מ\"ה דחכ'</b>: זהר רע\"מ צו כח, א. לד, א. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 39. הנחה ד\"ה וירא העם וינועו על יד הערה 66."],["247","72","<b>יה\"ר מלפניך שיכבשו</b>: ע\"פ ברכות ז, א."],["248","73","<b>מלפניך</b>: בבוך 984 (בהנחת ר' הלל): נרשם סימן מחיקה על תיבה זו."],["249","74","<b>הבריאה. . דאצי'. . פרסא המפסיק</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא."],["250","75","<b>כי שמש ומגן</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך."],["251","76","<b>אלף בגי' אל שדי</b>: ראה מבו\"ש ש\"ג ח\"ב פט\"ו. לקו\"ת להאריז\"ל דברים (עה\"פ יוסף ה'). מאמרי אדה\"ז תקס\"ח ח\"ב ע' תרנא. תו\"א חנוכה מא, ב. אוה\"ת וארא ריש ע' קנה."],["252","77","<b>אל שדי. . בעולם הבריאה</b>: שם. פע\"ח שער הק\"ש פ\"א."],["253","78","<b>שם אל שבדיקנא כמבואר באד\"ר</b>: ראה זהר נשא קלא, ב."],["254","79","<b>בה\"ר דרביעא על אלף טורין</b>: ראה זהר בראשית יח, ב. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' יב."],["255","80","<b>אלו</b>: וכ\"ה בבוך 243. ובבוך 1139. בסה\"מ תר\"ל: לולא. בבוך 744: אילולא."],["256","81","<b>אלו הקב\"ה עוזרו</b>: ראה קדושין ל, ב. סוכה נב, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא רפי\"ג</a>."]]],[2000470106,"<h3>גור ארי'</h3>\n<b>בס\"ד פ' ויחי</b>\n<b></b>דמיון השבטים לחיות כו' כל הגדול מחברו כו' נה\"ר מזיעתן של חיות – ג\"פ. ב' קיצורים\nויחי\n<b>גור</b> ארי'<sup data-n=\"257\">1</sup> יהודה<sup data-n=\"258\">2</sup> כו' וכתיב יששכר חמור גרם<sup data-n=\"259\">3</sup>, ובדן אמר יהי דן נחש<sup data-n=\"260\">4</sup>, נפתלי<sup data-n=\"261\">5</sup> אילה שלוחה, בנימין זאב יטרף<sup data-n=\"262\">7</sup>. וצ\"ל מה שדימה השבטים לחיות טמאות<sup data-n=\"263\">6</sup>, ואת דן דימה עוד לנחש כו' שלכאו' אינו מובן כלל מהו המעלה בזה, כי מה שדימה יהודה לארי' הנה הוא עכ\"פ מלך שבחיות<sup data-n=\"264\">9</sup>, אבל שארי השבטים שדימה אותם לשארי חיות ובהמות טמאות<sup data-n=\"265\">8</sup> מהו יתרון המעלה בזה כו', האם לא מצא דמיון אחר כ\"א לדמות את ישכר שנטה שכמו לסבול עול תורה כ\"א לחמור הנושא וסובל משאו, ואת נפתלי לאילה, ובנימין לזאב הטורף ודורס<sup data-n=\"266\">10</sup> שכולם הם חיות ובהמות טמאות כו'. אך הענין יובן ע\"פ משנ\"ת במ\"א בענין תירוץ הקושי' במ\"ש פני ארי' אל הימין<sup data-n=\"267\">11</sup> ופני שור מהשמאל שמובן ונודע לכל מעלת הימין<sup data-n=\"268\">12</sup> על השמאל, וא\"כ גבהה וגדלה מעלת בחי' הארי' שבמרכבה על בחי' שור, ומדוע למטה הארי' הוא חיה טמאה<sup data-n=\"269\">13</sup>, ואם<sup data-n=\"270\">14</sup> היות כי הוא מלך שבחיות זהו לפי שכחו גדול יותר א\"כ בחי' החי שבו הוא ביתרון על כל החי' והבהמה, אבל מ\"מ הנה הוא חי' טמאה ושור הוא בהמה טהורה, אשר ההבדל שביניהם רב הוא, שזה באפשר להעלותו, והטמא א\"א להעלותו כ\"א ריחוקו והבדילות ממנו זהו תקנתו, וכענין כלי חרס שבירתו עד שאינו ראוי' לכמו שהי' תחלה זהו תקנתו<sup data-n=\"271\">15</sup>, א\"כ זהו איבודו, ולא העלתו כמו הטהור שמתעלה ע\"י אכילת אדם שנכלל ועולה ממדרגת בע\"ח לבחי' מדבר שהרי מהאכילה נעשה דם, והדם הוא הנפש אשר בו מתלבש נפש האדם כמ\"ש כי הדם הוא הנפש<sup data-n=\"272\">16</sup>, שתירצו",[["257","1","<b>גור ארי' יהודה</b>: בספר התולדות של כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"e16\">א</sup> כותב אודות מאמר זה: ”דמיון השבטים לחיות כו' כל הגדול מחברו כו' נה\"ד מזיעתן של חיות — ג\"פ. ב' קיצורים\".\nמיוסד על מאמר ד\"ה בנימין זאב יטרוף שנדפס במאמרי אדה\"ז על פרשיות התורה ח\"א ע' ריח.\nמאמר זה הובא לקמן בהמשך זאת חנוכת המזבח ספ\"י וראה בהערה שם."],["258","2","<b>גור ארי' יהודה</b>: ויחי מט, ט."],["259","3","<b>יששכר חמור גרם</b>: שם מט, יד."],["260","4","<b>יהי דן נחש</b>: ויחי שם, יז."],["261","5","<b>נפתלי אילה שלוחה</b>: שם שם, כא."],["262","7","<b>בנימין זאב יטרף</b>: ויחי מט, כז."],["263","6","<b>אילה. . לחיות טמאות</b>: וכ\"ה גם בסיום המאמר. וראה גם הערה 8."],["264","9","<b>לארי'. . מלך שבחיות</b>: חגיגה יג, ב."],["265","8","<b>שדימה השבטים. . לשארי חיות ובהמות טמאות</b>: במאמרי אדה\"ז כאן: שדימה אותם [בנימין ויששכר] לזאב וחמור שהם טמאים. . הזאב בחיות וחמור בבהמות."],["266","10","<b>לזאב הטורף ודורס</b>: ראה חולין מב, א (במשנה). שו\"ע יו\"ד סנ\"ז, ס\"א."],["267","11","<b>פני ארי' אל הימין</b>: יחזקאל א, י [ושם: ופני]."],["268","12","<b>מעלת הימין</b>: ראה שבת סא, א. לק\"ט ויחי מח, יד. שו\"ע אדה\"ז הל' השכמת הבקר ס\"ב, ס\"ד (במהדו\"ק ומהדו\"ת)."],["269","13","<b>הארי' הוא חי' טמאה</b>: ראה אוה\"ח אחרי יז, יד. (בנוסף למאמרי אדה\"ז כאן) <a class=\"ft-cite\" href=\"#/read/torah-or/3901370119\" data-slug=\"torah-or\" data-id=\"3901370119\">תו\"א וישלח כה, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381168\" data-slug=\"likkutei-torah\" data-id=\"4001381168\">מג\"א צג, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540204\" data-slug=\"torat-chaim\" data-id=\"2300540204\">לקו\"ת שה\"ש ט, ד</a>. תו\"ח וארא ח\"א נו, ב. וש\"נ. סה\"מ תרכ\"ז ע' נ. וש\"נ. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה וכל שיח השדה פ\"ב."],["270","14","<b>ואם</b>: כ\"ה בכ\"מ — ראה גם סה\"מ תרל\"ח ע' ה. וש\"נ."],["271","15","<b>כלי חרס שבירתו. . זהו תקנתו</b>: ראה כלים פ\"ב, מ\"א."],["272","16","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג. ראה גם לקמן המשך זאת חנוכת המזבח פ\"ה.\n\n<b>א</b>  קה\"ת תש\"ז — ברשימת מאמרי שנה זו — ע' 51."]]],[2000470107,"ע\"ז כי להיות הארי' הוא גבוה מאד נעלה בשרשו לכן בירידתו למטה להתלבש בגוף בע\"ח א\"א לו להתלבש כ\"א בגוף חי' טמאה שהוא גס ועב יותר הרבה מכמו גוף בהמה טהורה שהוא אכילת המדבר כו', וכמו בכותל חומה הנופל לארץ הנה האבן אשר בראש הכותל<sup data-n=\"273\">*17</sup> נופל למרחוק יותר, וסיבת נפילתו למרחוק כ\"כ זהו מפני כי הי' תחילה גבוה יותר. ויובן עוד ממה שאנו רואים שהראי' היא במעלה יותר עליונה מבחי' השמיעה, שלכן גזרו אומר שאינו דומה שמיעה לראי'<sup data-n=\"274\">17</sup>, והיינו שמה שנקנה בכח הנפש ע\"י הראי' גדול במעלה עליונה ודביקות יותר מבחי' השמיעה כמשנ\"ת מזה באורך בד\"ה וככה<sup data-n=\"275\">18</sup> תאכלו אותו בענין ההפרש בין מוחין דאבא למוחין דאימא כו' ע\"ש, ומדוע בהתפשטותם בגוף האדם הנה הראי' תופסת דבר גשמי דוקא עצם ומהות הדבר כמו שנשפל בגשמיותו, ואיננה תופסת דבר רוחני כלל כמו קול, שגשמיותו הוא ג\"כ דק ורוחני, משא\"כ שמיעה תופס דבר הרוחני כמו הקול ונעימות כלי שיר וכלי זמר כו', והגשמי כמו כל הדברים שנשפלו להיות בחומר וציור החומר גשמי אין השמיעה תופסת אותם, ולכאו' נהפוך הוא, אלא שהיא הנותנת שלהיות כח הראי' גדול במעלה יותר לכן בהתפשטותה למטה אין לה כלי שתתלבש בה כ\"א הגשמי דוקא שהוא חומר גס, משא\"כ השמיעה היא ברוחני דוקא מפני כי בשרשה לא הגיעה למעלת הראי' כו', ועד\"ז יובן שלהיות הארי' הוא גבוה במעלות יותר על השור לכן בירידתו למטה הארה ממנו להחיות גוף גשמי בלתי אפשר שילובש בגוף טהור שהוא אינו גס כ\"כ, כ\"א דוקא בדבר טמא כחי' טמאה דוקא, ולהיותו בחי' גבוה לכן גם למטה הוא מלך שבחיות שהוא הוראה על עוצם בחי' החי שבו כו'.\n<b></b>קיצור. למה דימה השבטים לחיות ובהמות טמאות, ויובן עפמשנ\"ת שהארי' שהוא יותר במעלה למטה הנה הוא חי' טמאה, ע\"ד כמו נפילת האבנים מהחומה שהגבוה יותר נופל למרחוק יותר, והראי' דוקא תופס דבר גשמי כו'.\n(ב) <b>וביאור</b> ד\"ז יובן ע\"ד מארז\"ל כל הגדול מחבירו<sup data-n=\"276\">19</sup> יצרו גדול הימנו, אשר לכאו' יפלא מאד הלא מי שהוא גדול יותר הי' צ\"ל אצלו מציאת היצר במיעוט יותר, כי האור דוחה חשך בטבע, וא\"כ אור בהיר שאצל הגדול, שלכן נק' גדול מחבירו שהו\"ע היותו יותר בתורה ובי\"ש ובגמ\"ח כו', וא\"כ מדוע עוד יגרע",[["273","*17","<b>האבן אשר בראש הכותל</b>: מובא בכ\"מ ומהם: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370435\" data-slug=\"torah-or\" data-id=\"3901370435\">תו\"א מג\"א צז, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380244\" data-slug=\"likkutei-torah\" data-id=\"4001380244\">לקו\"ת אמור לט, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381023\" data-slug=\"likkutei-torah\" data-id=\"4001381023\">פ' ראה (יט, ג</a>) כא, רע\"ג ובהנסמן במ\"מ לשם. האזינו עה, א. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשפז. תקס\"ו ע' קנד. סהמ\"צ להצ\"צ ע' קצ. לקמן המשך זאת חנוכת המזבח פי\"ט. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת על יד הערה 56. (בחלק ההנחות) בהנחה שם על יד הערה 70."],["274","17","<b>שאינו דומה שמיעה לראי'</b>: ראה מכילתא יתרו יט, ט. לק\"ט שלח יג, יח. מאמרי אדה\"א דברים ח\"א ע' קמו ואילך. שה\"א ט, ב הערה 14. סה\"מ תרכ\"ז ע' שמט. וש\"נ. תרל\"ב ח\"א ע' י. וש\"נ. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה וזהו שרש יונתי על יד הערה 53. ד\"ה להבין שרש ענין מקיפים דבינה ספ\"ב. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה משה קבל פיסקא ויובן."],["275","18","<b>בד\"ה וככה</b>: תרל\"ז פל\"ג. וראה גם שם פנ\"ז."],["276","19","<b>כל הגדול מחבירו</b>: סוכה נב, סע\"א. ראה מאמרי אדה\"ז על מארז\"ל ע' פה ובהנסמן במ\"מ לשם. הנסמן במאמרי אדה\"א נ\"ך ע' שנא."]]],[2000470108,"חלקו שיצרו יהי' גדול הימנו. אך הענין הוא דהיא הנותנת וכנ\"ל, ויובן זה מענין המדות אהבה ויראה שכלליות ענין המדות בעבודה הוא בחי' ההתפעלות בתוקף הן באהבה והן ביראה שב' מדות אלו דחו\"ג כוללים כלליות המדות (ובמ\"א נת' שחסד עצמו כולל כל המדות<sup data-n=\"277\">20</sup> ) ומבחי' תוקפם וחזקם מסתעף אח\"כ גם בחי' הגבורות קשות. ויובן זה מענין בחי' ההסתעפות שנמצא מבחי' מדת הגבורה ביותר נקל, דהנה אנו רואים<sup data-n=\"278\">21</sup> שיש איזה אנשים שמתהנים כשעושים דין קשה באדם כמו שלוחי ב\"ד בימים הקדמונים, שהיו מכים ועונשים ע\"פ ב\"ד, או אנשים כשמוצאים איש שעבר על דיני התורה שמתמלאים עליו אף וחימה ופיו ולבו שוים לנקום ולנטור מאיש הזה ולבבו בוער עליו כאש ושלהבת העולה מאליה<sup data-n=\"279\">22</sup> ומתלהבת ומתלהטת, ואומרים כי קנאת ה' צבאות<sup data-n=\"280\">23</sup> היא מדוע עבר על פקודי אורייתא כו' לכן ילקה במכות נאמנות שיקבל ע\"י יסורים קשים ומרים, ובאמת א\"ז מצד קנאת ה' צבאות כ\"א ששרשם מבחי' הגבורות, אשר בהשתלשלות נמשך גבורות קשים ורעים לנקום נקם<sup data-n=\"281\">24</sup>, ומה שאו' שקנאת ה' צבאות הוא זה שזהו פנימיות החסד בכדי למרקו מעוונו וה' יסלח לו<sup data-n=\"282\">25</sup>, הנה זהו רק הלבשה שמלביש פנימיות רצונו בלבוש נאה בעיני הבריות אשר האדם יראה לעינים בלבד, אבל ה' יראה ללבב<sup data-n=\"283\">26</sup> שזהו מפני כי שרשם ומקורם הוא בחי' הגבורות קדושות כו' רק שבהשתלשלו' למטה נמשך מזה גבורות קשות לנקום נקם כו'. וע\"ד שנהר דינור יוצא מזיעתן של חיות<sup data-n=\"284\">27</sup> הקדש<sup data-n=\"285\">28</sup>, על ראש רשעים יחול<sup data-n=\"286\">29</sup> בגיהנם, שמצד גודל הפחד ורתת וזיע של חיוה\"ק הנה הזיעה שז\"ע הפסולת, כמו זיעה שבאדם<sup data-n=\"287\">30</sup> שזהו הפסולת שנבדל מהחום, שלכן החולה שיש לו חום זר כשמזיע מתרפא, והיינו שיוצא החום ונעשה לחלוחית מים שיוצאי' מנקבי הזיעה ועי\"ז מתרפא החולה, כן תוקף החום מחמת האימה ופחד<sup data-n=\"288\">31</sup> של חיוה\"ק בעבודתם בבחי' המרכבה שבטלים להרוכב כו' הפסולת היוצא מהם שזה נמשל לזיעה שהיא פסולת החום שבאדם שהי' למים כו' הנה מהזיעה של חיוה\"ק נהר דינור יוצא על ראש רשעים יחול בגיהנם למרק אותם מעוונם שזהו תכלית הטוב<sup data-n=\"289\">32</sup>",[["277","20","<b>שחסד. . המדות</b>: ראה ביאוה\"ז עקב קכ, ג. סידור סדר הגדה חצר, ג. מאמרי אדה\"ז תקס\"ה ח\"א ע' תמ. תקס\"ו ע' רג."],["278","21","<b>דהנה אנו רואים. . תרתין אחתין</b>: ראה ביאוה\"ז אמור קמ, ד. ולהצ\"צ שם כרך ב ע' תתקכז ואילך. ע' תתקנה. מאמרי אדה\"ז (כאן ו) תקס\"ה ח\"א ע' תעה (וע' נא). סהמ\"צ להצ\"צ ע' 178. סה\"מ תרכ\"ו ע' פח ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380410\" data-slug=\"likkutei-torah\" data-id=\"4001380410\">לקו\"ת נשא כה, ג</a>. מאמרי אדה\"א הנחות תקע\"ז ע' מא ואילך."],["279","22","<b>ושלהבת העולה מאליה</b>: ע\"פ רש\"י בהעלותך ח, ב."],["280","23","<b>קנאת ה' צבאות</b>: ע\"פ ישעי' ט, ו. לז, לב."],["281","24","<b>הגבורות. . לנקום נקם</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081174\" data-slug=\"likkutei-sichot\" data-id=\"1300081174\">לקו\"ש</a> פינחס כרך ח ע' 163. וש\"נ."],["282","25","<b>וה' יסלח לו</b>: ע\"פ מטות ל, ו. ט. יג."],["283","26","<b>האדם יראה לעינים. . ה' יראה ללבב</b>: ע\"פ שמואל-א טז, ז."],["284","27","<b>שנהר דינור. . של חיות</b>: ראה חגיגה יג, ב."],["285","28","<b>הקדש</b>: כ\"ה גם בסה\"מ תרל\"ח ריש ע' קמב. וש\"נ. מאמרי אדה\"ז אתהלך לאזניא ע' לה. מאמרי אדה\"א נ\"ך ע' שיח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680446\" data-slug=\"torat-chaim\" data-id=\"2300680446\">תו\"ח תולדות קס, ב</a>. וראה גם ביאוה\"ז שם. סה\"מ תר\"ל ע' שיג."],["286","29","<b>על ראש רשעים יחול</b>: ירמי' כג, יט. ל, כג."],["287","30","<b>זיעה שבאדם</b>: ראה גם בענין הזיעה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550765\" data-slug=\"torat-chaim\" data-id=\"2300550765\">תו\"ח ויקהל ח\"ב תט, ד</a> ואילך. וש\"נ."],["288","31","<b>הזיעה. . האימה ופחד</b>: ראה תו\"א וישב ל, ד. מאמרי אדה\"ז אתהלך לאזניא ותו\"ח שם."],["289","32","<b>למרק. . תכלית הטוב</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380529\" data-slug=\"likkutei-torah\" data-id=\"4001380529\">לקו\"ת</a> <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380667\" data-slug=\"likkutei-torah\" data-id=\"4001380667\">נשא שם. קרח נג, ד</a>. מטות פו, סע\"ב. מאמרי אדה\"א דברים ח\"ב ע' תרד-תרח."]]],[2000470109,"והחסד בכדי שיוכלו אח\"כ ליהנות מזיו השכינה בג\"ע התחתון והעליון, וכמשנ\"ת מזה במאה\"ז רזא דסתרא דא כו'<sup data-n=\"290\">33</sup> תרתין אחתין, ועמ\"ש במ\"א שדוד נק' איש הדמים<sup data-n=\"291\">34</sup> הגם כי הי' אדמוני עם יפה עינים<sup data-n=\"292\">35</sup> שארז\"ל יושב ודן בסנהדרין<sup data-n=\"293\">36</sup>, ומלחמות מצוה כו' עכ\"ז נק' איש הדמים אלא שזהו לפי שמ' במשפט יעמיד ארץ<sup data-n=\"294\">37</sup>, וגם זהו חסד כמ\"ש והוכן בחסד כסא<sup data-n=\"295\">38</sup> שזהו תכלית הטוב בכדי למרק העון כו'. ועד\"ז יובן בענין שפיכת הנפש לפני הוי' וכמ\"ש בחנה ואשפוך את נפשי<sup data-n=\"296\">39</sup> לפני הוי', עכ\"ז מסתעף מזה אח\"כ מדת הכעס ג\"כ רק שזהו על ההיפוך, וכמ\"ש כי מרוב שיחי וכעסי דיברתי עד הנה<sup data-n=\"297\">40</sup> כו'. ובזה יובן מ\"ש וחרה אף ה'<sup data-n=\"298\">41</sup> בפ' שני' דק\"ש, שלכאו' אין כאן מקומו כלל לענין בחי' חרון אף ה' כו', שהרי נא' שם והא\"ש תשמעו<sup data-n=\"299\">42</sup> ומ\"ע חרון אף ה', אלא שהכעס הוא על ההיפוך כמ\"ש פן יפתה לבבכם<sup data-n=\"300\">43</sup> כו' שזהו דוקא כשתשמעו ואז נופל הכעס כשפנה לבבו כו', ונא' זה בפ' שני' שהיא בחי' גבורה כנודע, ששמע והא\"ש הם חו\"ג<sup data-n=\"301\">44</sup> כו', אמנם באמת גם בבחי' מדת החסד שייך ג\"כ שיסתעף ממנה הכעס, והיינו מב' טעמים, הא' כי החסד הוא מורכב מהגבורה שהרי זהו בבחי' התיקון כו', וא\"כ כשם שהחסד שבגבורה אינו מעציר הסתעפות בחי' הכעס על ההיפוך במדת הגבורה כן בחי' גבורה שבחסד פועל שגם מצד החסד יומשך הכעס על האיש בליעל העושה רע, וגם על מי שעוסק בהבליות כו' ופונה לבו לבטלה כו', והב' דאם היות שהחסד עצמו הוא כולו לגמול הטוב גם לעושה רע ומפנה לבו הנ\"ל, עכ\"ז מצד בחי' תגבורת החסד מצד זה הנה הוא מקורה בתגבורת החיות אשר מזה נמשך בחי' הכעס על ההיפך, היינו בראותו אח\"כ אנשים הולכים בהבליות, אזי יבער בו כאש חמתו בקנאתו קנאת ה' צבאות באש תבערה, וכל שתהי' האהבה יותר גדולה וחזקה בתגבורת האהבה יותר יהי' הכעס על ההיפך ג\"כ יותר (ואמנם צ\"ל מדוע א' אברהם לו ישמעאל יחי' לפניך<sup data-n=\"302\">45</sup> היתכן שלא ידע את ישמעאל<sup data-n=\"303\">46</sup>, ומצד היותו בבחי' חסד גמור נת' במ\"א שמצד טבעו הטוב להטיב גם למי",[["290","33","<b>כו'</b>: כ\"ה בהכת\"י."],["291","34","<b>שדוד נק' איש הדמים</b>: שמואל-ב טז, ז. ראה גם סה\"מ תרכ\"ו ע' קלא וע' קלג. תרכ\"ט ע' ב. תרל\"ב ח\"ב ע' תקנ."],["292","35","<b>אדמוני עם יפה עינים</b>: שמואל-א טז, יב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380211\" data-slug=\"likkutei-torah\" data-id=\"4001380211\">לקו\"ת אמור לא, סע\"ב</a>. סידור שער התפילין יג, ד ואילך."],["293","36","<b>יושב ודן בסנהדרין</b>: ראה ב\"ר פס\"ג, ח."],["294","37","<b>שמ' במשפט יעמיד ארץ</b>: משלי כט, ד."],["295","38","<b>והוכן בחסד כסא</b>: ישעי' טז, ה."],["296","39","<b>שפיכת הנפש. . ואשפוך את נפשי</b>: שמואל-א א, טו. ראה גם לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויאמר כו' לך לך על יד הערה 67."],["297","40","<b>כי מרוב. . הנה</b>: שם שם, טז."],["298","41","<b>וחרה אף ה'</b>: עקב יא, יז. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה סוכה שחמתה מרובה מצלתה פיסקא והנה נת'."],["299","42","<b>והא\"ש תשמעו</b>: עקב שם, יג."],["300","43","<b>פן יפתה לבבכם</b>: שם יא, טז."],["301","44","<b>ששמע והא\"ש הם חו\"ג</b>: ראה לקו\"ת ואתחנן יב, ד. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן במ\"מ לשם."],["302","45","<b>לו ישמעאל יחי' לפניך</b>: לך יז, יח."],["303","46","<b>היתכן שלא ידע את ישמעאל</b>: ראה לקמן המשך מצה זו פמ\"ד על יד הערה 1371 ואילך. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמוכים לעד על יד הערה 19. הנחה ד\"ה ערבים עלי דברי דודיך על יד הערה 55. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו\"א לך יב, א</a>. תו\"ח ח\"ש קכו, א ואילך. אוה\"ת שם קכא, א. סה\"מ תרל\"ח ע' רפט."]]],[2000470110,"שאינו ראוי כמו שמי שהוא חסדן בטבעו אינו מדקדק כלל ליתן למי שראוי דוקא, כ\"א פותח את ידו להשביע כל רצון איש ואיש היינו גם למי שאינו ראוי כלל<sup data-n=\"304\">47</sup>, ולכן אברהם שהי' בתכלית בחי' הטוב והחסד כמ\"ש<sup data-n=\"305\">48</sup> בפרד\"ס<sup data-n=\"306\">49</sup> בשם ס' הבהיר<sup data-n=\"307\">50</sup> שאמרה מדת החסד כל ימי היות אברם בארץ<sup data-n=\"308\">51</sup> לא הוצרכתי לעשות מלאכתי שהרי אברם עומד ומשמש במקומי, וכמ\"ש מזה במ\"א שהחליף מקום בחי' מדת החסד<sup data-n=\"309\">52</sup>, ובס' או\"צ<sup data-n=\"310\">53</sup> בשער י\"ז הוא שער הנדיבות נת' שאברהם הי' נדיב בין בגופו בין בממונו בין בנפשו, לכן אמר לו ישמעאל יחי' לפניך, ולפמשנ\"כ צ\"ל בהיפך, אלא שנא' שמצד תגבורת החסד שהי' באברהם שלא הי' בשום איש זולתו לא מצא כלל רע בישמעאל, והמופת לזה שהרי שרה א\"ל גרש האמה הזאת<sup data-n=\"311\">54</sup> כו', משא\"כ הוא מצ\"ע נא' וירע הדבר מאד בעיני אברהם על אודות בנו<sup data-n=\"312\">55</sup> כו'<sup data-n=\"313\">56</sup>, כי הביט בעין חמלה על כל זולתו עד שלא מצא בו רע כלל, משא\"כ מי שהוא בתגבורת בחי' אהבה לאלקות עכ\"ז לזולתו הנה הוא רואה היפוכו, ואדרבה כל שהאהבה גדולה יותר לא יוכל להביט במי שנמשך אחר ההבליות כו').\n<b></b>קיצור. שכל הגדול מחבירו יצרו גדול, ויובן מענין אהוי\"ר שמסתעף מהם בחי' הכעס על ההיפך, בקנאם קנאת ה' צבאות כו', ובאמת זהו סיגי הגבורות, וז\"ע וחרה אף שנא' בפ' שני' של ק\"ש.\n(ג) <b>והנה</b> הכעס בעצם מציאותו לא טוב<sup data-n=\"314\">57</sup>, ועכ\"ז מתהוה דוקא מצד הקדושה והיינו מבחי' האהוי\"ר לאלקות כנ\"ל, שהרי מי שאין לו אהוי\"ר לגמרי לא יכעוס כלל גם על הרשע ואוהב חמס, וכמו שאנו רואי' שמי שהוא עובד ה' באהוי\"ר לא יוכל לסבול את מי שהולך בטל, וכמארז\"ל שבת דל\"ג ב' שתמה רשב\"י מניחים",[["304","47","<b>שמצד טבעו. . שאינו ראוי כלל</b>: ראה לקמן המשך מצה זו שם על יד הערה 1368. שם הנחה ד\"ה ערבים עלי דברי דודיך על יד הערה 53. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370118\" data-slug=\"torah-or\" data-id=\"3901370118\">תו\"א שם. וישלח כה, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370518\" data-slug=\"torah-or\" data-id=\"3901370518\">ויקהל קטז, ב</a>. מאמרי אדה\"ז תקס\"ה ח\"א ע' שעו (נו\"ש). סה\"מ תרכ\"ט ע' רכז. המשך מים רבים תרל\"ו ע' נט."],["305","48","<b>כמ\"ש בפרד\"ס</b>: ראה שער טעם האצילות ש\"ב, פ\"ב. שער הכנויים שכ\"ב, פ\"ד (בשינוי קל). ראה גם סה\"מ תרס\"ג ח\"ב ע' צא."],["306","49","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["307","50","<b>ס' הבהיר</b>: סקצ\"א (בשינוי קל). זח\"א בהשמטות רסד, ריש ע\"ב."],["308","51","<b>בארץ</b>: ראה גם לעיל מאמר ד\"ה ואעשך לגוי גדול ובהערה 10."],["309","52","<b>אברם. . שהחליף. . מדת החסד</b>: ראה לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 643 שמציין: בד\"ה ואעשך לגוי גדול<sup data-n=\"e17\">ב</sup>. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ערבים עלי דברי דודיך על יד הערה 51. (בחלק ההנחות) הנחה ד\"ה כמים הפנים על יד הערה 31. סה\"מ תרל\"ו ח\"ב ע' רנב. תרע\"ח ע' שמ."],["310","53","<b>ובס' או\"צ</b>: ראה לעיל מאמר ד\"ה ואעשך לגוי גדול ובהערה 12."],["311","54","<b>גרש האמה הזאת</b>: וירא כא, י."],["312","55","<b>וירע הדבר. . בנו</b>: וירא שם, יא."],["313","56","<b>כו'</b>: כ\"ה בהכת\"י."],["314","57","<b>הכעס. . לא טוב</b>: ראה אגה\"ק סכ\"ה. סה\"מ תרכ\"ז ע' תק. וש\"נ.\n\n<b>ב</b>  אולי הכוונה למאמר ד\"ה זה שנדפס לעיל*. ראה שם בתחילתו.\nמשנת תרל\"ו ונאמר עוד הפעם בשנה זו."]]],[2000470111,"חיי עולם ועוסקים בחיי שעה, והטעם מפני שכל דבר יש בו פסולת מחמת עה\"ד טו\"ר, לכן גם מהאהבה מתגלה אח\"כ הפסולת והוא הכעס, וכמשל השמרים שביין, וז\"ע הארי' שהוא בגימ' גבורה<sup data-n=\"315\">58</sup>, והיינו בחי' תגבורת החסד שהרי פני ארי' אל הימין, ובעבודה זהו בחי' האהבה לה' בבחי' תגבורת גדול מאד, ועכ\"ז למטה הוא מזיק הטורף ודורס ואין מידו מציל כ\"א ה' לבדו, ולכן הי' הנס דדניאל<sup data-n=\"316\">59</sup> גדול מאד, והיינו מפני כי גם בשרשן בבחי' האהבה יש פסולת והוא בחי' הכעס על ההיפך, וכמארז\"ל מזיעתן של חיוה\"ק נהר דינור יוצא על ראש רשעים יחול בגיהנם וכנ\"ל, והיינו להיות כי עמידת היינו בחי' ביטול החיות הוא באימה וביראה וברתת<sup data-n=\"317\">60</sup> ולכן עי\"ז שהם זעים מחיל כסא<sup data-n=\"318\">61</sup> נמשך הזיעה שהיא בחי' הפסולת כנ\"ל, ויש לפרש זה בשני דרכים הא' שע\"י תוקף החום מגרש דבר שכנגדו חוצה וזהו סיבת הזיעה שמזיע האדם בהיותו במקום חם כמו במרחץ וכדומה, הב' שהחום בעצם בהיותו חם ויבש אינו מזיע וכמו החולה בתוקף חומו כו', וכשהחולה מתחיל להתרפאות זהו כשהחום נעשה חם ולח ואז עצם החום מתהפך לצאת ע\"י הזיעה כו' ומזה מתרפא החולה כו', ועד\"ז יובן ענין זיעתם של חיוה\"ק, וכמו\"כ יובן ענין בחי' הפסולת היוצא מבחי' תוקף תגבורת אהבת הארי' שהוא בחי' הכעס על ההיפך, ולפי ערך תוקף תגבורת האהבה כ\"ה בחי' תגבורת הזיעה הוא הכעס כו' להיות למטה בחי' גבורות קשות וטורף ודורס, וקולו מטיל אימה על זולתו וקול הארי' עצמו מפחד זולתו פחדי מות כו', אשר כ\"ז הוא לפי שבשרשו הוא גבוה יותר וכנ\"ל, וכמו שאנו רואים שיש בעלי חסד<sup data-n=\"319\">62</sup> למסתופפים בצלם שזהו מחמת גדלות עצמותם בעיני עצמם, ואמנם להמורד בו יהי' באכזריות גדולה וימיתהו מעט כרגע, ושניהם הם סיבה אחת ממש, שמאחר שהחסד הוא מסיבת הגדלות עצמותו, א\"כ הרי שכנגדו כלא חשיב אצלו, ולכן ימיתהו כרגע כו', משא\"כ מי שאינו יש ודבר כ\"כ בעיני עצמו, הגם כי אינו גומל חסד כ\"כ למסתופפים בצלו, אבל איננו מהיר כ\"כ ג\"כ בעונש לשכנגדו, שגם נפש זולתו נחשב אצלו למציאות יקר כו', ועד\"ז יובן בבחי' הארי' שהוא בחי' תגבורת האהבה כנ\"ל בבחי' הקדושה, לכן מבחי' הפסולת שבו, היינו ממה שנתערב בחי' הטו\"ר בשה\"כ, וכמ\"ש במ\"א שמה שנתברר תחילה נעשה בחי' המרכבה דבריאה<sup data-n=\"320\">63</sup> כו', הנה מזה נמשך הכעס שהוא בחי' דין קשה ביותר על המנגד לדעתו ועבודתו, וזהו על ראש רשעים יחול בגיהנם כו', ובירידת המדרגות בהתלבשותו בגוף גשמי נתהוה מזה ארי' הגשמי המזיק שטורף ודורס בגשמיות לכל העובר עליו כו', משא\"כ מבחי' פני שור כו', וזהו שכל הגדול מחבירו יצרו גדול הימנו, ועפ\"ז",[["315","58","<b>הארי'. . גבורה</b>: ראה פי' הראב\"ד לס\"י פ\"א, מי\"ב. מאמרי אדה\"א דברים ח\"ג ע' א'ל. וש\"נ. שה\"א עב, א הערה 5."],["316","59","<b>הנס דדניאל</b>: דניאל ו, כג."],["317","60","<b>באימה וביראה וברתת</b>: ע\"פ ברכות כב, א."],["318","61","<b>זעים מחיל כסא</b>: ראה פיוט והחיות\nב (נוסח הקדושה אשכנז) מוסף לר\"ה."],["319","62","<b>שיש בעלי חסד</b>: במאמרי אדה\"ז כאן ע' ריט: הישמעאלים הם בעלי חסד."],["320","63","<b>שמה שנתברר תחילה. . דבריאה</b>: ראה ע\"ח שער התיקון ש\"י, ספ\"א. שער מ\"ן ומ\"ד של\"ט, דרוש ג. דרוש ד. שער כללות אבי\"ע שמ\"ב, פ\"ג. ספר הליקוטים להאריז\"ל בתחלתו (ב, א ד\"ה דרוש). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380627\" data-slug=\"likkutei-torah\" data-id=\"4001380627\">לקו\"ת פנחס עו, ד</a>. לקמן המשך זאת חנוכת המזבח רפי\"ט. סה\"מ תרל\"ח ס\"ע שמט. וש\"נ."]]],[2000470112,"י\"ל לשון הימנו שזהו ממנו עצמו שהסיבה הוא מפני שבשרשו ובהתלבשותו למטה הנה הוא גדול כו'.\n<b>והנה</b> כ\"ז הוא עכשיו, אבל לע\"ל כשיתבררו כל הבירורים וכמארז\"ל עתידה<sup data-n=\"321\">64</sup> חזיר ליטהר<sup data-n=\"322\">65</sup>, אזי יהי' כאו\"א כמו שהוא בשרשו בעצם בחי' הקדושה שבו בבחי' האלקי שבו, והארי' בעצמו שרשו גבוה מאד נעלה יותר, וכערך הזה הם כל החיות ובהמות הטמאות כו' שהם הם שנפלו ממקום הגבוה למעלה ביותר שזהו עצמו הסיבה שירדו למטה מאד כנ\"ל בבחי' דילוג הערך יותר להיות חי' ובהמה טמאה כו', וזהו שדימו השבטים לחיות ובהמות טמאות יהודה לארי' ישכר<sup data-n=\"323\">66</sup> לחמור דן לנחש, נפתלי לאילה, בנימין לזאב הטורף הגם כי איננו מלך שבחיות כנ\"ל, שאין הכוונה על הזאב והחמור הגשמיים כמו שהם ירדו ונשפלו למטה, אלא על שרשם ומקורם בבחי' הקדושה ממקום שנפלו הניצוצות להיות כי בחי' הזאב והחמור עליונים ביותר, וכ\"ש הארי', שלפי ערך מעלתן בבחי' העבודה כן דימה אותם שדן נחש עלי כו' שפיפון כו', שבירר בחי' הנחש, ועלה במעלות להיות כמ\"ש בשרשו בתהו לפני השבירה כו' וכמו נחש אותיות חשן<sup data-n=\"324\">67</sup> בחי' חשן המשפט<sup data-n=\"325\">68</sup> שזהו בתיקון ועכ\"ז בערך זה יובן מעלתו בבחי' התהו, ולכן מחנה דן הי' מאסף לכל המחנות<sup data-n=\"326\">69</sup>, להיותו בחי' בירור הנחש שהוא הרע היותר גרוע<sup data-n=\"327\">70</sup>, שלהיותו תחילה ערום מכל כמ\"ש והנחש הי' ערום<sup data-n=\"328\">71</sup> כו' לכן נתקלל שהי'<sup data-n=\"329\">72</sup> ארור מכל<sup data-n=\"330\">73</sup>, וע\"י הבירור מתעלה לשרשו בתהו כמו קודם חטא עה\"ד טו\"ר כו', ומ\"מ גור ארי' יהודה דוקא שהארי' תגבורתו גדול יותר וכנ\"ל הנה בבחי' זו הארי' יותר גדול כו'.",[["321","64","<b>עתידה</b>: כ\"ה במאמרי אדה\"ז כאן ע' ריט."],["322","65","<b>עתידה חזיר ליטהר</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380837\" data-slug=\"likkutei-torah\" data-id=\"4001380837\">לקו\"ת פ' ראה ל, ב</a>. מאמרי אדה\"ז תקס\"ז ע' שכח. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680083\" data-slug=\"torat-chaim\" data-id=\"2300680083\">תו\"ח מקץ רטז, א</a> ובהערה 8. שע\"ת עג, ד ובהערה 95. פלח הרמון אמור ע' קכה. ע' קכו ובהערה 11."],["323","66","<b>ישכר</b>: ראה גם סה\"מ תרל\"ח ע' תמ. וש\"נ."],["324","67","<b>נחש אותיות חשן</b>: ראה טעמי המצות להאריז\"ל פ' תצוה מצות אפוד וחשן. סה\"מ תרל\"ח ריש ע' קצא. וש\"נ."],["325","68","<b>חשן המשפט</b>: תצוה כח, ל. כט. טו."],["326","69","<b>מחנה דן. . המחנות</b>: בהעלותך י, כה. ראה ירושלמי ערובין פ\"ה, סה\"א. הובא ברש\"י בהעלותך שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011103\" data-slug=\"likkutei-sichot\" data-id=\"1300011103\">לקו\"ש ויחי ח\"א ע' 103</a> ואילך."],["327","70","<b>הנחש שהוא הרע היותר גרוע</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380388\" data-slug=\"likkutei-torah\" data-id=\"4001380388\">לקו\"ת נשא כ, א</a>. סה\"מ תרל\"ח ע' רב. וש\"נ."],["328","71","<b>והנחש הי' ערום</b>: בראשית ג, א וברש\"י שם."],["329","72","<b>שהי'</b>: אוצ\"ל: שיהי'."],["330","73","<b>ארור מכל</b>: בראשית שם, יד [בדילוג]."]]],[2000470113,"<h3>זאת חנוכת המזבח</h3>\n<b>בס\"ד פ' מקץ</b>\n&lt;1&gt;\nּ <b>(א)</b> זאת חנוכת המזבח<sup data-n=\"331\">1</sup> ביום המשח אותו<sup data-n=\"332\">2</sup>, וכתי' זאת חנוכת המזבח אחרי המשח אותו<sup data-n=\"333\">3</sup>. וצ\"ל שרש ענין החנוכה מהו וענינה אשר עי\"ז נבין ענין קריאת שם חנוכה שכינו חז\"ל על מציאת פך של שמן חתום בחותמו של כה\"ג כידוע ממארז\"ל מאי חנוכה<sup data-n=\"334\">4</sup> כו' בך\"ה בכסליו כו' וטמאו כל השמנים כו' ומצאו פך א' חתום בחותמו של כה\"ג כו' נעשה נס והדליקו ממנו שמונה ימים. ולפ\"ז עיקר הנס",[["331","1","<b>זאת חנוכת המזבח</b>: מכאן ועד סד\"ה וז\"ע שארז\"ל הוא המשך הנודע בשם ”זאת חנוכת — תר\"ם\" ונדפס בשם: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380421\" data-slug=\"likkutei-torah\" data-id=\"4001380421\">לקו\"ת</a> תורת שמואל ש\"ו (ספר התולדות של כ\"ק אדמו\"ר מהר\"ש קה\"ת תש\"ז ע' 51 הערה 6). המשך זה הכולל ט מאמרים (שהם כ\"ג פרקים), נאמר משבת פ' מקץ עד שבת פ' תצוה [פרט לשבת פ' ויחי שאז נאמר הדרוש גור ארי' שנדפס לעיל, ואינו מן ההמשך. וש\"פ בא שלא נרשם דרוש].\nחלק הראשון של ההמשך (עד לקמן פ\"י) מיוסד על מאמר ד\"ה זה שנמצא בבוך 1116 ע' עו [לא נדפס לע\"ע — ויועתק לקמן בריש כל מאמר חלק הנתבאר במאמר ההוא] והנחה אחרת נדפסה בלקו\"ת נשא כח, ב וראה הנסמן במ\"מ לשם.\nחלק השני (פ\"י — פט\"ו) מיוסד על מאמר ד\"ה הנה ענין מחוץ לפרכת שנדפס במאמרי אדה\"ז על פרשיות התורה ח\"א ע' שנא<sup data-n=\"e18\">א</sup>-שנג<sup data-n=\"e19\">ב</sup> והגהות וכו' מהצ\"צ נדפסו באוה\"ת תצוה כרך ח' ע' ג'סב.<sup data-n=\"e20\">ג</sup> והנחה אחרת נדפסה במאמרי אדה\"ז תקס\"ז ע' עג ובשינויים קלים<sup data-n=\"e21\">ד</sup> ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370489\" data-slug=\"torah-or\" data-id=\"3901370489\">תו\"א תצוה קי, א</a>. והגהות וכו' מהצ\"צ נדפסו באוה\"ת תצוה ע' א'תקנו.\nוחלק הג' מפט\"ז ואילך — מיוסד על מאמר ד\"ה וידבר וגו' וארא וגו' שנדפס באוה\"ת וארא כרך ז ע' ב'תקסג. ע' ב'תקסז ואילך. ופכ\"ג הוא לשון מאמר ד\"ה הנה ענין מחוץ לפרכת הנ\"ל בהוספות ושינויים וכו'.\nהנחת<sup data-n=\"e22\">ה</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן (בחלק הנחותיו<sup data-n=\"e23\">ו</sup>).\nלהלן חלק מד\"ה זה מבוך 1116 כנ\"ל המתבאר במאמר זה:\n”זאת חנוכת המזבח ביום המשח אותו וכתי' זאת חנוכת המזבח אחרי המשח אותו להבין זה צריך להקדים ענין הקרבנות שהיו מקריבי' חלב ודם ע\"ג המזבח והי' יורד אש ע\"ג המזבח בדמות ארי' והיינו ארי' דאכי' קרבנין כו' ויובן זה מענין תפלו' שכנגד הקרבנו' שעיקר התפלה לדבקה בו ולאהבה בכל לבבך בשני יצריך וכתי' וירא אלקי' את כל אשר עשה והנה טוב מאד טוב זה מלאך חיים מאד זה כו' ולהבין דהא הוא המ\"ה הוא היצה\"ר ולמה נק' בשם טוב מאוד אך אין היצה\"ר נק' בשם טוב מאד כשהוא יצה\"ר בתקפו אלא כד אתכפיא כו'\"."],["332","2","<b>זאת. . ביום המשח אותו</b>: נשא ז, פד."],["333","3","<b>זאת. . אחרי המשח אותו</b>: נשא שם, פח."],["334","4","<b>מאי חנוכה</b>: ראה שבת כא, ב. לקמן הערה 166.\n\n<b>א</b>  מבוך 1116 הנ\"ל ונמצא שם אחר מאמר דלעיל. וראה לקמן שולי הגליון להערה 183.\n\n<b>ב</b>  והסיום לקמן בפכ\"ג. ראה בפיסקא הבאה בפנים ההערה ד\"ה והחלק הג'\n\n<b>ג</b>  באוה\"ת שם וכן בתו\"א דבסמוך מציין שההגהות הם על נוסח המאמר כפי שנדפס בתו\"א. אמנם ליתר דיוק ההגהות הם להנחה כפי שנדפסה במאמרי אדה\"ז פרשיות הנ\"ל.\n\n<b>ד</b>  מ\"מ לתו\"א שם.\n\n<b>ה</b>  ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\n\n<b>ו</b>  להלן באה רשימת הדרושים ע\"פ ספר התולדות של כ\"ק אדמו\"ר מהר\"ש הנ\"ל ובחצאי ריבוע ניתוספו בריש הדרוש פתיחת הדרושים — שכנראה לא נרשמו ע\"י כ\"ק אדמו\"ר מהר\"ש — כפי שהם מופיעים בההנחות.\nא) זאת חנוכת המזבח — (פרקים א-ב), פ' מקץ.\nב) וביאור כו' משכן יצה\"ר — (פרקים ג-ה), פ' ויגש.\nג) [כמים הפנים] והנה כו' מיכאל עומד ומקריב — (פרקים וא\"ו-ז), פ' שמות.\nד) [תכון תפלתי] והנה כו' אכלתי יערי — (פרקים ח-יו\"ד), פ' וארא.\nה) [ויהי הענן והחשך] והנה השושבין — (פרקים יא-יג), פ' בשלח.\nו) [מזבח אדמה] ויובן עוד כו' זית רענן — (פרקים יד-טז), פ' יתרו.\nז) ועפ\"ז כו' ותהי להם הלבנה — (פרקים יז-יט), פ' משפטים.\nח) [ישקני מנשיקת פיהו] והנה לע\"ל כתיב בבכי יבואו — (פרקים כ-כא), פ' תרומה.\nט) [ואתה תצוה] וז\"ע שארז\"ל על שלא ברכו בתורה — (פרקים כב-כג), פ' תצוה."]]],[2000470114,"הי' מה שהדליק שמונה ימים פך שלא הי' בו אלא כדי להדליק יום אחד לבד, וא\"כ למה כינו לקרותם ימי חנוכה. ובאמת ענין החינוך<sup data-n=\"335\">5</sup> הוא עד\"מ שמחנכין הקטן להרגילו לילך לביה\"ס שזהו בעת התחלתו דוקא, אבל כשמתרגל א\"צ כלל לחינוך, ובהמ\"ק<sup data-n=\"336\">6</sup> היו מדליקין ומקריבין קודם שטמאו, א\"כ אח\"כ כשנצחו כו' רק שלא הי' להם שמן טהור, נעשה נס כו' ומהו קריאת שם חנוכה<sup data-n=\"337\">7</sup>, שלכאורה אינו שייך כלל וכלל לענין מה שנעשה נס והדליקו שמונה ימים כו', גם מה שקורין פ' הנשיאים בחנוכה<sup data-n=\"338\">8</sup> מובן שיש להם שייכות<sup data-n=\"339\">9</sup> זל\"ז אשר לפי הנ\"ל אינו מובן שייכותם זל\"ז, גם צ\"ל מ\"ש ביום המשח, ואח\"כ אמר אחרי המשח אותו כו', ואם זהו ביום אינו אחר המשח, ואם אחר המשח דוקא אינו מוכרח שיהי' ביום המשח אותו, ואיך יתקיימו ב' מקראות אלו כו'. ויובן בהקדם שרש ענין הקרבנות שהיו מקריבים פרים אילים וכבשים ע\"ג המזבח, והעיקר הי' הקרבת חלב ודם, ואש שלמעלה הי' יורד על המזבח בדמות ארי'<sup data-n=\"340\">10</sup> וכמ\"ש בזהר ארי' דאכיל קרבנין<sup data-n=\"341\">11</sup>, וצ\"ל שרש ענין זה. ויובן זה ע\"פ משארז\"ל תפלה כנגד תמידין תקנו<sup data-n=\"342\">12</sup> שעיקר ענין התפלה הוא כדי לדבקה בו ית' בתכלית היחוד, ולא די במה שמדבק נפשו האלקי' שהלא היא חלק אלק' ממעל<sup data-n=\"343\">13</sup> וגם קודם התלבשותה בגוף היתה עומדת לפניו כמ\"ש חי ה' אשר עמדתי לפניו<sup data-n=\"344\">14</sup> ומסתמא היתה עמידתה באהוי\"ר, במכ\"ש ממלאכים דכתי' בהם ויעמידם",[["335","5","<b>ענין החינוך</b>: ראה (בנוסף להערה 1) לקמן פ\"ח. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה זאת חנוכת המזבח כאן בתחילתה. (בחלק ההנחות) הנחה ד\"ה תכון תפלתי על יד הערה 37. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה רני ושמחי פיסקא וענין החינוך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370138\" data-slug=\"torah-or\" data-id=\"3901370138\">תו\"א וישב כט, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381120\" data-slug=\"likkutei-torah\" data-id=\"4001381120\">לקו\"ת ברכה צח, סע\"ב</a> ואילך. סידור שער החנוכה רעז, א. מאמרי אדה\"ז תקס\"ו ע' רמג. אוה\"ת נשא כרך ד ע' א'תסה<sup data-n=\"e24\">ז</sup>. סה\"מ תרל\"ה ח\"ב ע' שלא. המשך וככה תרל\"ז פק\"י. ש\"א טו, ב ובהערה 23."],["336","6","<b>ובהמ\"ק</b>: בבוך 810 ועד\"ז בבוך 451: ובבהמ\"ק."],["337","7","<b>ובהמ\"ק. . שם חנוכה</b>: ראה שבלי הלקט סקע\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101287\" data-slug=\"likkutei-sichot\" data-id=\"1300101287\">לקו\"ש חנוכה כרך י ע' 279</a> בהערה. כ\"ד כסלו כרך כ ע' 449 בהערה 26. שם חנוכה ע' 633 בהערה."],["338","8","<b>שקורין פ' הנשיאים בחנוכה</b>: מגילה ל, סע\"ב (במשנה). רמב\"ם הל' תפלה פי\"ג, הי\"ז. טושו\"ע או\"ח הל' חנוכה רסתרפ\"ד. לקמן ספ\"ט. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה רני ושמחי בתחילתו. (בחלק ההנחות) בהנחה שם על יד הערה 76."],["339","9","<b>שיש להם שייכות</b>: ראה גם בהנסמן לעיל הערה 7."],["340","10","<b>ואש שלמעלה. . ארי'</b>: יומא כא, ב."],["341","11","<b>ארי' דאכיל קרבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שה\"א עט, ב הערה 13. לקמן פ\"ה."],["342","12","<b>תפלה כנגד תמידין תקנו</b>: ראה ברכות כו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380630\" data-slug=\"likkutei-torah\" data-id=\"4001380630\">לקו\"ת פינחס עז, ג</a>."],["343","13","<b>חלק אלק' ממעל</b>: ראה איוב לא, ב. <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540089\" data-slug=\"torat-chaim\" data-id=\"2300540089\">תו\"ח וארא ח\"א נא, ד</a>. וש\"נ."],["344","14","<b>חי ה' אשר עמדתי לפניו</b>: מל\"ב ה, טז. ראה גם לעיל מאמר ד\"ה ואעשך לגוי גדול ובהערה 60.\n\n<b>ז</b>  במהדורת תשנ\"ה נשא בהוספות ע' 116."]]],[2000470115,"לעד לעולם<sup data-n=\"345\">15</sup> שענין עמידתם זה הוא באהוי\"ר ואם המלאכים שהם מחיצוני' הכלים עמידתם באהוי\"ר כ\"ש עמידת הנשמות שהם מפנימיות הכלים<sup data-n=\"346\">16</sup> כנודע, וגם ענין שם עמידה למעלה ז\"ע הביטול<sup data-n=\"347\">17</sup> שהרי לא שייך ענין עמידה גשמי' אלא ע\"ש שעומדים בבחי' הביטול עש\"ז עצמו נק' בשם עמידה כמו העומד לפני המלך שעומד בביטול עצום מפני אימת ופחד המלך כו', א\"כ ענין דביקת נה\"א הלואי שיהי' ביטולה בהיותה מלובשת בגוף עד שיהי' בערך לאופן ביטולה קודם שנתלבשה בגוף אלא שכל ענין ירידתה בגוף הוא בכדי שגם נה\"ב יהי' לה ג\"כ ביטול לאלקות, וזהו דכתי' ואהבת בכל לבבך וארז\"ל בשני יצריך<sup data-n=\"348\">18</sup> שגם היצה\"ר ישוב לאהבת ה', וזהו ע\"י הקדמת פסוק שמע<sup data-n=\"349\">19</sup> ובשכמל\"ו<sup data-n=\"350\">20</sup>, שע\"י ההתבוננות והעמקת הדעת בבחי' ביטול אמיתי דאחד בחי' יחו\"ע וביטול היש דועד בחי' יחו\"ת<sup data-n=\"351\">21</sup> עי\"ז גם היצה\"ר ישוב לאהבת ה' ולדבקה בו ית', וזהו תכלית ירידת הנשמה בגוף כו'.\n<b></b>קיצור. ענין חנוכה, ולמה כינו לקרות חנוכה שהנס הי' בשמן, יובן בהקדם הקרבנות ע\"פ משארז\"ל תפלות כנגד תמידין תקנו, שענין התפלה לדבקה בו ית' שגם הנה\"ב יבא לדבקה בו כו'.\n(ב) <b>והנה</b> יתרון אור מתוך החשך<sup data-n=\"352\">22</sup>, שענין בחי' בירור נה\"ב שגם הוא יבא לדבקה בו ית' &lt;2&gt;\nּ ה\"ז יותר מעולה ומשובח מדביקות נה\"א שדבוקה בו ית' בטבע תולדתו כו', ויובן זה ממ\"ש וירא אלקים את כל אשר עשה והנה טוב מאד<sup data-n=\"353\">23</sup>, וארז\"ל טוב זה מלאך חיים מאד זה מה\"מ<sup data-n=\"354\">24</sup>, ולכאורה למה נק' בשם טוב מאד, אך הענין כנודע שהוא היצה\"ר הוא המסית והוא המקטרג והוא הפועל הגומר כו' שהוא המה\"מ<sup data-n=\"355\">25</sup>, אמנם אין היצה\"ר נק' טוב מאד בהיותו עדיין יצה\"ר בתוקף עוז כמו שהוא",[["345","15","<b>ויעמידם לעד לעולם</b>: תהלים קמח, ו. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו פיסקא וזהו המלך. וש\"נ. (בחלק ההנחות) הנחה ד\"ה כמים הפנים פיסקא אך הנה. וש\"נ. לקמן ח\"ב (בחלק מאמרים) המשך יונתי פ\"ח. פי\"ד. סה\"מ תרכ\"ט ע' רלה. תרל\"ח ע' תעז. תרע\"ח ע' שלו. תרפ\"ו ע' שכב ואילך. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' נט."],["346","16","<b>המלאכים. . מחיצוני'. . מפנימיות הכלים</b>: ראה ע\"ח שער העיבורים שכ\"ח, פ\"א. שער פו\"ח ש\"מ, דרוש י. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370321\" data-slug=\"torah-or\" data-id=\"3901370321\">תו\"א יתרו עב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380822\" data-slug=\"likkutei-torah\" data-id=\"4001380822\">לקו\"ת פ' ראה כו, סע\"ג</a> ואילך. מאמרי אדה\"א ויקרא ח\"א ע' צט. וש\"נ. דברים ח\"ג ע' תשסח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540226\" data-slug=\"torat-chaim\" data-id=\"2300540226\">תו\"ח בשלח ח\"א רמ, ד</a> ואילך."],["347","17","<b>עמידה. . הביטול</b>: ראה סוטה לט, א. לעיל מאמר ד\"ה ואעשך לגוי גדול ובהערה 61."],["348","18","<b>ואהבת. . בשני יצריך</b>: ואתחנן ו, ה [בדילוג] ובספרי שם. ברכות נד, א במשנה. ראה מאמרי אדה\"א בראשית ע' שסג ואילך. שערי אורה ו, א הערה 9. לקמן פט\"ז. מאמר ד\"ה סמוכים לעד ספ\"א. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"ו. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך."],["349","19","<b>שמע</b>: ואתחנן ו, ד."],["350","20","<b>ובשכמל\"ו</b>: פסחים נו, א."],["351","21","<b>דאחד. . דועד בחי' יחו\"ת</b>: זהר בראשית יח, ב. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370514\" data-slug=\"torah-or\" data-id=\"3901370514\">תו\"א ויקהל קטו, ב</a>."],["352","22","<b>יתרון אור מתוך החשך</b>: ע\"פ קהלת ב, יג."],["353","23","<b>וירא. . טוב מאד</b>: בראשית א, לא."],["354","24","<b>טוב. . מאד זה מה\"מ</b>: יל\"ש בראשית שם (רמז טז). זהר בהקדמה יד, א."],["355","25","<b>שהוא היצה\"ר. . המה\"מ</b>: ראה בבא בתרא טז, א."]]],[2000470116,"מסית ומדיח ח\"ו, אלא לאחר הבירור<sup data-n=\"356\">26</sup>, שכשמבררין אותו, והיינו כשמסית ומדיח ואין נשמעין לו אז כד אתכפי' סט\"א<sup data-n=\"357\">27</sup> אסתלק יקרא דקוב\"ה בכולהו עלמין שמצד הנח\"ר שנמשך מצד כפיית הרע עי\"ז נמשך ענג העליון עד שמאיר הארת הענג בכל העולמות. ויש לפרש זה בב' דרכים, הא' שהיצה\"ר בעצם רע הוא וע\"י שמבררים אותו ע\"י שכופים אותו ע\"י העדר מילוי רצונו עד שגם הוא מתרכך להיות ג\"כ כפוף ובטל עד שגם הוא בטל לאלקות כו' ה\"ז יותר טוב מכמו שהי' טוב מצד עצמו, וה\"ז כמו שעושים מרקחת מצנון שהוא בעצם מר הוא וחריף מאד וממתיקים אותו ע\"י הביטול והטיגון בדבש<sup data-n=\"358\">28</sup> שמטגנים אותו ואז נעשה דבר חשוב יותר הרבה מכמו שהי' קודם שטיגנו אותו עד שעולה על שולחן מלכים לכבד בו אותו כו', ועד\"ז יובן ענין היצה\"ר אם הי' מתחלה טוב לא הי' לו מעליותא כ\"כ שהרי על הטוב נא' רק טוב לבד כמארז\"ל טוב זה מלאך טוב<sup data-n=\"359\">*29</sup>, שהרי הרבה טוב נברא כו', כ\"א יצה\"ר לאחר הבירור ה\"ה טוב מאד שהוא עד\"מ הצנון כשמטגנים אותו אז משתנה למעליותא כו'.\n<b>והדרך</b> הב' שגם היצה\"ר בעצם טוב הוא, כי כל עיקר ענין ההסתה שמסית ומדיח אין כוונתו שיצייתו כ\"א שלא יצייתו לו<sup data-n=\"360\">29</sup>, וזה כל עיקר כוונתו כו', וא\"כ ה\"ה טוב יותר מכמו טוב בעצם שהוא היצ\"ט, שהרי היצ\"ט אין לו מעלה כ\"כ במה שמסית אותו לטוב שאינו מראה לו טוב אחר, משא\"כ היצה\"ר שמראה לו טיב העוה\"ז ותענוג שנפל בשה\"כ בדברים האסורים, שלחיך הם מתוקים, או שארי תאוות שהם עריבים על האדם וא\"א לכחד זאת שהרי בעצם הם מפסולת התענוג שנפל בשה\"כ, וזה שמראה אין רצונו שימלא כפי הסתתו אותו למלאות תאוותו, כ\"א שלא יציית לו כלל אחרי אשר הראה לו טוב טעם תענוג שנפל בשה\"כ עכ\"ז יסגף א\"ע ויגדור עצמו לבלי יומשך אחר תענוגי עוה\"ז השפל והגשמי כ\"א לזבוח את יצרו<sup data-n=\"361\">30</sup> ולקרר רתיחות דמו מה שנרתח ע\"י הסתת היצה\"ר ולהיות מעובדי ה' הזובחים את יצרו לפניו, א\"כ טוב זה הוא יותר נעלה מכמו טוב שלא הראה לו טוב אחר כלל, וא\"כ היצה\"ר בעצם גם כמו שהוא קודם הבירור ה\"ה טוב מאד, פי' שבטוב זה יש יתרון על טוב עצמו כו' והיתרון הוא גדול כ\"כ עד שנק' בשם מאד כו', ובזהר איתא משל ע\"ז מהזונה עם בן המלך<sup data-n=\"362\">31</sup>, שהמלך צוה לזונה להסית את בנו שידע אם בנו",[["356","26","<b>היצה\"ר נק' טוב מאד. . לאחר הבירור</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370311\" data-slug=\"torah-or\" data-id=\"3901370311\">תו\"א יתרו סט, ד</a>. סה\"מ תרל\"ח ע' קלה ואילך ובהערה 703. וראה גם מאמרי אדה\"ז תקס\"ד ע' קד ואילך."],["357","27","<b>כד אתכפי' סט\"א</b>: ראה זהר תרומה קכח, ב. יתרו סז, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' ה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770331\" data-slug=\"or-hatorah-hb\" data-id=\"8316770331\">אוה\"ת שלח כרך ו ע' א'תשעב</a>. וש\"נ. שה\"ש כרך ב ע' תרצט."],["358","28","<b>מרקחת מצנון. . בדבש</b>: מובא בכ\"מ ומהם: מאמרי אדה\"ז על פרשיות התורה ח\"א ע' ע. תקס\"ג ח\"ב ע' תשדמ. שעה\"י קכה, סע\"א. אמ\"ב שער התפילין קמ, א. מאמרי אדה\"א בראשית ס\"ע קכג. דברים ח\"ד ע' א'תלב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670368\" data-slug=\"torat-chaim\" data-id=\"2300670368\">תו\"ח בראשית יג, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670380\" data-slug=\"torat-chaim\" data-id=\"2300670380\">מ, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670421\" data-slug=\"torat-chaim\" data-id=\"2300670421\">נח ע, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670531\" data-slug=\"torat-chaim\" data-id=\"2300670531\">וירא קז, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540370\" data-slug=\"torat-chaim\" data-id=\"2300540370\">שמות ח\"א מה, ג</a>. סה\"מ תרל\"ד ע' רנז. תרמ\"ד ע' רסב."],["359","*29","<b>טוב זה מלאך טוב</b>: ראה יל\"ש בראשית א, לא (רמז טז) יצר טוב. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 28."],["360","29","<b>היצה\"ר. . כוונתו. . שלא יצייתו לו</b>: ראה בסמוך הערה 31."],["361","30","<b>לזבוח את יצרו</b>: ראה סנהדרין מג, ב."],["362","31","<b>מהזונה עם בן המלך</b>: ראה זהר תרומה קסג, א. <a class=\"ft-cite\" href=\"#/read/tanya/3401310014\" data-slug=\"tanya\" data-id=\"3401310014\">תניא פ\"ט</a> ופכ\"ט ובמ\"מ הגהות והע\"ק לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680131\" data-slug=\"torat-chaim\" data-id=\"2300680131\">תו\"ח מקץ רטז, ד</a> הערה 67."]]],[2000470117,"נאמן הוא וחזק בדעתו שלא יעבור על הציווי אשר ציונו ואסר לנו ב\"א<sup data-n=\"363\">32</sup>, והנה רצון המלך באין ספק שחזק הוא שרצונו שבנו יסגף א\"ע ויכפה את יצרו ויחזק את לבבו לבלתי סור מן הדרך אשר ציוהו אביו, והזונה הנה היא גם היא למלאות רצון המלך באתה להסית את בנו ולא מתאוות וזדון לבה אשר השיאה לעשות כדבר הזה שהרי &lt;3&gt;\nּ בלתי הציווי לא עשתה כן, רק ע\"פ ציווי וגזירת המלך היא מוכנת לעשות רצון המלך, וא\"כ אם<sup data-n=\"364\">33</sup> היות שמתאמצת בכל אמצי כחה שיציית לה בן המלך ויסיר מדרכי אביו וגזירות אשר ציוהו, עכ\"ז מאחר שלמלאות רצון המלך באתה הנה עצם רצונה האמיתי היא שלא יציית לה, ומה שמסתת אותו בריבוי כ\"כ, הנה בלתי זה הוא אינו עושה באמונה כ\"א ברמי' שיש לבע\"ד לומר אולי היתה מסתת אותו בטוב הי' נשמע לה, ולכן מוכרחת להסית אותו בטוב טעם ודעת להבעיר לבבו עד שיעלה בלבו טינא, ועכ\"ז עצם רצונה האמיתי הוא שלא ישמע לה, ואז כאשר ע\"י יתמלא רצון המלך אשר לא יהי' שום מקום לבע\"ד לחלוק כלל אז תהי' מעלתה שלימה שע\"י ניסו את בן המלך ונמצא שלם ונתעלה בתור המעלה, אשר זהו שבח לה יותר הרבה מן הטוב שהי' מגיע לה לפי שעה אם היתה מסרת לבבו שיסור מדרכי החיים אשר ציוהו אביו, ועד\"ז יובן בענין היצה\"ר שגם הוא טוב הוא בעצם ולא טוב הנגלה כ\"א טוב המכוסה בכיסויים הנראים היפך לעין הרואה, ושכל האדם שהוא מרומה נראה שהיצה\"ר רצונו לדחותו שיודחה ממחיצתו של הקב\"ה, אמנם באמת לא כן הוא שגם היצה\"ר רצונו האמיתי שלא ישמעו לו, ועכ\"ז מוכרח הוא לעשות כל הכיסוים בטצדקאות שונות להסיתו ולפתותו ולדבר על לבו ולהראות את עוצם טיב התענוג שנפל בשבה\"כ איך שמתוק לחיך וכל הרגשי גופו מתהנים מזה הרגש חי והתפעלות עצומה, בכדי שלא יהי' מקום לבע\"ד לחלוק ולאמר שעשה ברמיה, ולכן אינו ניכר כלל עצם חפצו האמיתי מה שהוא באמת לאמיתו והיינו מה שלא ישמע לו כ\"א היפוכו לגמרי מכל וכל, ואז כשיתחזק יוצא מכח אל הפועל בחי' הטוב של היצה\"ר שהוא טוב מאד, היינו טוב הבלתי מוגבל, והמופת לזה במה שלא סר לבבו, הנה עבר בחי' ההגבלה שהרי הרע הוא לעומת הטוב, והגבלת הטוב מן הרע ה\"ז הגבלה היותר מוגבלת, וזה שכבש את יצרו והעביר ההגבלה, וכפה את יצרו הרע שגם הוא יעשה הטוב בעיני אלקים ואדם<sup data-n=\"365\">*34</sup> לבלתי סור מן הדרך אשר ציונו ה' אלקינו הרי עבר את ההגבלה א\"כ הוא בלתי מוגבל לכן נק' בשם טוב מאד כו', ולכן בחי' הענג הנמשך מבחי' אתכפי' זו היא ג\"כ בלתי מוגבלת, ואשר לזאת סליק בחי' יקרי' דקוב\"ה בכולהו עלמין בלתי הגבלה שבעולם זה ובעולם שלמטה הימנה לא הגיע בחי' הענג הזה, כ\"א בכולהו עלמין סליק יקרי' דקוב\"ה כו', ע\"י דאתכפי' סט\"א, והרי מובן שיתרון האור שיאיר בלתי הגבלה זהו מתוך החשך דוקא כו'.\n<b></b>קיצור. שיתרון אור מתוך החשך, טוב מאד זהו מה\"מ שהוא היצה\"ר, ונת' בב' דרכים הא' שהוא בעצם רע וכשמהפכין אותו ה\"ז עד\"מ טיגון הצנון",[["363","32","<b>ב\"א</b>: ביאות אסורות."],["364","33","<b>אם</b>: כ\"ה בכ\"מ — ראה גם סה\"מ תרל\"ח ע' ה. וש\"נ."],["365","*34","<b>הטוב בעיני אלקים ואדם</b>: ע\"פ משלי ג, ד."]]],[2000470118,"בדבש, הב' שגם הוא עצמו טוב מאד הוא, וע\"י האתכפי' יוצא מכאה\"פ להיות נראה טובו, ולעבור ההגבלה וה\"ה מאד בלתי מוגבל כו', ועי\"ז סליק יקרי' דקוב\"ה בכולהו עלמין בלתי הגבלה שרק עד פה תבוא כו'.\n&lt;4&gt;\nּ",[]],[2000470119,"<h3>וביאור כו' משכן יצה\"ר</h3>\n<b>בס\"ד פ' ויגש</b>\n(ג) <b>וביאור</b> הענין יובן דהנה משכן יצה\"ר הוא<sup data-n=\"366\">34</sup> בחלל השמאלי שבלב מקום נה\"ב<sup data-n=\"367\">35</sup> שבאדם, אשר שרש נה\"ב הוא משמרי האופנים<sup data-n=\"368\">36</sup> שבעולם העשיי'<sup data-n=\"369\">37</sup>, ונודע כי האופנים וחיוה\"ק<sup data-n=\"370\">38</sup> הם ברעש גדול ומתנשאים לעומת השרפים, ואומרים ברוך<sup data-n=\"371\">39</sup>, וצ\"ל מה\"ע לעומת השרפים<sup data-n=\"372\">40</sup> הלא לכאו' שניהם הם מלאכים שכלי'",[["366","34","<b>וביאור כו' הנה משכן יצה\"ר</b>: מאמר זה הוא מאמר השני מההמשך וכולל פרקים ג-ה.\nהמאמר מיוסד על מאמר ד\"ה זאת חנוכת המזבח שבבוך 1116 כנ\"ל בריש ההמשך (ומקבילו ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380422\" data-slug=\"likkutei-torah\" data-id=\"4001380422\">לקו\"ת נשא כח, ג</a> ואילך. וראה הנסמן במ\"מ לשם).\nמאמר זה נזכר בסה\"מ תרמ\"ג ע' סה [ושם: כך א' כ\"ק אאמו\"ר זצללה\"ה בש\"ק ויגש ש' תר\"מ, ואני לא שמעתי הדרו'].\nלהלן נעתק חלק המאמר מבוך הנ\"ל שנתבאר בדרוש זה:\n”והענין כי משכן היצה\"ר הוא בנפש הבהמית ושרשה מאופני' דעשי' והאופני' ברעש גדול והרעש הוא מחמת ההתבוננו' שההתהוות מאין ליש הוא מבחי' מלכותך מלכו' כל עולמי' ואין זה אלא זיו כו' שנקרא שמו עליהם כמשל המלך שנק' שמו על המדינה ולכן אומרי' ג\"פ קדוש להיו' המשכה מסכ\"ע עד שיהי' הוי' צבאות אות הוא בצבא דילי' בחי' אות א' ביו\"ד נברא העה\"ב ובה' נברא העה\"ז וע\"ז מרעישי' בקול רעש גדול כי להיות שהוא חידוש גדול ונורא מאד מי יכילנו וכל דבר שלא יכיל הרוח לסבול מחמת גודל עוצם הדבר הנורא שאין כח בשכלו לתפוס כו' מתהוה לו רעש גדול כו' והשרפי' לפי ששרשם ממקום הרעש ההוא לכך אינם מרעישי' כי לכן נק' שמם שרפי' שכבר נשרפו כו' והנה ע\"י הרעש כמים הפנים לפנים כן לב האדם לאדם פי' האדם לאדם כי יש אדם על הכסא דמות כמראה אדם ואדם שמתחת לכסא שאפי' פני ארי' פני שור פני נשר הם בבחי' אדם וכמ\"ש ודמות אדם לארבעתם ודמות פניהם פני אדם וכמים הפנים לפנים כן לב האדם שלמעלה לאדם שלמטה באתעדל\"ת דילי' וזהו ענין הקרבנו' ג\"כ להקריב חלב ודם נפש הבהמי' ע\"ג המזבח ונחית אשא ארי' דאכיל קרבנין אריה מלך החיות להתכלל באש שלמעלה\""],["367","35","<b>יצה\"ר. . בחלל השמאלי שבלב. . נה\"ב</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310014\" data-slug=\"tanya\" data-id=\"3401310014\">תניא רפ\"ט</a> ובמ\"מ הגהות והע\"ק שם."],["368","36","<b>שרש הנה\"ב הוא משמרי האופנים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380083\" data-slug=\"likkutei-torah\" data-id=\"4001380083\">לקו\"ת ויקרא ב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381021\" data-slug=\"likkutei-torah\" data-id=\"4001381021\">האזינו עד, ג</a>."],["369","37","<b>האופנים. . העשיי'</b>: ת\"ז ת\"ו כג, א. ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381032\" data-slug=\"likkutei-torah\" data-id=\"4001381032\">לקו\"ת האזינו עז, ב</a>: וכמ\"ש האריז\"ל — ראה ע\"ח שער פו\"ח דרוש טו. ביאוה\"ז בשלח לט, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תתסג. וש\"נ. קונטרסים ע' תקלה."],["370","38","<b>האופנים וחיוה\"ק הם ברעש גדול</b>: ע\"פ ברכת יוצר."],["371","39","<b>האופנים וחיוה\"ק. . ברוך</b>: יחזקאל ג, יב. ברכת יוצר. ראה חולין צב, רע\"א ובתוד\"ה ברוך. ראה גם סה\"מ תרל\"ד ע' רנד."],["372","40","<b>לעומת השרפים</b>: ראה גם עט\"ר ע' מב ואילך. מאמרי אדה\"א שמות ח\"א ס\"ע רפה ואילך. אוה\"ת אחרי כרך ב ע' תקמ. סה\"מ תרל\"ד ס\"ע רנד ואילך. המשך מים רבים תרל\"ו ע' קטז וע' קיז."]]],[2000470120,"נבדלים<sup data-n=\"373\">41</sup> שעובדים את ה' באימה וביראה ברתת ובזיע<sup data-n=\"374\">42</sup> ולמה יהי' עבודת האופנים לעומת עבודת השרפים, וגם משמע שזה שאומרים ברוך כבוד כו' זהו לעומת בחי' קדוש שאומרים המלאכים<sup data-n=\"375\">43</sup>, אשר גם זה אינו מובן מהו ולמה כו'. והענין הוא דכתי' אני הוי' לא שניתי<sup data-n=\"376\">44</sup> שלא יש שום שינוי בין קודם הבריאה ובין אחר הבריאה, והיינו מפני שכלליות ברה\"ע נעשה מהארה בעלמא ולכן כלליות ההשתלשלו' אינו תופס מקום כלל, ואי לזאת כאשר השרפים משיגים איך שהוא ית' קדוש ומובדל מגדר עולמות, וזהו שאומרים ג\"פ קדוש שז\"ע היותו קדוש ומובדל מג' עולמות בי\"ע<sup data-n=\"377\">45</sup>, או שהוא קדוש מקדוש ע\"ד קדה\"ק לגבי קדש, ג\"פ (והוא מפני שהם נבראים א\"א להם להשיג יותר דבאמת אינו שייך מספר ג\"פ קדוש זל\"ז שהוא בלתי בע\"ג שאינו בערך לגבי הגבול בבחי' בלי גבול ולא במספר ג' כו') ולכן רצונם האמיתי שיעלו ויבואו ויגיעו להדבק בו ית' הקדוש ומובדל מגדר עולמות, ושיצאו מהשגתם והגבלתם להדבק בו שמובדל ומרומם מגדר עולמות, ולכן כתי' שרפים עומדים ממעל לו<sup data-n=\"378\">46</sup>, ולכאורה איך אפשר שהמלאכים יוכלו לעמוד למעלה מבחי' ש' אד' שאמר תחלה, ותי' הבעש\"ט ז\"ל שבכ\"מ שהרצון שם<sup data-n=\"379\">47</sup> ה\"ה כאלו הוא עומד שם (ולכן בלעו\"ז ג\"כ כן הוא, וכמו שהראה פ\"א לתלמידו שור מלובש בכובע של ש\"ק<sup data-n=\"380\">48</sup>, שזה הי' מפני שהאוכל אכל בתאוה עצומה, ונעשה הוא עצמו תמונת שור שהוא הבשר שנתאוה לה, והכובע לא נשתנה כו') וע\"כ כאשר השרפים חפצם ותשוקתם ליכלל וליבטל בבחי' אוא\"ס שקדוש ומובדל לכן ה\"ה כאלו עומדים שם כו', ולפ\"ז צ\"ל מאחר שכאילו עומדים שם למה רוצים עוד יותר ועונים באימה ואומרים ביראה קדוש שהרי כאלו הם שם, וכפשוטו י\"ל שבהסתלק הרצוא והאמירה הרי אינם שם לכן מוכרחים להיות תמיד בבחי' הרצוא.\n<b>ואמנם</b> הנה האופנים אינם משיגים את בחי' אוא\"ס הקדוש ומובדל כ\"א משיגי' שכל התהוות העולמות הוא מהארה בעלמא לבד ושיש בחי' שלמעלה מהשגתם, אבל אינם משיגי' מהו, ולכן אומרים ברוך היינו שיתברך ויומשך להם מה",[["373","41","<b>מלאכים שכלי' נבדלים</b>: ראה לעיל מאמר ד\"ה ואעשך לגוי גדול ובהערה 43."],["374","42","<b>באימה וביראה ברתת ובזיע</b>: ע\"פ ברכות כב, א."],["375","43","<b>קדוש שאומרים המלאכים</b>: ברכת יוצר. ראה חולין צא, ב. ובתוד\"ה ברוך שם צב, רע\"א."],["376","44","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי ובהערה 29."],["377","45","<b>ג\"פ קדוש. . בי\"ע</b>: ראה גם לקו\"ת יוה\"כ סט, ב. ע, ד (באצי'). מאמרי אדה\"ז תקס\"ה ח\"א ע' רנב (נו\"ש). ע' רצב."],["378","46","<b>שרפים עומדים ממעל לו</b>: ישעי' ו, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380215\" data-slug=\"likkutei-torah\" data-id=\"4001380215\">לקו\"ת אמור לב, ב</a>. סה\"מ תרל\"ח ע' טו. וש\"נ."],["379","47","<b>ותי' הבעש\"ט ז\"ל שבכ\"מ שהרצון שם</b>: ראה אוה\"ת נשא<sup data-n=\"e25\">א</sup> — כרך ד — ע' א'תמב<sup data-n=\"e26\">ב</sup>. כתר שם טוב קה\"ת מהדורת תשנ\"ט בהוספות סמ\"ח. וש\"נ. פלח הרמון אמור ע' שיא. וש\"נ. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ס\"ע לה ואילך. ע' סב."],["380","48","<b>הבעש\"ט. . שהראה. . שור מלובש בכובע של ש\"ק</b>: ראה גם סה\"מ תרמ\"ג ע' סה. תרח\"ץ ע' רז. וש\"נ. סה\"ש תש\"א ע' 93. כתר שם טוב קה\"ת מהדורת תשנ\"ט בהוספות סמ\"ח בשולי הגליון.\n\n<b>א</b>  והוא הנחת ר' הלל מש\"פ נשא תר\"י יודפס בע\"ה בספרו פלח הרמון בפ' נשא.\n\n<b>ב</b>  במהדורת תשנ\"ה נשא בהוספות ריש ע' 86."]]],[2000470121,"שאינו מושג להם, וה\"ז לעומת בחי' השרפים שהרי השרפים רוצים לעלות וליכלל וליבטל בו ית' שזהו העדר המשכה, כי המשכה היא מה שכבר מצומצם, והם רצונם בבחי' שקדוש ומובדל מהם מפני שלא נתצמצם להיות נגלה בג' עולמות בי\"ע, והאופנים וחיוה\"ק מאחר שמשיגים שיש דבר שלמעלה מהשגתם ואינם יודעים מהו ולכן א\"א להם להיות הרצון בעצם הדבר כמו השרפים מאחר שאין משיגים מהו כמו השרפים אלא שרצונם וחפצם הוא לטעום מנופת צוף טעם מה שלמעלה מהשגתם, ולכן אומרים ברוך כו' שיתברך ויומשך להם בחי' מה שלמעלה מהשגתם כו'.\n&lt;5&gt;\nּ <b>אך</b> הנה עדיין צ\"ל מהו שאומר באופנים שהם ברעש גדול<sup data-n=\"381\">49</sup>, ולמה השרפים שהם במעלה היותר עליונה לא יהיו ברעש גדול, והאופנים שנמוכים במעלה נגד השרפים עד שהם בעשי' יתעלו במעלת עבודתם להיות בבחי' רעש גדול דוקא, אך הענין הוא דהנה בחי' הרעש של האופנים זהו מפני שהם אינם משיגים ולכן מזה נעשה אצלם בחי' הרעש גדול, ועד\"מ המים כשפוטרי'<sup data-n=\"382\">50</sup> מקום יציאתם ומניחים שביל דק על יציאת המים מתגברים בבחי' רעש גדול להיות הולכי' ברעש, ועד\"ז יובן באופנים שלהיות שכל מה שמושג לשרפי' איך שהוא ית' קדוש ומובדל זה אינו מושג לבחי' האופנים כלל, כ\"א משיגים שיש דבר שלמעלה מהשגתם אבל אינם משיגים מהו ה\"ז כמו שביל דק שהונח על מקום יציאת המים לכן האופנים הם ברעש גדול עד\"מ כמו רעש המים מפני דחיקת ריבוי המים לצאת דרך שביל הדק כו'.\n<b>ויובן</b> ד\"ז ממה שסיפרו לנו הנביאים<sup data-n=\"383\">51</sup>, וממארז\"ל שאמרו על ישעי' שהוא כמו בן כרך שראה את המלך ועל יחזקאל שזהו כמו בן כפר<sup data-n=\"384\">52</sup> שראה את המלך, והענין הוא ששניהם ראו את המרכבה, רק שישעי' סיפר לנו בדרך קצרה תוכן המכוון ובעצם המרכבה לא דיבר הרבה מזה רק התחיל ואראה את אד' יושב<sup data-n=\"385\">53</sup> כו', אבל יחזקאל הרבה לספר את כל אריכות המרכבה בריבוי פרטי', והיינו כי זהו ענין ההפרש בין בן כרך לבן כפר כשרואים את המלך ושניהם מתפעלי' אבל אין גרם התפעלותם שוה, שהרי הבן כרך עם היות שרואה את המון הצבא הבאים לכבוד המלך עכ\"ז אינו מתפעל מזה כ\"כ, והוא מפני כי מורגל הוא לראותם תמיד להיותו דר תמיד בכרך, כ\"א התפעלותו הוא מהנהגת המלך את הצבא ושכל העמוק שיש בתכסיסי המלחמה אשר המלך עורך את הצבא שיבינו את רמיזותיו וסימניו כו', אבל הכפרי איננו מבין כלל את עצם חכמת המלך בהנהגתו את הצבא כ\"א מתפעל מריבוי הצבא וקול צהלת סוסים אשר צבא המלך רוכבי' עליהם וכדומה, ולהיות כי",[["381","49","<b>באופנים שהם ברעש גדול</b>: ראה גם (בנוסף להערה 34) עט\"ר ע' מא וע' מב ואילך. מאמרי אדה\"א שמות ח\"א ע' רפו ואילך. סה\"מ תרכ\"ט ע' רלז ואילך."],["382","50","<b>כשפוטרי'</b>: בהמשך הנדפס: כשסותמי'."],["383","51","<b>שסיפרו לנו הנביאים</b>: ישעי' רפ\"ו. יחזקאל פ\"א."],["384","52","<b>ישעי'. . יחזקאל. . בן כפר</b>: ראה חגיגה יג, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381116\" data-slug=\"likkutei-torah\" data-id=\"4001381116\">לקו\"ת ברכה צז, ב</a>. סידור שער ר\"ח ריא, ב. מאמרי אדה\"א שמות ח\"א ע' רפו. סה\"מ תרכ\"ט ע' רלז."],["385","53","<b>ואראה את אד' יושב</b>: ישעי' ו, א."]]],[2000470122,"התפעלות איננו ע\"פ השגה בבחי' השכלה פנימיות לכן הוא ברעש שראה גודל עוצם מעלת המלך שבא בחיל כבד וקול צהלת הסוסים ומרבה לדבר בפרטיות שראה כו' והכל בבחי' החיצוני', ועד\"ז יובן בענין ישעי' ויחזקאל להיות כי ישעי' ראה את המרכבה בבחי' בריאה<sup data-n=\"386\">54</sup> לכן ראה איך שהשרפי' עומדים בבחי' ביטול עצום מאד נעלה לעלות וליכלל וליבטל באוא\"ס עצומ\"ה, לכן לא דיבר כלל בבחי' החיצוני' כ\"א בבחי' הפנימיות איך שביטולם הוא לאוא\"ס הקדוש ומובדל מגדר עולמות כו', אבל יחזקאל הרבה לספר אריכות הענין ודמות המלאכי' ומראיתם כו' וה\"ז כמו הרעש גדול דאופנים וחיוה\"ק, וכן יחזקאל ראה ביצי'<sup data-n=\"387\">55</sup> ששם הוא עמידת חיות הקדש<sup data-n=\"388\">56</sup> כו'.\n<b></b>קיצור. שהנה\"ב שרשו משמרי האופני', והאופני' ברעש גדול לעומת השרפי' שהשרפים חפצם לעלות וליבטל והאופנים רוצים להשיג כו', והרעש גדול זהו מחמת העדר ההשגה וע\"ד ההפרש בין בן כרך שראה את המלך לבן כפר שראה את המלך כו'.\n&lt;6&gt;\nּ (ד) ועוי\"ל ענין בחי' הרעש גדול דאופנים, הוא ע\"פ מה שמתבוננים שהתהוות יש מאין הוא מבחי' מלכותך מכ\"ע<sup data-n=\"389\">57</sup>, שכל ענין בחי' המל' הוא בחי' זיו כבוד הדר מלכותו, מלך שמו נקרא עליהם, שכל ענין השם הוא בכדי שזולתו יקראהו בשמו<sup data-n=\"390\">58</sup> אבל לעצמו א\"צ לו כלל, וגם שמו אינו כמו אפי' עור האדם או שערותיו, שעור ושער האדם ה\"ה נוגעים יותר לגוף האדם שהרי כשדוקרים או חותכים בעור אם כי איננו מכאיב כמו בבשר האדם עכ\"ז מרגיש הוא שחותכים בעור וכשמושכי' בשערותיו יכאיב לו ונמשך גוף האדם גם בלתי רצון האדם, משא\"כ בשמו אשר יקראוהו בו כשילעיגו משמו אינו נוגע לו כלל, ומה שמתפעל מזה ומתקצף על אדם הלועג ממנו זהו מה שנוגע למדה שבלב, אבל מה שנוגע לעצם שמו אינו מתפעל כלל, ומה שנפנה לקוראיו זהו על צד ההרגל, וא\"כ ענין השם ה\"ז בחי' הארה בעלמא, וגם אפי' לפמשנ\"ת במ\"א בענין ויקרא האדם שמות<sup data-n=\"391\">59</sup> שאם נאמר שהשם הוא רק הסכם לבד א\"כ מהו שא' הקב\"ה על אדה\"ר חכמתו גדולה משלכם<sup data-n=\"392\">60</sup>",[["386","54","<b>ישעי'. . בריאה</b>: ראה לקו\"ת להאריז\"ל ישעי' פ\"ו. לקוטי הש\"ס להנ\"ל יבמות מט, ב ד\"ה מנשה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540375\" data-slug=\"torat-chaim\" data-id=\"2300540375\">תו\"ח בא ח\"א קיד, סע\"ג</a>. וש\"נ. סה\"מ תרמ\"ז ע' קלו. קמב. סה\"מ ליקוט ח\"ג (מאמר ד\"ה בגמ' יבמות. . ע\"פ ואראה תרמ\"ט) ע' ו."],["387","55","<b>יחזקאל ראה ביצי'</b>: ראה ע\"ח שער ק\"נ שמ\"ט, פ\"ב. מאמרי אדה\"א נ\"ך ע' קמא. וש\"נ. תו\"ח שם ובהערה 194. סה\"מ תרמ\"ז שם. ולהעיר מויקהל משה בתחלתו<sup data-n=\"e27\">ג</sup>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370347\" data-slug=\"torah-or\" data-id=\"3901370347\">תו\"א משפטים עח, ב</a>: בריאה."],["388","56","<b>ביצי'. . חיות הקדש</b>: ראה ע\"ח שער פנו\"ח ש\"מ, דרוש יג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550702\" data-slug=\"torat-chaim\" data-id=\"2300550702\">תו\"ח תצוה ח\"ב שמ, ג</a>. וש\"נ."],["389","57","<b>מלכותך מכ\"ע</b>: תהלים קמה, יג."],["390","58","<b>השם. . שזולתו יקראהו בשמו</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רסח. וש\"נ (ובריש המאמר שם). קונטרסים ס\"ע תקס ואילך. סה\"מ תרכ\"ט ע' קלו. המשך מים רבים תרל\"ו ע' סה."],["391","59","<b>ויקרא האדם שמות</b>: בראשית ב, כ. ראה סה\"מ תרכ\"ט שם ואילך. וש\"נ. תרל\"ח ע' קסב. וש\"נ."],["392","60","<b>חכמתו גדולה משלכם</b>: ב\"ר פי\"ז, ד [ושם: מרובה — אבל כ\"ה גם בהמשך מים רבים שם ע' כט. תרל\"ז פ\"ו. תרל\"ח שם. ועוד].\n\n<b>ג</b>  זאלקווא תקל\"ה ו, א – ראה אודות הספר באוה\"ת בלק ע' תתקקפה."]]],[2000470123,"אלא שהשם הוא אותיות המחיים את הדבר ההוא א\"כ השם אינו זיו אלא מקור חיותו<sup data-n=\"393\">61</sup>, אמנם הנה זהו ברוחניות, והתהוות הגשמיות מן הרוחניות<sup data-n=\"394\">62</sup> אין לך בריאה יש מאין גדול מזה, א\"כ מוכרח לומר שדבר המהוה והמחי' מסתתר מדבר המתהוה ואינו מתגלה אלא הארתו לבד שז\"ע בחי' זיו בלבד, רק שלפ\"ז זיו דשם הוא במעלה יותר עליונה מעצם האדם, וכן נא' בבחי' המ' שגבוה מאד נעלה, שבאמת כן הוא שהרי בחי' המל' שרשה בכתר<sup data-n=\"395\">63</sup>, ובמק\"מ איתא ששרש המל' הוא מרדל\"א<sup data-n=\"396\">64</sup>, ובת\"ז כ\"ע דאיהו כתר מל'<sup data-n=\"397\">65</sup>, אבל מ\"מ הוא רק בחי' זיו בלבד, והארת זיו זה הוא המחי' כלליות בי\"ע, וזהו שבבשכמל\"ו נא' ג' לשונות שם כבוד מלכותו, וכולם לשון זיו שהרי מלך שמו נק' עליהם, וכבוד הוא בחי' לבוש כמארז\"ל ר\"י קארי למאנא מכבדותא<sup data-n=\"398\">67</sup>, שזהו בחי' לבוש מל', וא\"כ למה כפל לאמר ג\"פ ענין א', אלא שזהו נגד ג' עולמות בי\"ע<sup data-n=\"399\">66</sup> שיש הבדל בין עולם לעולם, והיינו שבחי' המל' מתלבש בלבוש מל' ושם מבחי' כבוד זה מחי' ומהוה בחי' העשיה, וזהו שם צבאות שא' חנה<sup data-n=\"400\">68</sup> שהוא השם שבבי\"ע כמ\"ש בת\"א<sup data-n=\"401\">69</sup> ס\"פ<sup data-n=\"402\">70</sup> בא, והיינו כי אות הוא בצבא שלו<sup data-n=\"403\">71</sup>, אות לשון סימן, וגם לשון אות ביו\"ד נברא העוה\"ב<sup data-n=\"404\">72</sup> ובה' נברא העוה\"ז, וע\"ז הם מרעישים בבחי' הרעש גדול כי להיות חידוש גדול ונורא מאד מי יכילנו, וכל דבר אשר לא יכול הרוח לסבול מחמת גודל עוצם מעלת חידוש דבר נורא כזה עד שאין השכל תופסו מתהוה אצלו בחי' רעש גדול וה\"ז קרוב לפי מה שנת' לעיל ס\"ג שזהו מפני העדר השגתם רק שלשם נת' שזהו מפני שמשיגי' שיש בחי' שלמעלה מהשגתם אבל",[["393","61","<b>השם. . מקור חיותו</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380254\" data-slug=\"likkutei-torah\" data-id=\"4001380254\">לקו\"ת בהר מא, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550264\" data-slug=\"torat-chaim\" data-id=\"2300550264\">תו\"ח יתרו ח\"ב רנב, ד</a>. סה\"מ תרל\"ב ח\"א ע' קלא. וש\"נ. תרל\"ח ע' סב. וש\"נ."],["394","62","<b>והתהוות הגשמיות מן הרוחניות</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380799\" data-slug=\"likkutei-torah\" data-id=\"4001380799\">לקו\"ת פ' ראה כ, ד</a> בשם חכמי המחקר. ראה עקרים מ\"א, פכ\"ג. מ\"ד, פ\"ג<sup data-n=\"e28\">ד</sup>. ראה גם תו\"א מג\"א צ, ב. מאמרי אדה\"א דברים ח\"ד ע' א'רפו ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770181\" data-slug=\"or-hatorah-hb\" data-id=\"8316770181\">אוה\"ת שה\"ש כרך ב ע' תקמט</a>. סה\"מ תרכ\"ז ע' שפז וע' תיח. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ויאמר כו' לך לך על יד הערה 37. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה שם על יד הערה 53. קונט' בר מצוה תרנ\"ג ע' מט. וש\"נ."],["395","63","<b>המל' שרשה בכתר</b>: לקו\"ת חוקת נח, א."],["396","64","<b>ובמק\"מ. . ששרש המל' הוא מרדל\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080400\" data-slug=\"or-hatorah-hb\" data-id=\"8160080400\">אוה\"ת</a> יחזקאל<sup data-n=\"e29\">ה</sup> כרך א ע' ת שמציין: כמ\"ש במק\"מ ר\"פ צו דכ\"ו<sup data-n=\"e30\">ו</sup> ע\"פ לא ידעתי נפשי<sup data-n=\"e31\">ז</sup> ששרש המל' מרדל\"א. לקמן המשך מצה זו פ\"ס ובהערה 1704."],["397","65","<b>כ\"ע דאיהו כתר מל'</b>: ת\"ז בהקדמה יז, א."],["398","67","<b>ר\"י קארי למאנא מכבדותא</b>: ראה שבת קיג, א."],["399","66","<b>שבבשכמל\"ו. . בי\"ע</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרמ. ע' תשטו. תקס\"ו ע' טז. סהמ\"צ להצ\"צ ע' קכב. המשך מים רבים תרל\"ו ע' סה."],["400","68","<b>שם צבאות שא' חנה</b>: שמואל-א א, יא. ברכות לא, ב."],["401","69","<b>צבאות. . שבבי\"ע כמ\"ש בת\"א</b>: בא ס, ב. ראה גם אוה\"ת בא ע' שכח. סה\"מ מלוקט א' ע' שפ ואילך."],["402","70","<b>ס\"פ</b>: כ\"ה גם בהמשך הנדפס."],["403","71","<b>אות הוא בצבא שלו</b>: ראה חגיגה טז, רע\"א (לגי' הע\"י. רש\"י סנהדרין צב, א ד\"ה שתי אותיות). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540396\" data-slug=\"torat-chaim\" data-id=\"2300540396\">תו\"ח בא ח\"א קיד, ד</a>. וש\"נ."],["404","72","<b>ביו\"ד נברא העוה\"ב</b>: ראה מנחות כט, ב.\n\n<b>ד</b>  צויין בהמשך מים רבים תרל\"ו פקנ\"ז ובהערה.\n\n<b>ה</b>  נדפס גם בספר החקירה ע' עט.\n\n<b>ו</b>  ע\"ב.\n\n<b>ז</b>  שה\"ש ו, יב."]]],[2000470124,"מה שמהוה אותם זה משיגים, וכאן יתבאר שעם היות שמשיגים את הכח האלקי המהוה אותם מ\"מ מפני החידוש העצום &lt;7&gt;\nּ והנורא מזה נעשה אצלם הרעש גדול כו'.\n<b>ואמנם</b> השרפים לפי שהם עצמם הם ממקום שנמשך החידוש שמזה מתהוה אצל האופני' וחיוה\"ק בחי' הרעש לכן אינם בבחי' רעש כלל, והיינו כי ממל' דבריאה מתהוה היצירה ולכן החיות דיצי' הם בבחי' רעש על החידוש העצום והנורא כנ\"ל וכ\"ש האופנים דעשיי', אבל השרפי' שבבריאה אצלם אין זה חידוש כלל כ\"א עומדים בבחי' הביטול עצום, ושמם מוכיח עליהם שנק' בשם שרפי' ע\"ש שכבר נשרפו<sup data-n=\"405\">73</sup> בבחי' הרשפי אש כמ\"ש רשפי' רשפי אש<sup data-n=\"406\">74</sup> שלהבת י\"ה, לכן הם בחשאי בבחי' הביטול, כמו גחלת שכבר נשרפה כו' שאינה בבחי' הרעש כמו עץ הדולק שנשמע קולו ע\"י שמתעכל באש, והיינו להיות כי הגחלת נשתנה מעץ להיות אש עצמו כו' ולכן הניח גחלת ברה\"ר והזיק<sup data-n=\"407\">75</sup> ה\"ז כמו להב האש כו', ולכן השרפי' שכבר נשרפו אינם מרעישים כלל.\n<b></b>קיצור. שעוי\"ל שרעש האופנים הוא מהדבר נפלא שמהארה בעלמא נתהוו העולמות, והשרפים להיות<sup data-n=\"408\">76</sup> בבריאה שהאין היינו בחי' מל' דבריאה מהוה יצי' לכן אינם מרעישים.\n(ה) <b>והנה</b> כתי' כמים הפנים לפנים<sup data-n=\"409\">77</sup> כן לב האדם אל האדם, פי' לב האדם אל האדם ענין ב' בחי' אדם אלו דכתי' ועל דמות הכסא<sup data-n=\"410\">78</sup> דמות כמראה אדם, שבחי' כמראה אדם הוא ממעל לכסא, ויש בחי' אדם שמתחת לכסא והוא מ\"ש ודמות פניהם פני אדם<sup data-n=\"411\">79</sup>, שגם בחי' פני ארי' ופני שור ופני נשר ג\"כ דמות פניהם פני אדם הוא, וכדכתי' וזה מראיהן<sup data-n=\"412\">80</sup> דמות אדם להנה, וכתי' ודמות פניהם פני אדם, וכמים הפנים לפנים כן לב האדם שממעל לכסא לאדם שבחיות ע\"י האתעדל\"ת שלו בבחי' רצו\"ש, וכמ\"ש והחיות רצו\"ש<sup data-n=\"413\">81</sup> כו'. וע\"פ הקדמה זו יובן ענין הקרבנות ג\"כ להקריב חלב ודם הבהמה ע\"ג המזבח וע\"י העלאה זו נחית אשא בדמות ארי' דאכיל קרבנין, פי' וענין האכילה הוא כמו האדם הגשמי כשאוכל איזה מאכל מתעכל המאכל ונעשה ממנו בשר האדם שזהו עילוי של המאכל במה שמתעלה ממה שהי' תחלה צומח או בעל חי להתעלות להיות בשר האדם שהוא מדבר, עד\"ז יובן ענין דאכיל קרבנין הוא מה שמתעלה בשר הבהמה וחלבה הנשרפת באש שלמטה להיות עולה ונכללת באש שלמעלה שז\"ע אכיל קרבנין שזהו כמו המאכל שנכלל",[["405","73","<b>שרפים ע\"ש שכבר נשרפו</b>: ראה סה\"מ תרל\"ח ע' טז. וש\"נ."],["406","74","<b>רשפי' רשפי אש</b>: שה\"ש ח, ו."],["407","75","<b>הניח גחלת ברה\"ר והזיק</b>: ירושלמי ב\"ק פ\"א, ה\"א."],["408","76","<b>להיות</b>: כ\"ה גם בהמשך הנדפס."],["409","77","<b>כמים הפנים לפנים</b>: משלי כז, יט (ושם: לאדם)."],["410","78","<b>ועל דמות הכסא</b>: יחזקאל א, כו."],["411","79","<b>ודמות פניהם פני אדם</b>: יחזקאל שם, י. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380424\" data-slug=\"likkutei-torah\" data-id=\"4001380424\">לקו\"ת נשא כאן כט, א</a>."],["412","80","<b>וזה מראיהן</b>: שם שם, ה."],["413","81","<b>והחיות רצו\"ש</b>: יחזקאל א, יד."]]],[2000470125,"להיות נק' בשם אדם, שהרי קודם שהאדם אוכל אינו נק' בשם מאכל אדם שמובן ענינו שאיננו אדם עדיין כ\"א שהוכן למאכל אדם שבזה יש לו יתרון שראוי והוכן למאכל אדם ולא למאכל בהמה אבל איננו אדם, וכשאוכל אותו האדם אז מתעלה להיות אדם עצמו שהרי הוא מתעכל להיות דם שבו חיות האדם כמ\"ש כי הדם הוא הנפש<sup data-n=\"414\">82</sup>, וא\"א להבין ולהבדיל בין המאכל וגוף וחיות האדם שהי' קודם שאכל מאכל זה כו', ועד\"ז יובן ענין ארי' דאכיל &lt;8&gt;\nּ קרבנין שנק' בשם אכילה ע\"ש שבחי' אש שלמטה מתעלה ונכללת באש שלמעלה עד שא\"א להבדיל ולחלק ביניהם מפני שנכללת לגמרי עד שמתאחדים להיות לאחדים בחי' א' ממש, והנה הגם כי אש יורד מלמעלה עכ\"ז מצוה להביא מן ההדיוט<sup data-n=\"415\">83</sup>, והיינו כי כדי שיהי' לב האדם אל האדם זהו ע\"י כמים הפנים לפנים שע\"י ההעלאה בבחי' אתעדל\"ת עי\"ז נמשך אתעדל\"ע<sup data-n=\"416\">84</sup> להיות המשכת בחי' אדם העליון לבחי' אדם שבמרכבה שלמטה מהכסא כו'.\n<b></b>קיצור. כמים הפל\"פ כן לב האדם אל האדם, ב' בחי' אדם, וההמשכה היא לפ\"ע האתעדל\"ת ועפ\"ז יובן ענין הקרבנות שמתעלים ליכלל באש שלמעלה ע\"ד כמו מאכל דצומח וחי להיות מדבר, ועד\"ז יובן ענין ארי' דאכיל קרבנין.",[["414","82","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["415","83","<b>אש יורד. . להביא מן ההדיוט</b>: ראה תו\"כ ויקרא א, ז. ערובין סג, א. מאמרי אדה\"א דברים ח\"ד ע' א'תפה. וש\"נ."],["416","84","<b>אתעדל\"ת. . אתעדל\"ע</b>: ראה זהר לך פח, א. מאמר ד\"ה לרוקע נדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' קצד [ובמקביליו ובהנסמן במ\"מ לשם]. מאמרי אדה\"א דברים ח\"א ע' קצח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a> ובהערה 189."]]],[2000470126,"<h3>[כמים הפנים] והנה כו' מיכאל עומד ומקריב</h3>\n<b>פ' שמות</b>\n(וא\"ו) <b>והנה</b><sup data-n=\"417\">85</sup> כמו שהוא בענין הקרבת הבהמה ע\"ג המזבח, כן יובן בחי' זו בנש\"י בבחי' עבודת הנשמות בעבודה שבלב זו תפלה<sup data-n=\"418\">86</sup>, דהנה ארז\"ל מיכאל עומד ומקריב נש\"י<sup data-n=\"419\">87</sup> ע\"ג המזבח, שצ\"ל מה\"ע הקרבה זו שלכאו' אינו דומה",[["417","85","<b>והנה כו' מיכאל עומד ומקריב</b>: מאמר זה הוא מאמר הג' מההמשך וכולל פרקים ו-ז.\nדרוש זה מיוסד על מאמר ד\"ה זאת חנוכת המזבח שבבוך 1116 כנ\"ל בריש ההמשך (ומקבילו בלקו\"ת נשא וראה הנסמן במ\"מ לשם).\nלקמן בחלק ההנחות נדפסה הנחה ממאמר זה ושם הפתיחה: כמים הפנים.\nלהלן נעתק חלק המאמר מבוך הנ\"ל שנתבאר בדרוש זה:\n”וכן הענין בנשמו' שמיכאל כה\"ג מקריב ע\"ג המזבח הנשמו' הן בחי' הנבראי' מאין ליש וע\"י מיכאל נקרבי' למעלה ליכלל באצי' דא. . והנה הקרבת הקרבנו' ע\"ג המזבח נק' בשם אכילה כמארז\"ל בשתי אכילות הכתוב מדבר א' אכילת אדם וא' אכילת המזבח לפי שהיא בחי' פנימי'\"."],["418","86","<b>בעבודה שבלב זו תפלה</b>: ראה ספרי (ופרש\"י) עקב יא, יג. תענית ב, סע\"א. רמב\"ם ריש הלכות תפלה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450608\" data-slug=\"or-hatorah-hb\" data-id=\"8316450608\">אוה\"ת עקב ע' תרח</a>."],["419","87","<b>מיכאל עומד ומקריב נש\"י</b>: ראה חגיגה יב, ב כגי' הע\"י. תוד\"ה ומיכאל מנחות קי, א. מאמרי אדה\"א ויקרא ח\"א ע' א. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540486\" data-slug=\"torat-chaim\" data-id=\"2300540486\">תו\"ח שמות ח\"א ה, א</a>. וש\"נ. לקמן (בחלק ההנחות) בהנחה כאן."]]],[2000470127,"להקרבת הבהמה ע\"ג המזבח שהבהמה היא גשמיות ושרשה מבחי' פני שור<sup data-n=\"420\">88</sup>, ועולה ונכללת באש שלמעלה להכלל בבחי' אדם<sup data-n=\"421\">89</sup>, אבל הנשמה היא חלק אלקה ממעל וקודם התלבשותה בגוף היתה עומדת לפניו באהוי\"ר כנ\"ל<sup data-n=\"422\">90</sup>, א\"כ מהו ענין הקירוב מה שמיכאל כה\"ג<sup data-n=\"423\">91</sup> מקריב נש\"י ע\"ג המזבח, אך הענין הוא דהנה א\"א נשמה שנתת בי טהורה היא, אתה בראת<sup data-n=\"424\">92</sup> כו', ולכאו' צ\"ל מהו שאו' טהורה היא קודם אתה בראת, שענין שם בריאה הוא דבר חדש מה שלא הי' לעולמים כלל, וכמו הבריאה כלליות, שהונח שם זה ע\"ש ההתחדשות שנתחדש מאין ליש, וכמו ואם בריאה יברא<sup data-n=\"425\">93</sup> שפי' שאם נברא מכבר פה לארץ תפתח פיה ואם לא נברא יברא ה' מחדש, וזהו ההפרש בין בריאה יש מאין להשתלשלות עו\"ע<sup data-n=\"426\">94</sup> כו' כמ\"ש במ\"א באורך, וא\"כ מהו קריאת שם טהורה שקודם לבראת, אך הענין יובן ע\"פ מה דאיתא שנש\"י חקוקים תחת כסה\"כ<sup data-n=\"427\">95</sup>, וכן אמרו אוצר של נשמות<sup data-n=\"428\">96</sup>, והיינו כי מקור דנש\"י הוא באצי' העליון, ואז טהורה היא פי' טהור הוא שלא יש שום דבר נוסף על עצמות אצילותה כמו הדבר טהור שפירושה הוא<sup data-n=\"429\">97</sup> שמנוקה הוא מכל דבר לכלוך, כך ענין טהורה פי' שלילה מכ\"ד כו', אלא שבכדי שתתלבש הנשמה בגוף ונה\"ב גשמי ירדה הנשמה בבחי' בריאה יש מאין וזהו אתה בראת, ואח\"כ נוצרה בבחי' היצי' ואח\"כ נעשית בבחי' העשי' עד שאח\"כ ביכולתה להחיות גוף גשמי ולהתלבש בנה\"ב גשמי כו', וגם הנשמה בהיותה בבחי' האצי' ג\"כ מוכרח לומר שהוא קצת נפרד, שהרי מזה עצמו שא' חי ה' אשר עמדתי לפניו מובן ענין היותה נפרד קצת שאל\"כ לא יתכן כלל ענין האהוי\"ר שענין האהבה או היראה לא יתכן כ\"א על הזולת ולא על עצמו, ואם היו<sup data-n=\"430\">98</sup> בתכלית היחוד &lt;9&gt;\nּ באלקות לא הי' לו כלל ענין העמידה באהוי\"ר, והגם שי\"ל שזה קאי בהיות הנשמה בגעה\"ע, מ\"מ הלא גם נשמות דאצי' מרוחקים מן הקו כמ\"ש באגה\"ק סי' ך' ד\"ה איהו וחיוהי, ולזאת יתכן לומר בהם ענין עמידתן",[["420","88","<b>שהבהמה. . פני שור</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ח. מאמרי אדה\"א שמות ח\"א ע' כח. וש\"נ. סה\"מ תרל\"ח ע' יח. וש\"נ."],["421","89","<b>שהבהמה. . להכלל בבחי' אדם</b>: ראה לקמן המשך מצה זו פמ\"ב על יד הערה 1309. סה\"מ תרל\"ח ע' לה. פלח הרמון ויקרא ע' ב וע' יא."],["422","90","<b>כנ\"ל</b>: פ\"א."],["423","91","<b>שמיכאל כה\"ג</b>: ראה זהר ס\"ת לך פ, סע\"א ואילך. הנסמן במאמרי אדה\"א בראשית ע' נו."],["424","92","<b>נשמה. . טהורה. . בראת</b>: ברכת אלקי נשמה (מברכות ס, ב). ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי רפ\"ט (ובשני ההנחות שם). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381196\" data-slug=\"likkutei-torah\" data-id=\"4001381196\">לקו\"ת שה\"ש טז, ד</a>. סה\"מ תרל\"ג ח\"ב ס\"ע שכז ואילך. ע' שעב. תרע\"ח ע' שלז."],["425","93","<b>ואם בריאה יברא</b>: קרח טז, ל. ראה רש\"י שם."],["426","94","<b>ההפרש בין בריאה. . עו\"ע</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380255\" data-slug=\"likkutei-torah\" data-id=\"4001380255\">לקו\"ת בהר מא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381289\" data-slug=\"likkutei-torah\" data-id=\"4001381289\">ואתחנן י, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">שה\"ש מ, ב</a> ואילך. המשך מים רבים תרל\"ו ע' רכה. תו\"א משפטים עה, ד. תרע\"ח ע' פו ואילך. ע' קכ."],["427","95","<b>שנש\"י חקוקים תחת כסה\"כ</b>: ראה ת\"ז תכ\"ב סה, ב [ובהנסמן בניצוצי זהר שם]. סו, א. רע\"מ צו כט, ריש ע\"ב: גזורות מתחת כסא הכבוד. מאמרי אדה\"א דברים ח\"ב ע' תצט [ושם: ובל' הגמרא — ראה בהנסמן שם]. סה\"מ תרל\"ח ע' עז."],["428","96","<b>אוצר של נשמות</b>: ראה ע\"ז ה, א וברש\"י ותוס' שם. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשעה. מאמרי אדה\"א דברים ח\"ב ע' תקנג בהערה."],["429","97","<b>הוא</b>: ניתוסף ע\"פ המשך זה הנדפס."],["430","98","<b>היו</b>: כ\"ה גם בהמשך הנדפס."]]],[2000470128,"באהוי\"ר, ולכן שייך ענין ההקרבה שמיכאל כה\"ג מקריבן להיות נאחדים ממש בתכלית היחוד, בבחי' איהו וחיוהי כו'.\n<b>והענין</b> הוא, דהנה איהו וחיוהי חד איהו וגרמוהי חד בהון<sup data-n=\"431\">99</sup>, ולכאו' צ\"ל מאחר שחיוהי וגרמוהי שניהם הם חד ולמה מחלקן לב' דברים שאיהו עם בחי' חיוהי חד וגם איהו וגרמוהי חד, הלא נושא שם חד בלה\"ק הוא אחד ומאחר שאחד הם אין מקום כלל לחלוק ביניהם, ואם מצד שהם שני ענינים מחולקי' שחיוהי הוא בחי' האורות וגרמוהי הם הכלים<sup data-n=\"432\">100</sup> מ\"מ הי' לו לומר איהו וחיוהי וגרמוהי חד בהון, אלא מוכרח לומר שעם היות שגם בחי' גרמוהי חד עם בחי' איהו כמו חיוהי מ\"מ אין אחדותם שוה, והיינו מה שבחי' איהו מתייחד עם גרמוהי לברוא בהם וע\"י בחי' יש מאין<sup data-n=\"433\">101</sup>, אבל מ\"מ יחוד בחי' איהו עם חיוהי הוא יחוד יותר נפלא באין ערוך שהרי גרמוהי הוא רק בשביל התהוות הנבראי' שאינו בערך לגבי בחי' יחוד האצילות שהוא אינון ואינון הוא<sup data-n=\"434\">102</sup>, והגם שקאי גם הכלים<sup data-n=\"435\">103</sup> דאצי' מ\"מ בחי' הכלים כמו שהם בבחי' האצי' ולא לצורך התהוות בי\"ע הם במדרגה יותר נעלה, ולא מחמת בחי' זו נחלקו לומר ב\"פ חד כו'.\n<b>והנה</b> בחי' טהורה היא שא' בנשמה זהו מפני ששרשה מבחי' פנימיות הכלים דאצי' שכ\"ז הוא בכלל גרמוהי, אבל ענין ההקרבה שמיכאל כה\"ג מקריבן ע\"ג המזבח שלמעלה זהו שיתאחדו לדבקה בו ית' בבחי' איהו וחיוהי, שזהו באופן אחר ממש, והוא בחי' לדבקה בו, לאשתאבא בגופא דמלכא<sup data-n=\"436\">104</sup> כו', שזהו עלייה גדולה מאד, ובכלל נחשב בחי' עלי' זו מבחי' שרש ומקור הנבראי' להכלל בבחי'",[["431","99","<b>איהו וחיוהי. . וגרמוהי חד בהון</b>: ראה ת\"ז בהקדמה ג, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370316\" data-slug=\"torah-or\" data-id=\"3901370316\">תו\"א יתרו עא, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370321\" data-slug=\"torah-or\" data-id=\"3901370321\">עב, ב</a>. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"ט (ובשני ההנחות שם). מאמר ד\"ה ולהבין וכו' מזבח הפנימי על יד הערה 21. סה\"מ תרכ\"ט ס\"ע רד. וש\"נ. ע' שעח. וש\"נ. תרל\"ג ח\"ב ע' שמו. וש\"נ. המשך מים רבים תרל\"ו פ\"ל. פל\"ב. המשך וככה תרל\"ז פע\"ו. פק\"ז."],["432","100","<b>שחיוהי. . האורות וגרמוהי הם הכלים</b>: ראה סה\"מ תרנ\"ג ע' עז: ”כן פי' בע\"ח ובאגה\"ק<sup data-n=\"e32\">א</sup> ד\"ה איהו וחיוהי\" רס\"כ. תרל\"ג שם. וש\"נ. המשך מים רבים תרל\"ו פקנ\"א. סה\"מ תרל\"ח ס\"ע יג ואילך ובהערה 125. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"ט."],["433","101","<b>לברוא. . יש מאין</b>: ראה אגה\"ק שם."],["434","102","<b>שהוא אינון ואינון הוא</b>: ראה זהר אחרי ע, א. עבודת הקדש חלק היחוד פ\"ד<sup data-n=\"e33\">ב</sup>."],["435","103","<b>הכלים</b>: אוצ\"ל: על הכלים."],["436","104","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה גם לקמן מאמר ד\"ה סמכוני באשישות ובהערה 51.\n\n<b>א</b>  וכ\"ה לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה הא' בפיסקא והנה להבין זה ובפיסקא וביאור. (בחלק ההנחות) הנחה ד\"ה יפה שעה הא' על יד הערה 71.\n\n<b>ב</b>  <b>מובא גם בשם עבודת הקדש בכ\"מ ומהם</b>: לקמן (בחלק ההנחות) הנחה ד\"ה כמים הפנים על יד הערה 55. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פט\"ז. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אני לדודי הב' על יד הערה 47. ד\"ה כנשר יעיר קנו על יד הערה 36. ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 123. (בחלק ההנחות) הנחה ד\"ה אני לדודי הב' על יד הערה 39. המשך וככה תרל\"ז פע\"ו. סה\"מ תרס\"ד ע' ריד."]]],[2000470129,"אוא\"ס העצמי כו' שבע\"ס דאצי', והגם שנת' במ\"א בענין נש\"י שעם היות שהם מבחי' הכלים עכ\"ז להיותם מפנימיות הכלים ה\"ה קרובין לגבי האור<sup data-n=\"437\">*105</sup>, ענין בחי' קירוב ודיבוק שני ענינים הם ואינם בערך זל\"ז כלל. ועמ\"ש בסדור בד\"ה אחרי הוי' אלקיכם תלכו בענין ובו תדבקון<sup data-n=\"438\">106</sup>, ובלק\"ת פ' ראה<sup data-n=\"439\">107</sup> בד\"ה אחרי הנ\"ל בשם הש\"ך<sup data-n=\"440\">108</sup>, שנמצא תיבת תדבקון זהו נגד אחד, שמשם יובן שערך הריחוק משארי בחי' לגבי בחי' תדבקון זהו כמו הריחוק מבחי' ההתבוננות והכנת ההתבוננו' לגבי בחי' ביטול במציאות דיחו\"ע בחי' מה בעצם כו'<sup data-n=\"441\">105</sup>.\n<b></b>קיצור. כמו שהוא בקרבנות כ\"ה בהקרבת הנשמות שמיכאל כה\"ג מקריבן ע\"ג המזבח שלמעלה, שיתעלו מבחי' גרמוהי לדבקה בבחי' חיוהי כו'.\n(ז) <b>והנה</b> נת\"ל<sup data-n=\"442\">109</sup> שהקרבת הבהמה ע\"ג המזבח נק' בשם אכילה ארי' דאכיל קרבנין, וכן ארז\"ל בשתי אכילות הכתוב מדבר אחת אכילת אדם ואחת אכילת מזבח, והיינו שכשם שבחי' ארי' דאכיל קרבנין נק' בשם אכילה שנת\"ל ענינה באריכות כן יש עוד בחי' אכילה שגבוה יותר מבחי' אכילת מזבח, והוא בחי' אכילת אדם, והיינו כי ענין בחי' ארי' דאכיל קרבנין ז\"ע העלי' מבחי' אש שלמטה לבחי' אש שלמעלה שנק' בשם אכילה ע\"ש שנכללת בהאוכל המאכל, אבל עכ\"ז הוא רק בבחי' ארי' שהוא ג\"כ בחי' חי' ועם היות שהוא מלך שבחיות<sup data-n=\"443\">111</sup> עכ\"ז מכלל בע\"ח יחשב כו', ואמנם אכילת אדם היינו שיוכלל בבחי' אדם, וי\"ל שלא בבחי' אדם שבמרכבה לבד &lt;10&gt;\nּ שהרי גם בחי' ארי' יש לו צורת אדם, א\"כ אין זה שתי אכילות, כ\"א בבחי' אדם שעל דמות הכסא דמות כמראה אדם כו' וכמ\"ש מזה בלק\"ת<sup data-n=\"444\">110</sup> בד\"ה ואכלתם אכול פ\"ב, והענין הוא דכתי' ואם האכל יאכל<sup data-n=\"445\">112</sup> בשתי אכילות הכתוב מדבר אחת אכילת אדם היינו מה שכהנים אוכלים ובעלים מתכפרים<sup data-n=\"446\">113</sup>, ואחת אכילת מזבח, פי' וענין האכילה הוא מה שמ\"ה מברר<sup data-n=\"447\">114</sup> ב\"ן<sup data-n=\"448\">115</sup>",[["437","*105","<b>נש\"י. . מפנימיות. . קרובין לגבי האור</b>: ראה גם מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' נט."],["438","106","<b>בסידור. . ובו תדבקון</b>: שער התפלה כו, א-ב."],["439","107","<b>ובלק\"ת פ' ראה</b>: כב, ד."],["440","108","<b>הש\"ך</b>: שפתי כהן לר' מרדכי הכהן."],["441","105","<b>ועמ\"ש. . כו'</b>: נכתב עה\"ג ובהמשך הנדפס: ליתא."],["442","109","<b>נת\"ל</b>: פ\"ה."],["443","111","<b>ארי'. . מלך שבחיות</b>: חגיגה יג, ב."],["444","110","<b>בשתי אכילות. . בלק\"ת</b>: נסמן בסמוך הערה 112."],["445","112","<b>ואם האכל יאכל</b>: צו ז, יח. זבחים יג, ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380107\" data-slug=\"likkutei-torah\" data-id=\"4001380107\">לקו\"ת צו ז, ד</a> ואילך. מאמרי אדה\"ז תקס\"ה ח\"א ע' קסג ואילך. סה\"מ תרכ\"ז ע' שלז. תרכ\"ט ע' רמט ואילך. וש\"נ. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וביום הביכורים על יד הערה 73 ואילך. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ויאמר כו' לך לך על יד הערה 30 ואילך. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויאמר כו' לך לך על יד הערה 41 ואילך."],["446","113","<b>שכהנים אוכלים ובעלים מתכפרים</b>: פסחים נט, ב. רמב\"ם הל' מעשה הקרבנות פ\"י, ה\"א. ראה גם לקמן שם. מאמרי אדה\"ז וסה\"מ (ובהנסמן לשם) בהערה שלפנ\"ז. שע\"ת מד, א. מאמרי אדה\"א במדבר ח\"ג ע' תתקנא. וש\"נ."],["447","114","<b>האכילה. . שמ\"ה מברר ב\"ן</b>: ראה גם ביאוה\"ז בלק קט, ד. סידור שער האלול רכז, ד. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370294\" data-slug=\"torah-or\" data-id=\"3901370294\">תו\"א בשלח סו, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380240\" data-slug=\"likkutei-torah\" data-id=\"4001380240\">לקו\"ת אמור לח, ג</a>."],["448","115","<b>שמ\"ה מברר ב\"ן</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. מאמרי אדה\"א דברים ח\"א ע' ה. וש\"נ. ח\"ב ע' תקעג ואילך. ח\"ד ע' א'ריג ואילך."]]],[2000470130,"ואכילת מזבח נת\"ל שזהו ענין ארי' דאכיל קרבנין, ואכילת אדם למעלה מבחי' ארי' דאכיל, כי עם היות שאכילת מזבח שהוא בחי' ארי' דאכיל קרבנין זהו ג\"כ ע\"ד שבחי' מ\"ה מברר ב\"ן, שהרי שרש הבהמה זהו ממה שנפל משמרי האופנים<sup data-n=\"449\">116</sup> והארי' הוא למעלה מהאופני' עצמן, וגם ארי' הוא אל הימין שמברר בחי' שור שמהשמאל<sup data-n=\"450\">117</sup>, ע\"ד מ\"ה וב\"ן מברר ומתברר כו', מ\"מ אכילת אדם זהו בחי' היותר גבוה ע\"ד דוגמא כמו ההפרש בין בירור ראשון לבירור שני<sup data-n=\"451\">118</sup>, אמנם באמת זהו הכל בחי' בירור ראשון רק שזהו בירור היותר נעלה מבחי' ארי' דאכיל כו' והיינו כנ\"ל שמתעלה בבחי' אדם דאצי' שלמעלה מהכסא כו', וזהו ע\"י אכילת כהנים דוקא בחי' אדם דכתי' נעשה אדם בצלמנו כדמותנו<sup data-n=\"452\">119</sup> שהוא בצלם ודמות בחי' אדם שלמעלה לכן ע\"י אכילתו מתעורר למעלה בחי' אכילת אדם העליון כו' (ועוי\"ל שע\"י אכילת כהנים שהם בחי' אדם שנכלל זבח הקרבן שהוא בהמה בבחי' אדם שהוא הכהן האוכל את הזבח עי\"ז נעשה אדם ובהמה תושיע ה'<sup data-n=\"453\">120</sup> שע\"י שנכלל בחי' בהמה בבחי' אדם עי\"ז נמשך שע\"ה נהורין<sup data-n=\"454\">121</sup>, והגם שבכ\"מ הפי' אדם ובהמה כשהאדם הוא בטל ונמשך כבהמה<sup data-n=\"455\">122</sup> שז\"ע ביטול שלמעלה מהשכל, עכ\"ז גם זה שנכלל הבהמה באדם (או י\"ל כפשוטו שבירור נה\"ב שבא לבחי' הביטול שלמעלה מטו\"ד, וה\"ז אדם ובהמה כמ\"ש בכ\"מ כו') והכהן פירושו משרת<sup data-n=\"456\">123</sup> שהוא בטל לאדונו זהו ג\"כ אדם ובהמה שעי\"ז נמשך שע\"ה נהורין כו'). ובכ\"ז יובן שרש ענין טוב מאד זה יצה\"ר לפי ב' הפירושי'<sup data-n=\"457\">124</sup>, שע\"י בירור היצה\"ר או ע\"י הסרת הלבושים שהלביש את תוכן בחי' פנימיות כוונתו ע\"י כמים הפנים לפנים נמשך מלמעלה להיות סליק יקרא דקוב\"ה<sup data-n=\"458\">125</sup> בכולהו עלמין מבחי' עצם הענג, ע\"ד שהאופנים ע\"י הרעש שלהם מחמת ההסתר ממשיכים להיות כבוד ה' ממקומו",[["449","116","<b>שרש הבהמה. . משמרי האופנים</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380107\" data-slug=\"likkutei-torah\" data-id=\"4001380107\">לקו\"ת צו ז, ד</a>."],["450","117","<b>ארי'. . שמברר בחי' שור שמהשמאל</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380352\" data-slug=\"likkutei-torah\" data-id=\"4001380352\">לקו\"ת במדבר יא, א</a>. סה\"מ תרל\"ח ע' לה."],["451","118","<b>בירור ראשון לבירור שני</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370131\" data-slug=\"torah-or\" data-id=\"3901370131\">תו\"א וישב כח, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370216\" data-slug=\"torah-or\" data-id=\"3901370216\">ויחי מז, ד</a>. ביאוה\"ז נח ו, ג-ד. ויחי כט, א-ב. מאמרי אדה\"ז שבהערה 112."],["452","119","<b>נעשה אדם בצלמנו כדמותינו</b>: בראשית א, כו."],["453","120","<b>אדם ובהמה תושיע ה'</b>: תהלים לו, ז."],["454","121","<b>שע\"ה נהורין</b>: ראה גם לקמן המשך מצה זו פל\"ז. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי טובים דודיך מיין על יד הערה 19. ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 121. (בחלק ההנחות) בהנחה כאן על יד הערה 93. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה עשה צדקה ומשפט על יד הערות 79. 40. ד\"ה אשריכם זורעי על כל מים על יד הערה 124<sup data-n=\"e34\">ג</sup>. לקו\"ת במפתח ענינים מערכת מספר — שע\"ה. ש\"א יד, א הערות 12-14. סה\"מ תרל\"ח ס\"ע רנא. וש\"נ. סה\"מ מלוקט ב' ע' קס ובהערה 44."],["455","122","<b>אדם ובהמה. . ונמשך כבהמה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380292\" data-slug=\"likkutei-torah\" data-id=\"4001380292\">לקו\"ת בחוקותי נ, רע\"ג</a>."],["456","123","<b>והכהן פירושו משרת</b>: ראה רש\"י ויגש מז, כב."],["457","124","<b>ב' הפירושי'</b>: לעיל פ\"ב."],["458","125","<b>סליק יקרא דקוב\"ה</b>: ראה לעיל הערה 27.\n\n<b>ג</b>  <b>ושם</b>: ותכ\"ד חזר וא' ש\"ע."]]],[2000470131,"ממקורו ושרשו כמ\"ש בד\"ה ואולם חי אני<sup data-n=\"459\">126</sup> דתקס\"ד<sup data-n=\"460\">127</sup> ובהביאורים ע\"ש, ובס' תרך\"ב<sup data-n=\"461\">128</sup>.\n<b></b>קיצור. בשתי אכילות הכתוב מדבר, אכילת מזבח זהו מה שארי' אכיל קרבנין ואכילת אדם זהו עיקר בחי' מה שבחי' מ\"ה מברר ב\"ן כו', וזהו ע\"י אכילת כהנים דוקא כו'.",[["459","126","<b>ממקומו ממקורו ושרשו. . ואולם חי אני</b>: ראה מאמרי אדה\"ז תקס\"ט ע' קפה. ע' קצו ואילך. סהמ\"צ להצ\"צ ע' 356. ע' 366 ואילך. אוה\"ת שלח ע' תקיג. סה\"מ תרל\"ד ע' רמג ואילך ובהנסמן בריש המאמר שם. תרל\"ח ע' טז. וש\"נ. לקמן מאמר ד\"ה סמוכים פ\"ב. לקמן ח\"ב מאמר והנחה ד\"ה ויאמר כו' לך לך."],["460","127","<b>ואולם חי אני דתקס\"ד</b>: כ\"ה גם בהמשך הנדפס. וראה הערה שלפנ\"ז."],["461","128","<b>ואולם חי אני. . ובס' תרכ\"ב</b>: כ\"ה גם בהמשך הנדפס."]]],[2000470132,"<h3>[תכון תפלתי] והנה כו' אכלתי יערי</h3>\n<b>בס\"ד פ' וארא</b>\n(ח) <b>והנה</b> כל מה שנת\"ל בענין הקרבנות זהו הכל מה שהוא בבחי' או\"פ ועז\"נ אכלתי יערי<sup data-n=\"462\">129</sup> עם דבשי<sup data-n=\"463\">130</sup>, שכשם שנת\"ל בענין עבודת המלאכים כן בעבודה שבלב בתפלה &lt;11&gt;\nּ שכנגד תמידין תקנו יוצ\"א הוא בדוגמת עבודת המלאכים, ולכן ביוצ\"א שם נא' כל עבודת המלאכים שרפים חיות ואופנים, ודבשי",[["462","129","<b>והנה כו' אכלתי יערי</b>: מאמר זה הוא מאמר הד' מההמשך וכולל פרקים ח-יו\"ד.\nחלק הראשון של המאמר מיוסד על מאמר ד\"ה זאת חנוכת המזבח שבבוך 1116 כנ\"ל בריש ההמשך (ומקבילו ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380424\" data-slug=\"likkutei-torah\" data-id=\"4001380424\">לקו\"ת נשא כט, א</a>. וראה הנסמן במ\"מ לשם).\nחלק השני — פ\"י — מיוסד על מאמר ד\"ה הנה ענין מחוץ לפרכת שנדפס במאמרי אדה\"ז על פרשיות התורה ח\"א ע' שנא ואילך. והנחה אחרת ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370489\" data-slug=\"torah-or\" data-id=\"3901370489\">תו\"א תצוה קי, א</a>. וראה הנסמן לעיל בריש ההמשך.\nלקמן בחלק ההנחות נדפסה הנחה ממאמר זה ושם הפתיחה: תכון תפלתי קטרת לפניך. מאמר זה נזכר בסה\"מ תרמ\"ג ע' סה<sup data-n=\"e35\">*</sup>."],["463","130","<b>אכלתי יערי עם דבשי</b>: שה\"ש ה, א. ראה זהר פינחס רכו, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380795\" data-slug=\"likkutei-torah\" data-id=\"4001380795\">לקו\"ת פ' ראה יט, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381266\" data-slug=\"likkutei-torah\" data-id=\"4001381266\">שה\"ש לד, ב</a>."],["e35","*","<b>להלן נעתק חלק המאמר מבוך הנ\"ל שנתבאר בדרוש זה</b>:\n”אכלתי יערי עם דבשי אבל יש בחי' א' והיא בחי' מקיף שהוא ענין הקטרת שהוא רק ריח שהנשמה נהנה בו ולא הגוף אינו נכנס בגוף כלל בבחי' פנימי' רק שהוא בבחי' מקיף מלמעלה הנה הקטרת לא היתה קריבה ע\"ג מזבח החיצון כ\"א ע\"ג מזבח הפנימי רק בנשיאי' היתה הוראת שעה שהקריבו קטרת ע\"ג מזבח החיצון והיינו בשביל חנוכת המזבח כמשל התינוק המחנכין אותו ללימוד נותנין לו מתנה יתירה כדי להרגילו להתחיל בלימוד משא\"כ כשהוא כבר הרגיל א\"ע והתחיל כו' וזהו ענין הבו לה' כבוד שכבוד הוא ענין מקיף והארה יתירה כדי להיו' נמשך אח\"כ הז' קולות והכבוד הזה צריך להמשיך מתחלה וכן נותנין מתנה לכבוד חתן וכלה לפי שנעשה יחוד חדש כי החתן חות דרגא וכלה כלתה נפשי ממטה למעלה והם שני הפכים שמתייחדים וכדי להמשיך יחוד חדש כזה צריך להמשיך תחלה בחי' כבוד שהוא תוספת הארה בבחי' מקיף ולכן הקריבו הנשיאי' קערות כסף וכפות זהב אף שמנחת נדבה מביאין בכפיפה מצרית רק הנשיאי' עשו לכבוד ולתפארת אך כדי להיו' המשכת קטרת שהיא בבחי' מקיף צ\"ל משיחת המזבח בשמן המשחה כי שמן המשחה הוא ממוצע בין פנימי למקיף כי שמן הוא משקה ובשמן המשחה היה מעורב בשמים ראש מר דרור קנמן בשם כו' שהוא ענין הריח הרי שהי' תערובת בחי' פנימי ומקיף ומ\"מ בחי' מקיף נקרב ביום המשח שהכל בחי' א' משא\"כ שאר הקרבנות שהם אכילת המזבח ולזבח השלמים כל הבקר לעולה כו' היו אחרי המשח שמתחלה הי' צ\"ל בחי' המקיף לחינוך ואח\"כ היתה אכילת המזבח וד\"ל ולכך בקרבנות שהם אכילת המזבח כתי' אחרי המשח אותו ובקטרת והבאת הקערות שהם בבחי' מקיף ובחי' כבוד כתי' ביום המשח כו'\"."]]],[2000470133,"הוא ק\"ש שהוא בחי' המתיקות דק\"ש בחי' עריבות ידידות מתיקות ונעימות<sup data-n=\"464\">131</sup> שנמשך ע\"י ההתבוננות דשמע ובשכמל\"ו יחו\"ע ויחו\"ת כו', אמנם כ\"ז הוא בבחי' הפני' רק שבק\"ש יש בחי' בכל מאדך<sup data-n=\"465\">132</sup> שהו\"ע לצאת מהגבלת הכלי לגמרי שלזה נק' בשם מאד כו'.\n<b>אך</b> עוד עבודה א' הי' במקדש שהיא בבחי' מקיף לבד, והוא בחי' הקטרת הקטרת, ולא היתה קריבה על מזבח החיצון כ\"א על מזבח הפנימי<sup data-n=\"466\">133</sup> לבד, והוא רק בחי' ריח דבר שהנשמה נהנית<sup data-n=\"467\">134</sup> ממנה ולא הגוף, רק בחנוכת המזבח שחנכו הנשיאים היתה הוראת שעה שהקטירו קטרת גם על מזבח החיצון<sup data-n=\"468\">135</sup> וזהו בשביל החנוכה שחנכו את המזבח וכמשל התינוק שמחנכי' אותו שילך לביה\"ס הולכים עמו הגדולים כנ\"ל<sup data-n=\"469\">136</sup> ונותנים לו מתנה מרובה ויתירה שלא ע\"צ ההרגל אתו בשאר הימים שהכל הוא בכדי לחנכו ולהרגילו לילך לביה\"ס, משא\"כ כשכבר הרגיל א\"ע לילך לביה\"ס אז הנהוג אתו כמו שהוא לפי ערכו כו', וזהו דכתי' הבו לה' כבוד ועוז<sup data-n=\"470\">137</sup>, שלכאו' אינו מובן כלל מ\"ע הבו לה' כבוד הלא לי הכבוד אמר ה' צבאות<sup data-n=\"471\">138</sup> ומה\"ע הבאת הכבוד לו ית' כו'. אך הענין הוא דכבוד הוא בחי' מקיף שהרי זהו דבר שאינו רק מה שנמשך בבחי' הפנימיות לבד כ\"א רובו ככולו הוא בחי' מקיף ומה שיש בו שנמשך בבחי' הפנימיות זהו הארת והסתעפות לבד, והוא מה שהארת המקיף מאיר",[["464","131","<b>עריבות. . ונעימות</b>: ראה אוה\"ח ר\"פ אחרי ד\"ה א\"י עז\"ה. מובא בכ\"מ בדא\"ח ומהם מאמרי אדה\"א בראשית ע' קעו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550246\" data-slug=\"torat-chaim\" data-id=\"2300550246\">תו\"ח תרומה ח\"ב שו, א</a>. וש\"נ."],["465","132","<b>בכל מאדך</b>: ואתחנן ו, ה. ראה לקמן (בחלק ההנחות) בהנחה כאן ובהערה 30."],["466","133","<b>הקטרת. . מזבח הפנימי</b>: ראה תצוה ל, א. ז. ח. סהמ\"צ להרמב\"ם מ\"ע כח. רמב\"ם הל' כלי המקדש פ\"א, הי\"א. הל' תמידין ומוספין רפ\"ג."],["467","134","<b>ריח. . שהנשמה נהנית</b>: ראה ברכות מג, ב. לקמן (בחלק ההנחות) בהנחה כאן פיסקא והנה בבהמ\"ק. ראה גם ש\"א ז, ב. יא, ב. לקמן מאמר ד\"ה סמכוני באשישות ובהערה 59. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה שם על יד הערה 77. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת על יד הערה 69. (בחלק ההנחות) בהנחה שם על יד הערה 86."],["468","135","<b>הוראת שעה. . קטרת. . מזבח החיצון</b>: נשא ז, יד וברש\"י שם ממנחות נ, א."],["469","136","<b>וכמשל התינוק. . כנ\"ל</b>: ראה לעיל פ\"א ובהערה 5."],["470","137","<b>הבו לה' כבוד ועוז</b>: תהלים כט, א."],["471","138","<b>לי הכבוד אמר ה' צבאות</b>: כ\"ה גם בהמשך הנדפס. לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 39: ה' צבאות הוא מלך הכבוד."]]],[2000470134,"בפנימיות, וכל ענין מקיף דבחי' הכבוד הזה זהו הארה יתירה בשביל שעי\"ז יומשך אח\"כ כל הז' קולות שנא' אח\"כ כו', ועם היות כי לי הכבוד אמר ה' עכ\"ז הלא באמת כולם בחכ' עשית<sup data-n=\"472\">139</sup> שגם ל\"ב נ\"ח שבגימ'<sup data-n=\"473\">140</sup> כבוד<sup data-n=\"474\">141</sup> כעשי' גשמיות<sup data-n=\"475\">142</sup> נחשב כו' לכן צריכים להמשיך בחי' הכבוד הזה וזהו הבו לה' כבוד כו', וכן אנו רואים שלכבוד חו\"כ נותנים מתנות יקרות שכ\"ז הוא בשביל שיומשך אח\"כ בחי' יחוד חדש שעי\"ז יומשך בחי' אור חדש שלא הי' לעולמים, והיינו כי חתן הוא חות דרגא<sup data-n=\"476\">143</sup>, שזהו ירידה והשפלה לפניו לירד מבחי' ההתקשורת באו\"א שהי' תחלה ויעזוב את או\"א שבאצי', ודבק באשתו<sup data-n=\"477\">144</sup> להשפיע לה בחי' שפע הפנימי שלו, והכלה היא גם היא כלתה נפשה<sup data-n=\"478\">145</sup> מלמטלמ\"ע בבחי' תשוקה נפלאה כמ\"ש ואל אישך תשוקתך<sup data-n=\"479\">146</sup>, שע\"י העלאה והמשכה זו נמשך או\"ח לגמרי מה שלא הי' לעולמים כלל להוליד בדומה לו ממש, גם נמשך בחי' המשכות חדשות כו' ע\"י יחוד ב' הפכי' אלו, ולכן כדי שיומשך בחי' זו צ\"ל תחלה בחי' כבוד חו\"כ שהוא בחי' תוספת הארה בבחי' מקיף, ולכן הקריבו הנשיאים קערות כסף, כפות זהב<sup data-n=\"480\">147</sup>, הגם שמנחת נדבה היו מביאין בכפיפה מצרית<sup data-n=\"481\">148</sup>, רק עשו כן לכבוד ולתפארת ליחוד הקב\"ה עם נש\"י כמ\"ש ונועדתי לך שם<sup data-n=\"482\">149</sup>, אותיות ונודעתי<sup data-n=\"483\">150</sup> מל' והאדם ידע<sup data-n=\"484\">151</sup>, והעלאות והמשכת וקירוב הכחות והשמות שע\"י הקרבנות כו'.\n&lt;12&gt;\nּ <b>קיצור.</b> וכ\"ז הוא בחי' או\"פ, ויש בחי' או\"מ והיא הקטרת, דבר שהנשמה נהנית, וזהו הבו לה' כבוד, וכן ענין כבוד חו\"כ, או\"ח נש\"ח כו', וזהו הקערות וכפות זהב מליאה<sup data-n=\"485\">152</sup> קטרת כו'.\n(ט) <b>ואמנם</b> כדי שיהי' בחי' המשכת הקטרת שהוא בחי' מקיף צ\"ל משיחת המזבח בשמן המשחה, כי הנה ענין ובחי' שמן המשחה הוא בחי' הממוצע בין פנימי למקיף, כי השמן הוא משקה ובשמן הזה הי' מעורב בשמים ראש, מר דרור",[["472","139","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["473","140","<b>ל\"ב. . שבגימט' כבוד</b>: זהר רע\"מ צו לג, א."],["474","141","<b>ל\"ב נ\"ח שבגימ' כבוד</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"א מערכת כבוד. מאמרי אדה\"א בראשית ע' ג ואילך. דברים ח\"ב ע' שפ. וש\"נ."],["475","142","<b>כעשי' גשמיות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא פ\"ב</a> בהגהה. (לקמן בחלק ההנחות) בהנחה כאן ובהערה 46. הנסמן במאמרי אדה\"א קונטרסים ע' רנב. סה\"מ תרל\"ח ע' קג הערה 223."],["476","143","<b>חתן הוא חות דרגא</b>: ראה יבמות סג, א."],["477","144","<b>ויעזוב את או\"א. . ודבק באשתו</b>: בראשית ב, כד."],["478","145","<b>כלה. . כלתה נפשה</b>: ע\"פ תהלים פד, ג."],["479","146","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["480","147","<b>הקריבו הנשיאים קערות כסף כפות זהב</b>: נשא ז, יג. יד."],["481","148","<b>שמנחת נדבה. . בכפיפה מצרית</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071216\" data-slug=\"likkutei-sichot\" data-id=\"1300071216\">לקו\"ש ויקרא כרך ז ע' 205</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300281331\" data-slug=\"likkutei-sichot\" data-id=\"1300281331\">נשא כרך כח ע' 320</a> ואילך (נדפס גם באג\"ק שלו ח\"ג ע' רלד<sup data-n=\"e36\">א</sup>)."],["482","149","<b>ונועדתי לך שם</b>: תרומה כה, כב."],["483","150","<b>ונועדתי. . ונודעתי</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380313\" data-slug=\"likkutei-torah\" data-id=\"4001380313\">לקו\"ת במדבר א, סע\"ב</a>."],["484","151","<b>והאדם ידע</b>: בראשית ד, א."],["485","152","<b>נש\"ח. . מליאה</b>: לקמן (בחלק ההנחות) בהנחה כאן פיסקא ובזה יובן: נשמות חדשות. . בהמשך הנדפס: מלאות.\n\n<b>א</b>  <b>ושם</b>: ”זאת חנוכה תר\"ס\" ואולי צ\"ל: זאת חנוכת תר\"ם."]]],[2000470135,"קנמן בשם<sup data-n=\"486\">153</sup> כו' שהוא ענין הריח, א\"כ הי' תערובות בחי' פנימי ומקיף, והיינו להיותו בחי' הממוצע בין פנימי למקיף לכן הי' יכול לסבול שניהם, ועכ\"ז מהותו הוא שמן שהוא משקה היינו מה שנמשך בבחי' הפנימיות, והיינו כי עיקר המכוון מהמקיף שיומשך בחי' או\"פ רק שא\"א בלי ממוצע כו', ומ\"מ בחי' מקיף נקרב ביום המשח אותו שהכל בחי' אחד, משא\"כ שארי הקרבנות שהם אכילת מזבח, ולזבח השלמים<sup data-n=\"487\">154</sup>, כל הבקר לעולה<sup data-n=\"488\">155</sup> הי' אחרי המשח, שמתחלה הי' צ\"ל בחי' המקיף שז\"ע בחי' החינוך, ואח\"כ הי' אכילת מזבח, ולכן בקרבנות שהם אכילת מזבח כתי' אחרי המשח אותו, ובקטרת והבאת הקערות שהם בחי' מקיף ובחי' כבוד כתי' ביום המשח<sup data-n=\"489\">156</sup> כו'.\n<b>ועפ\"ז</b> יובן ג\"כ ענין קריאת שם חנוכה שכינו רז\"ל על המצא הפך, והצלתם בהצלחתם שגברו מ' בית חשמונאי, דהנה פי' שטמאו כל השמנים<sup data-n=\"490\">157</sup> שהי' בהיכל, זהו שכמו שיש בקדושה<sup data-n=\"491\">160</sup> בחי' חכ'<sup data-n=\"492\">159</sup> כן בלעו\"ז יש בחי' חכ' דקלי'<sup data-n=\"493\">158</sup> שהיא לעומת בחי' הקדושה ממש, ולכן הפליגו כל ספרי המוסר בלימוד חכ' חיצוני'<sup data-n=\"494\">161</sup>, ובגמ' אמרו שילמוד בשעה שלא יום ולא לילה<sup data-n=\"495\">162</sup>, וע' בסש\"ב שביאר איך שמטמא חב\"ד שבנפשו<sup data-n=\"496\">163</sup>, והיינו שנמשך בחי' או\"מ דטומאה ששרשה",[["486","153","<b>בשמים. . קנמן בשם</b>: תשא ל, כג."],["487","154","<b>ולזבח השלמים</b>: נשא ז, (יז) פח [ושם: וכל בקר זבח השלמים]."],["488","155","<b>כל הבקר לעולה</b>: נשא ז, פז."],["489","156","<b>בקרבנות. . אחרי המשח. . ובקטרת והבאת הקערות. . ביום המשח</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380109\" data-slug=\"likkutei-torah\" data-id=\"4001380109\">לקו\"ת צו ח, ב</a>. כאן כט, סע\"ב. אוה\"ת נשא כרך ד ע' א'תסו<sup data-n=\"e37\">ב</sup>."],["490","157","<b>חנוכה. . המצא הפך. . שטמאו כל השמנים</b>: שבת כא, ב. ראה לעיל רפ\"א."],["491","160","<b>בקדושה בחי' חכ'. . חכ' דקלי'</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380194\" data-slug=\"likkutei-torah\" data-id=\"4001380194\">לקו\"ת אחרי כז, ג</a>. שע\"ת סט, א ובהערה 10. סה\"מ תרל\"ח ס\"ע קלד. לקמן (בחלק ההנחות) בהנחה כאן."],["492","159","<b>השמנים. . חכ'</b>: ראה זהר יתרו פז, ב תרומה קמז, ב ובהגהת הרח\"ו שם. מאורי אור מערכת שמן אות מח וביאיר נתיב שם. מאמרי אדה\"א קונטרסים ע' תקמה. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370184\" data-slug=\"torah-or\" data-id=\"3901370184\">תו\"א מקץ מ, ד</a>. לקמן ספי\"ג. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה רני ושמחי על יד הערה 72 מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380114\" data-slug=\"likkutei-torah\" data-id=\"4001380114\">לקו\"ת צו ט, ג</a>. סה\"מ תרל\"ח ע' כג. וש\"נ. לקמן המשך מצה זו פכ\"ד על יד הערה 746 מ<a class=\"ft-cite\" href=\"#/read/torah-or/3901370409\" data-slug=\"torah-or\" data-id=\"3901370409\">תו\"א מג\"א צ, סע\"ד</a> [ח\"ע]. שם רפנ\"ט. ש\"א עו, א."],["493","158","<b>שטמאו כל השמנים. . חכ' דקלי'</b>: ראה לקמן המשך מצה זו רפנ\"ט. (בחלק ההנחות) בהנחה כאן על יד הערה 68 ואילך. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואלא עלמא אמאי קאים על יד הערה 41 ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370157\" data-slug=\"torah-or\" data-id=\"3901370157\">תו\"א מקץ לד, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370185\" data-slug=\"torah-or\" data-id=\"3901370185\">מא, א</a>. ג. סהמ\"צ להצ\"צ ס\"ע 142 ואילך. ש\"א מב, א ובהערה 14. סה\"מ תרמ\"ג ע' מח. תרמ\"ד ע' רח. סה\"מ מלוקט ב' ע' יח וע' כ."],["494","161","<b>ספרי המוסר בלימוד חכ' חיצוני'</b>: ראה גם של\"ה מס' שבועות קפג, א. הל' ת\"ת לאדה\"ז פ\"ג, ה\"ז ובהנסמן בהערות וציונים לשם. וראה גם בענין חכ' חיצוני' לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 66 ואילך. מאמרי אדה\"ז תקס\"ג ח\"א ע' ערה ואילך. תק\"ע ע' קפב. ענינים ע' קסה. מאמרי אדה\"א דברים ח\"א ע' ט ואילך ובהנסמן שם. פירוש המלות מב, ב ובשולי הגליון שם [במהדורת תשנ\"ג]. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450315\" data-slug=\"or-hatorah-hb\" data-id=\"8316450315\">אוה\"ת</a> ישעי' כרך ב ע' תשפג. תצא כרך ו ע' ב'שנו. מגדל עז ע' תלט ואילך."],["495","162","<b>חכ' חיצוני'. . בשעה. . לילה</b>: ראה מנחות צט, ב (הובא בהל' ת\"ת שם). לקמן (בחלק ההנחות) בהנחה כאן."],["496","163","<b>בסש\"ב. . שמטמא חב\"ד שבנפשו</b>: ספ\"ח וראה מ\"מ הגהות והע\"ק שם.\n\n<b>ב</b>  במהדורת תשנ\"ה נשא בהוספות ע' 117."]]],[2000470136,"מבחי' אבי אבות הטומאה<sup data-n=\"497\">164</sup>, ונמצא מובן ענין שטמאו כל השמנים היינו שע\"י הסטה הסיטו והזיזו ממקומו את בחי' חכ' דקדושה שיומשך עלי'<sup data-n=\"498\">165</sup> בחי' מקיף דקלי' ע\"ד טומאת החב\"ד ע\"י הלימודי' בס' חיצוני', ולהיות כן לא הי' מקום כלל על בחי' השראת הקדושה בבהמ\"ק וממילא לא הי' באפשרי להיות בחי' בירור הקרבנו' וכנ\"ל ששמן המשחה הוא הממוצע כו', ואם כי בו יש בשמים ראש בחי' ריח עכ\"ז מהותו הוא שמן, וכשטמאו כל השמנים אז גם מבחי' שמן זה לא הספיק שיוכל להיות גם עבודת הקרבנות כו', ולכן כשמצאו פך א' של שמן חתום<sup data-n=\"499\">166</sup> בחותמו של כה\"ג שענין החותם הוא שלא יקרב וישלוט בו ידי זרים, והפך מוקף צמיד פתיל שזהו בחי' או\"מ כו' וממילא לא שרה עליו רוח הטומאה שהרי או\"מ דוחה<sup data-n=\"500\">167</sup> ומסמא<sup data-n=\"501\">168</sup> כו' כידוע ולא הי' בו אלא כדי להדליק יום א' והיינו כמו שנמשך בסדר המדרגות שע\"י הממוצע הנ\"ל נמשך בחי' הפנימי' בכ\"י תמיד, נעשה נס והדליקו ממנו שמונה ימים, ענין בחי' שמונה נודע כי בחי' הבינה היא תמינאה<sup data-n=\"502\">169</sup>, ובינה מקור כל המקיפי'<sup data-n=\"503\">170</sup> שבז\"א, וכלליות השמונה ימים הן מן הבינה עד המל', להורות על חיבור &lt;13&gt;\nּ המקיף עם הפנימי שזהו כמו שמן המשחה שהוא עצמו שמן ובו בשמים ראש כו' ריח מקיף, לכן קראו שם יו\"ט זה בשם חנוכה, והיינו שזהו כדוגמת חנוכת המזבח והמקדש וכל כליו, והגם שעיקר הנס לכאו' הוא מה שגברו כו' ונצחום, מ\"מ בלתי הפך הזה של כה\"ג שהוא חיבור בחי' המקיף עם הפנימי לא הי' בחי' השראת הקדושה, ולכן קראו אותו שם חנוכה<sup data-n=\"504\">171</sup> שכשם שכששרה הקדושה במעשי' ש\"י עשו הנשיאים חנוכת המשכן והמזבח בקערות וזבחים ועולות, כ\"ה כשטמאו כו' ומצאו פך חתום כו' ה\"ז ג\"כ כמו חנוכה הנ\"ל, ולכן קורין פ' הנשיאים בחנוכה כו'.\n<b></b>קיצור. שכדי להיות המשכת בחי' הקטרת זהו ע\"י ממוצע והוא שמן המשחה שהי' שמן ובו בשמים ריח, ומ\"מ במקיף נא' ביום המשח ובקרבנות אחרי המשח, ועפ\"ז יובן ענין שם חנוכה שמצאו פך חתום חיבור המקיף עם הפנימי, והדליק שמונה ימים שיומשך המקיף בבחי' פנימיות כו'.",[["497","164","<b>אבי אבות הטומאה</b>: ראה רש\"י פסחים יד, ריש ע\"ב. יז, א. הנסמן באנציק' תלמודית בערכו."],["498","165","<b>עלי'</b>: בהמשך הנדפס: עליהם."],["499","166","<b><a class=\"ft-cite\" href=\"#/read/torah-or/3901370157\" data-slug=\"torah-or\" data-id=\"3901370157\">חתום</b>: בשבת כא, ב</a>: מונח. אבל כ\"ה גם בטור או\"ח הל' חנוכה סתר\"ע. וראה ב\"ח שם ד\"ה ה\"ג — סה\"מ מלוקט ב' ע' יח הערה 25. וכ\"ה גם בשאילתות חנוכה במהדורת מירסקי שאילתא כז בתחלתה. וברי\"ף שם חתום ומונח בחותמו. תו\"א מקץ לד, א. לעיל בריש ההמשך ובהנחה שם."],["500","167","<b>או\"מ דוחה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370020\" data-slug=\"torah-or\" data-id=\"3901370020\">תו\"א בראשית ה, ג</a>: ”כנראה בציור האילן שבפרד\"ס\". ע\"ח שער לאה ורחל של\"ז, פ\"ז: שהמוחין דאבא הם הדוחין את החיצונים."],["501","168","<b>או\"מ. . ומסמא</b>: ראה מאמר ד\"ה הוא הי' אומר תרל\"א [קונט' בר מצוה תרנ\"ג ע' לט]: כמ\"ש האריז\"ל שאור אבא מסמא. ע\"ח שער דרושי אבי\"ע שמ\"ב, פי\"ג. סה\"מ תרל\"ח ע' שי ואילך. ע' תצט ואילך."],["502","169","<b>הבינה היא תמינאה</b>: ראה זהר תרומה קסה, א."],["503","170","<b>ובינה מקור כל המקיפים</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"ג. לקו\"ת להאריז\"ל תהלים סנ\"ג."],["504","171","<b>קראו. . חנוכה</b>: ראה לעיל פ\"א הערה 7."]]],[2000470137,"(יו\"ד) <b>והנה</b><sup data-n=\"505\">172</sup> אהרן הוא הרועה הממשיך עד בי\"ע, וזהו דכתי' מחוץ לפרוכת<sup data-n=\"506\">174</sup>, והיינו כי אהרן הוא בחי' שושבינא דמטרוניתא<sup data-n=\"507\">175</sup> שהוא הוא המעלה כנס\"י להעלותם בעילוי אחר, והוא ע\"י שממשיך המשכת אוא\"ס בבי\"ע עד שגם הנשמות דבי\"ע יתעלו, וזהו מחוץ לפרוכת היינו בבי\"ע יערוך אהרן<sup data-n=\"508\">176</sup> בחי' שושדמ\"ט את הנרות<sup data-n=\"509\">177</sup> הם נש\"י<sup data-n=\"510\">178</sup> להעלותם בעילוי אחר עילוי כמ\"ש ובהעלות אהרן את הנרות<sup data-n=\"511\">179</sup>, וכתי' בהעלותך את הנרות<sup data-n=\"512\">180</sup> כו', וכל העלי' הוא רק עד האצי' כי באצי' א\"צ לשושבין כלל, להיות כי שם איהו וחיוהי חד וכמשנת\"ל<sup data-n=\"513\">181</sup>, ולכן רק מחוץ לפרוכת היינו בבי\"ע יערוך את הנרות דנש\"י, היינו שממשיך להם סיוע שיוכלו להעלות כמו הרועה הרועה צאנו במרעה טוב ועי\"ז הם הולכים ורצים כדרכם, כן בכדי להעלות נש\"י מבי\"ע לאצי' זהו ע\"י אהרן שלכן נק' בשם רועה<sup data-n=\"514\">173</sup> כו', וע\"ד שמצינו בגמ' ב\"מ דפ\"ה ב' לבר מגוהרקא דר\"ח דמנפשי' סליק, ולכולם יש מלאכים המסייעים אותם כו', כמש\"ש בכולהו יש מלאכי כד סלקין ונחתין, ועד\"ז יובן ענין יערוך אהרן את הנרות, וכ\"ז הוא מחוץ לפרוכת כו'.\n<b>וביאור</b><sup data-n=\"515\">182</sup> הענין דהנה פרוכת מתרגמינן פרסא<sup data-n=\"516\">183</sup>, וא\"כ זהו הפרסא שמפסיק בין האצי' לבי\"ע<sup data-n=\"517\">184</sup>, וענין הפרסא הוא בחי' ש' אלקי' כמ\"ש מזה בכ\"ד, וכמ\"ש שמש ומגן<sup data-n=\"518\">185</sup> ה' אלקי' שנמשל ש' אלקי' למגן הוא נרתק",[["505","172","<b>והנה</b>: מכאן מיוסד על מאמר ד\"ה הנה ענין מחוץ לפרכת שנדפס במאמרי אדה\"ז על פרשיות התורה ח\"א ע' שנא ואילך (וראה לקמן שולי הגליון להערה 183). והנחה אחרת ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370489\" data-slug=\"torah-or\" data-id=\"3901370489\">תו\"א תצוה קי, א</a>. וראה הנסמן לעיל בריש ההמשך.\nפיסקא זו מיוסדת על הנדפס שם ע' שנב ס\"ב שו\"ה הנ\"ל — והנה אהרן."],["506","174","<b>מחוץ לפרוכת</b>: תצוה כז, כא. אמור כד, ג."],["507","175","<b>אהרן. . שושבינא דמטרוניתא</b>: ראה זהר רע\"מ ויקרא כ, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קג. מאמרי אדה\"א שמות ח\"ב ע' שטו וע' שמ."],["508","176","<b>יערוך אהרן</b>: המשך הכתוב תצוה ואמור שם [בדילוג]."],["509","177","<b>יערוך.. את הנרות</b>: אמור שם, ד."],["510","178","<b>הנרות הם נש\"י</b>: ראה לקו\"ת ר\"פ בהעלותך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550614\" data-slug=\"torat-chaim\" data-id=\"2300550614\">תו\"ח תצוה ח\"ב שלו, ג</a>. וש\"נ."],["511","179","<b>ובהעלות אהרן את הנרות</b>: תצוה ל, ח."],["512","180","<b>בהעלותך את הנרות</b>: בהעלותך ח, ב."],["513","181","<b>וכמשנת\"ל</b>: פ\"ו."],["514","173","<b>אהרן הוא הרועה. . נק' בשם רועה</b>: לעיל במאמרי אדה\"ז כאן ספ\"א הובא לקמן ספי\"א (ובההנחה כאן): אהרן שהוא משבעה רועי'. נסמן לקמן הערה 231."],["515","182","<b>וביאור</b>: פיסקא זו מיוסדת על הנדפס במאמרי אדה\"ז שם ע' שנא. וראה הנסמן לעיל בריש ההמשך."],["516","183","<b>פרוכת מתרגמינן פרסא</b>: לקמן (בחלק ההנחות) בהנחה כאן על יד הערה 90: ות\"א. וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370052\" data-slug=\"torah-or\" data-id=\"3901370052\">תו\"א לך יב, סע\"א</a>. במאמרי אדה\"ז תקס\"ז כאן ע' עג: ”שתרגום פרכת פרסא\" בתו\"א כאן: ”שתרגום יונתן פרכת פרגוד והיינו פרסא\". ראה הנסמן במ\"מ במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שמט. מאמרי אדה\"א שמות ח\"ב ע' שכה. וש\"נ. בבוך 1824 מח, א<sup data-n=\"e38\">ג</sup>: פרסא. . והיינו והבדילה הפרוכת לכם כו' כי תרגום של פרוכת פרסא."],["517","184","<b>הפרסא. . האצי' לבי\"ע</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא."],["518","185","<b>שמש ומגן</b>: תהלים פד, יב. ראה (בנוסף להערה 1) שהיחוה\"א רפ\"ד. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך.\n\n<b>ג</b>  הנדפס במאמרי אדה\"ז על פרשיות התורה כאן הוא כנראה קיצור מההנחה שנעתקה בבוך זה."]]],[2000470138,"השמש<sup data-n=\"519\">186</sup>, ובדרז\"ל מוציא הקב\"ה חמה מנרתיקה<sup data-n=\"520\">187</sup>, שהוא הסתר דש' אלקי' המעלים על אור ה' וקדושתו והבהקת אורו בריבוי לגבי הנבראים דבי\"ע, וכנודע שבכדי שיהי' מציאות ההתהוות דבי\"ע זהו ע\"י ש' אלקי'<sup data-n=\"521\">188</sup> כו', ולכן בכדי להעלות נש\"י דבי\"ע לאצי' שהוא למעלה מן הפרסא דשם אלקי', זהו ע\"י השושבין אהרן כהנא רבא, שמעריך את הנרות ומעלה אותם כו'. ואמנם עדיין צ\"ל הלא נהוג עלמא שהשושבין הוא רק בעת החתונה לבד, משא\"כ אח\"כ אינם צריכים לשושבין כלל וכלל, ובענין הערכת &lt;14&gt;\nּ והעלאת הנרות זהו בכ\"י תמיד, אשר לכאו' אינו מובן כלל מ\"ע השושבין בכי\"ת כל בין הערבים, אך הענין הוא דהנה ענין החתונה הוא להיותה דבר חדש לזווג חו\"כ הבלתי מכירים זא\"ז כלל ואשר היו נפרדים ורחוקים זמ\"ז מאז נולדו, ומקרבים אותם<sup data-n=\"522\">189</sup>, בכדי שיולידו בנים שז\"ע המשכת או\"ח ממש כו' לזה צריכים שושבין דוקא, ומזה נמשך שמחה נפלאה על בחי' האו\"ח כו', ועד\"ז יובן שבכל בין הערבים יש בחי' התחדשות בירורי' שנתחדשו ע\"י העבודה ביום שעבר, מרפ\"ח ניצוצין<sup data-n=\"523\">190</sup> שנפלו, וזהו דכתי' ותקם כו' ותתן טרף<sup data-n=\"524\">191</sup>, טרף הוא רפ\"ח עם הכולל<sup data-n=\"525\">192</sup> שז\"ע בחי' הבירורי' והניצוצים שעולים ע\"י בחי' הבירורים, והניצוץ כשעולה ה\"ז דבר חדש, והיינו כמו שני אוהבים שלא ראו זא\"ז זמן רב שמתחדש אצלם הקירוב לבבות והאהבה מזל\"ז ביתר שאת ויתר עז ותגדל שמחתם עד למרבה מפני עוצם הקירוב שנעשה אחר הריחוק, ועד\"ז יובן בענין ההעלאת הניצוצות דרפ\"ח ניצוצין שנפרדו מאז הי' שבה\"כ, והיו בעמקי הקלי' וסט\"א, וע\"י התלבשות הנשמה שבעצם טהורה היא<sup data-n=\"526\">193</sup> היינו בלתי שום דבר נוסף על עצמיות אוא\"ס שהיא חלק אלק' ממעל, ולכן נק' טהורה כי ענין הטהרה הוא היותר מנוקה מכל, כמו הבגד טהור שפירושו שנקי הוא מכ\"ד טומאה ומכל לכלוך כו', כמ\"ש מזה בד\"ה גור ארי' יהודה<sup data-n=\"527\">194</sup>, ונשמה הטהורה הלזה ירדה להתלבש בגוף ונה\"ב בכדי",[["519","186","<b>נרתק השמש</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתקב. וש\"נ. בהערה הבאה."],["520","187","<b>מוציא הקב\"ה חמה מנרתיקה</b>: ראה נדרים ח, ב."],["521","188","<b>ההתהוות. . ש' אלקי'</b>: בראשית א, א. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380118\" data-slug=\"likkutei-torah\" data-id=\"4001380118\">לקו\"ת צו י, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380135\" data-slug=\"likkutei-torah\" data-id=\"4001380135\">יד, ד</a>. המשך תער\"ב ח\"א ע' שדמ. ח\"ב ע' תתלא. ע' א'קלב. לקמן מאמר ד\"ה סמכוני באשישות ובהערה 26. המשך מצה זו על יד הערה 1453. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני באשישות על יד הערה 32."],["522","189","<b>החתונה. . ומקרבים אותם</b>: ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת. סה\"מ תרל\"ח ע' תפ ובהערה 68."],["523","190","<b>מרפ\"ח ניצוצין</b>: ראה ע\"ח שער רפ\"ח שי\"ח, פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151537\" data-slug=\"likkutei-sichot\" data-id=\"1300151537\">לקו\"ש וישב כרך טו ע' 524</a> (אג\"ק שלו ח\"ב ע' כא). וש\"נ. מאמרי אדה\"א דברים ח\"ד ע' א'קעד. וש\"נ."],["524","191","<b>ותקם. . טרף</b>: משלי לא, טו."],["525","192","<b>טרף הוא רפ\"ח עם הכולל</b>: ראה פע\"ח שער ק\"ש שעהמ\"ט שט\"ז, פ\"ה. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתקלא. מאמרי אדה\"א בראשית ע' קמו. וש\"נ."],["526","193","<b>הנשמה. . טהורה היא</b>: ברכת אלקי נשמה (מברכות ס, ב). וראה לעיל רפ\"ו. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויהי הענן והחשך ובהערה 22. (בחלק ההנחות) הנחה ד\"ה כמים הפנים פיסקא והענין דהנה. לקמן ח\"ב (בחלק ההנחות) ד\"ה יפה שעה הא' על יד הערה 64."],["527","194","<b>בד\"ה גור ארי' יהודה</b>: מפ' ויחי, נדפס לעיל קודם ההמשך ולפנינו שם ליתא. ואולי הכוונה שבעת אמירת הדרוש נתבאר זה. וראה גם בהערה שלפנ\"ז."]]],[2000470139,"לבררם ולהעלותם עם הניצוצות שנפלו בהם<sup data-n=\"528\">195</sup> בשה\"כ כו', ולזאת בכדי שיעלו ניצוצות אלו זהו ע\"י השושבין, וז\"ע אהרן שושבינא דמט' שהוא הממשיך המשכת אלקות בכדי שיעלו הנרות הם נש\"י בכל בין הערבים, וז\"ע הטבת והעלאת הנרות בכל בה\"ע<sup data-n=\"529\">196</sup> בכי\"ת שהו\"ע העלאת הניצוצות המתבררים בכי\"ת כו'.\n<b></b>קיצור. שאהרן הוא שושדמ\"ט להעלות הנרות דנר ה' נשמת אדם<sup data-n=\"530\">197</sup>, וההעלאה היא מחוץ לפרוכת, מבי\"ע לאצי', ולכאורה השושבין הוא רק בעת החתונה אלא שזהו לפי שבכ\"י מתחדשי' העלאת הניצוצות מרפ\"ח ניצוצין וזהו הטבת הנרות דבין הערבים כו'.",[["528","195","<b>בהם</b>: בהמשך הנדפס: ליתא."],["529","196","<b>הטבת והעלאת. . בה\"ע</b>: רמב\"ם הל' תמידין ומוספים פ\"ג, ה\"י. הל' עבודת יוה\"כ פ\"ב, ה\"ב ובכ\"מ שם."],["530","197","<b>דנר ה' נשמת אדם</b>: משלי כ, כז."]]],[2000470140,"<h3>[ויהי הענן והחשך] והנה השושבין</h3>\n<b>בס\"ד. פ' בשלח</b>\n(יא) <b>והנה</b> השושבין<sup data-n=\"531\">198</sup> הוא מהיכל המלך כמו מי שצריך לכנוס להיכל המלך, ואמנם מפני עוצם מעלת רוממות המלך נופל על הנכנס בחי' יראה בושת שמתבושש מלפני המלך לכנוס בהיכלו, ולזאת צריך הוא לעזר וסעד שיעזור לו ויסעוד אותו לבלי יתגבר עליו הבושה כו', והעזר והסעד הוא שמבקש מי שהוא מקורב אצל המלך ונכנס ויוצא אצל המלך או מי שהוא חשוב כ\"כ עד שהוא אעיל בלי בר<sup data-n=\"532\">199</sup>, ולכן בכחו ויכולתו לעזור ולסעוד גם זולתו כו'. ועד\"ז יובן בענין העלאת הנרות דנר ה' נשמת אדם שלהיות הניצוצות המתעלים נתרחקו מאז נפלו בשבה\"כ, וגם הנשמה עם היות שטהורה היא היינו שאינה דבר נוסף על עצמותו וה\"ה חלק אלקה ממעל, עכ\"ז מאז ירדה &lt;15&gt;\nּ להתלבש בגוף הוכנה תחלה להיות בראת יצרת נפחת שכ\"ז הוא שינוי מהותה לירד במדריגה עד שיתכן לומר עליה בראת שהיא בריאה יש מאין<sup data-n=\"533\">200</sup>, ויצרת ציור חומר הבריאה, ונפחת זהו כדוגמת",[["531","198","<b>והנה השושבין</b>: מאמר זה הוא מאמר הה' מההמשך וכולל פרקים יא-יג.\nדרוש זה מיוסד על מאמר ד\"ה הנה ענין מחוץ לפרכת שנדפס במאמרי אדה\"ז על פרשיות התורה ח\"א ע' שנא ואילך. והנחה אחרת ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370489\" data-slug=\"torah-or\" data-id=\"3901370489\">תו\"א תצוה קי, א</a>. וראה הנסמן לעיל בריש ההמשך. הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה נדפסה לקמן (בחלק הנחותיו) ושם הפתיחה: ויהי הענן והחשך<sup data-n=\"e39\">א</sup>."],["532","199","<b>אעיל בלי בר</b>: ראה סוכה מה, ב."],["533","200","<b>בראת שהיא בריאה יש מאין</b>: ראה גם לעיל פ\"ו.\n\n<b>א</b>  ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470141,"העשייה שהוא עוד מרוחק יותר, וכנודע מענין אף עשיתיו, אף הפסיק<sup data-n=\"534\">201</sup> כו', ולכן כשעולה לעמוד לפני המלך מש\"ע<sup data-n=\"535\">202</sup>, ה\"ה בוש מעוצם מעלת רוממות כבודו כו', ולהיותה בעצם חלק אלקה ממעל, וטהורה היא כנ\"ל<sup data-n=\"536\">203</sup> שמנוקה מכל דבר המסתיר לזאת ה\"ה משגת יותר את גודל עוצם מעלת המלך מש\"ע, כמו מי שהוא בר שכל יותר גדול ה\"ה מבין מעלת בחי' רוממות וגדולת המלך יותר משפל אישים שהשגתו נמוכה בעצם כו', וא\"כ בושה של הנשמה גדלה מאד מאד מפני רוממות עצמותו ית' מצד עצמה וכ\"ש מצד בחי' הבירורים שהבושה עוד גדולה יותר ויותר מפני הריחוק כו', ולכן צריכה עזר וסעד לעוזרה ולסעדה שתוכל להתעלות, וזהו ע\"י אהרן כה\"ג שהוא בעצם מאצי' אלא שירד לבריאה בכדי להעלות נש\"י, ומ\"מ גם בהיותו למטה נא' עליו ואהרן מה הוא<sup data-n=\"537\">204</sup> שגם למטה בהיותו בגוף הי' בחי' מה שזהו בחי' ביטול במציאות כמ\"ש באצי' דאיהו וחיוהי חד, וכמ\"ש בת\"ז שם מ\"ה דאיהו אורח האצי'<sup data-n=\"538\">205</sup>, וא\"כ גם בהיותו למטה ה\"ה מהיכל המלך ולכן יכול הוא לעזר ולסעוד את נש\"י להעלותם כו', וע\"פ הקבלה אהרן הוא בחי' נצח דאבא<sup data-n=\"539\">206</sup>, וירד לבי\"ע לנצח העלי' דנש\"י, ועי\"ז נמשך בחי' השמחה מבחי' ה\"ג דאימא<sup data-n=\"540\">207</sup> כמ\"ש אם הבנים שמחה<sup data-n=\"541\">208</sup>, ואו\"א הם תרין ריעין<sup data-n=\"542\">209</sup> דלא מתפרשין וז\"ע אורה ושמחה<sup data-n=\"543\">210</sup>, ובעבודה זהו בחי' שמחה של מצוה אשר קדשנו במצותיו שע\"י בחי' מצותיו נמשך בחי' אשר שהוא תענוג<sup data-n=\"544\">211</sup> עליון, כמ\"ש בכ\"ד והוא מלשון מ\"ש באשר כי אשרוני בנות<sup data-n=\"545\">212</sup> כו',",[["534","201","<b>אף עשיתיו אף הפסיק</b>: ישעי' מג, ז. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380586\" data-slug=\"likkutei-torah\" data-id=\"4001380586\">לקו\"ת בלק סז, סע\"א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540181\" data-slug=\"torat-chaim\" data-id=\"2300540181\">תו\"ח בשלח ח\"א קמד, ג</a>. וש\"נ."],["535","202","<b>המלך מש\"ע </b>[ מלכו של עולם]: ע\"פ מגילה טו, ב. טז, סע\"א."],["536","203","<b>כנ\"ל</b>: ספ\"י ובהנסמן שם."],["537","204","<b>ואהרן מה הוא</b>: קרח טז, יא."],["538","205","<b>שם מ\"ה דאיהו אורח האצי'</b>: ראה ת\"ז בהקדמה יז, א. הדרת מלך שם ע' קיב. סידור אדה\"ז סדר מנחת ערב שבת (פתח אלי')."],["539","206","<b>אהרן. . נצח דאבא</b>: ראה (בנוסף להערה 1) לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ד\"ה ויהי הענן והחשך על יד הערה 43. מכתב ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש ח\"ו ע' 244</a>. מכתב א' טבת תשי\"ט באג\"ק שלו חי\"ח ע' קיז. מאמרי אדה\"ז תקס\"ב ח\"ב ע' תנט. תקס\"ג ח\"א ע' קלה ואילך. תקס\"ו ע' רמג. תקס\"ח ח\"א ע' שסה. ביאוה\"ז קרח צד, ג. סה\"מ תרל\"ה ח\"ב ע' שלב. וש\"נ. ס' הערכים חב\"ד ח\"ב מערכת אהרן ע' ח. וש\"נ."],["540","207","<b>השמחה מבחי' ה\"ג דאימא</b>: ראה אוה\"ת תצוה כאן ע' ג'סב שמציין (ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370172\" data-slug=\"torah-or\" data-id=\"3901370172\">תו\"א מקץ לז, ד</a>): דשמחה הוא חסדי' דאימא."],["541","208","<b>אם הבנים שמחה</b>: תהלים קיג, ט. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381043\" data-slug=\"likkutei-torah\" data-id=\"4001381043\">לקו\"ת</a> שמ\"ע פח, ד<sup data-n=\"e40\">ב</sup>. סוכות עט, ד. לקמן המשך מצה זו פל\"ח. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 48. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ושאבתם מים על יד הערה 42. ובהנחה שם על יד הערה 55. מאמרי אדה\"א נ\"ך ע' מח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540915\" data-slug=\"torat-chaim\" data-id=\"2300540915\">תו\"ח וארא ח\"א פה, ג</a>."],["542","209","<b>ואו\"א הם תרין ריעין</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670185\" data-slug=\"torat-chaim\" data-id=\"2300670185\">תו\"ח בראשית כא, ב</a> ובהערה 8."],["543","210","<b>אורה ושמחה</b>: אסתר ח, טז. ראה (בנוסף להערה 1) מאמרי אדה\"ז תקס\"ו ע' רמג."],["544","211","<b>אשר קדשנו במצותיו. . תענוג</b>: נוסח ברכת המצות. ראה תו\"א יתרו ע, ריש ע\"ב [נעתק לקמן המשך מצה זו פכ\"ב על יד הערה 687]. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380045\" data-slug=\"likkutei-torah\" data-id=\"4001380045\">לקו\"ת בשלח א, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380447\" data-slug=\"likkutei-torah\" data-id=\"4001380447\">בהעלותך לד, ב</a>."],["545","212","<b>אשר. . באשר </b>[בהמשך הנדפס: באשרי]<b> כי אשרוני בנות</b>: ויצא ל, יג. ראה ת\"ז ת\"ל (עד, ב). תל\"ט (עט, א). <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550424\" data-slug=\"torat-chaim\" data-id=\"2300550424\">תו\"ח יתרו ח\"ב רסז, ג</a>. וש\"נ. לקמן שם על יד הערה 688. ובהנחה כאן על יד הערה 52.\n\n<b>ב</b>  <b>ושם מציין </b>: בזח\"ב פ' יתרו (דפ\"ד ע\"א ודפ\"ה ע\"ב) ובפ' ויחי (דרי\"ט ע\"א) ובשאר דוכתי."]]],[2000470142,"ועבודה בשמחה היא מרוב כל<sup data-n=\"546\">213</sup>, כל הוא בחי' צדיק יסוד<sup data-n=\"547\">214</sup> עולם<sup data-n=\"548\">215</sup> כמ\"ש התרגום דאחיד<sup data-n=\"549\">216</sup> בשמיא ובארעא, והוא בחי' המשכה בבי\"ע שזהו ע\"י בחי' כל, והוא בחי' ההשפעה מלמעלמ\"ט בכדי שיהי' מלמטלמ\"ע בחי' ההעלאות מבי\"ע ונודע כי כל השפעה<sup data-n=\"550\">217</sup> אינו כמו שהוא בעצם שהמשפיע מוכרח לצמצם בכדי שיוכל להשפיע, וגם השפעתו הוא רק הארה מעצמותו, כמ\"ש מזה במ\"א באריכות, משא\"כ הע\"ס המשפיעים ע\"י היסוד כמו שהם באצי' דאיהו וחיוהי חד נא' לך ה' הגדולה<sup data-n=\"551\">218</sup> שלך הוא ג\"כ אותיות כל אלא שלך רומז על בחי' הביטול והדיבוק בו ית' בבחי' ביטול אמיתי בחי' מ\"ה בעצם כו' ולכן עבודה בשמחה גדול מבחי' רוב כל.\n<b>וביאור</b> הענין דהנה המצוה עצמה שרשה גבוה מאד מעלה מעלה, והוא מבחי' גלגלתא דא\"א, בחי' הלבנוניות שבין השערות, וז\"ע תרי\"ג ארחין דגלגלתא<sup data-n=\"552\">219</sup> שנת' בזהר בכ\"ד, שהם בחי' הלבנוניות שבין השערות, בהיות ידוע שהתורה נמשלה לשערות<sup data-n=\"553\">220</sup>, וכמ\"ש סלסלה ותרוממך<sup data-n=\"554\">221</sup> שע\"י סלסול השערות שהוא בחי' הפרדת השערות שלא יהיו אחוזים ודבוקי' ומבולבלי' זל\"ז, והיינו בחי' הפרדת הלכות שבתורה &lt;16&gt;\nּ שלא יהי' סותר מזה לזה עי\"ז מתרומם נפש האדם, שנמצא התורה היא<sup data-n=\"555\">222</sup> בחי' שערות, והשערות הם חלולים<sup data-n=\"556\">223</sup> שבתוך וחלל השערה היא הארת בחי' המוחין הוא אור ההשכלה כו', והרי הם כמו צירופי אותיות שבהם וע\"י מובן השכל, כמו כשלומד איזה תוס' הנה ע\"י הדיבור שמדבר באותיות ודברי התוס' עי\"ז מבין את אור ההשכלה המלובש בהם, שיציאת<sup data-n=\"557\">224</sup> אור השכל מן האותיות הוא כמו יציאת אור ההשכלה מן חלל השערה כו', שההארה יוצא מן דרך השערות החלולי' ואמנם מי הוא הנושא וסובל את השערות עם החללים שבהם זהו בחי' הלובן דגלגלתא כו' והיינו להיות כי כל התורה היא פי' וביאור המצות<sup data-n=\"558\">225</sup> ועשית",[["546","213","<b>ועבודה. . מרוב כל</b>: תבוא כח, מז. ראה גם הנסמן במאמרי אדה\"ז על פרשיות התורה כאן."],["547","214","<b>כל. . יסוד</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ה. פע\"ח שער הסוכות שכ\"ח, פ\"ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540129\" data-slug=\"torat-chaim\" data-id=\"2300540129\">תו\"ח וארא ח\"א נג, ד</a>. וש\"נ."],["548","215","<b>צדיק יסוד עולם</b>: ע\"פ משלי י, כה."],["549","216","<b>כמ\"ש התרגום דאחיד</b>: ראה זהר בראשית לא, א. ראה גם סה\"מ תרל\"ח ע' עט. וש\"נ."],["550","217","<b>כל השפעה</b>: ראה אגה\"ק סט\"ו. סי\"ט. סידור שחרית נ, ג. תו\"ח ח\"ש קכב, א ובהערה 10."],["551","218","<b>לך הוי' הגדולה</b>: דבהי\"א כט, יא. ראה גם אוה\"ת תצוה כאן ע' ג'קה."],["552","219","<b>המצוה. . תרי\"ג ארחין דגלגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א. (בנוסף להערה 1) אגה\"ק ס\"כ (קלא, א). קו\"א לתניא ד\"ה להבין מ\"ש בפע\"ח. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380803\" data-slug=\"likkutei-torah\" data-id=\"4001380803\">לקו\"ת פ' ראה כא, ד</a>. מאמרי אדה\"ז הנחות הר\"פ ע' קמד ואילך. אוה\"ת מג\"א [מהדורת תש\"נ] ע' צו ואילך. שבועות ע' קסו. לקמן פכ\"ג. וראה גם תו\"א לך יא, ג<sup data-n=\"e41\">ג</sup>. מג\"א צא, סע\"ב ואילך."],["553","220","<b>שהתורה נמשלה לשערות</b>: ראה גם ערה\"כ לבעל סדה\"ד מערכת שערות."],["554","221","<b>סלסלה ותרוממך</b>: משלי ד, ח. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370148\" data-slug=\"torah-or\" data-id=\"3901370148\">תו\"א מקץ לא, ד</a>. מאמרי אדה\"ז כתובים ח\"ב ע' צא וע' ק ואילך. מאמרי אדה\"א ויקרא ח\"א ע' קז. וש\"נ. קונטרסים ע' תקמג. וש\"נ. לקמן מאמר ד\"ה סמכוני באשישות על יד הערה 36 ואילך. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 64. המשך תרס\"ו ע' תט ואילך."],["555","222","<b>היא</b>: בהמשך הנדפס: ליתא."],["556","223","<b>והשערות הם חלולים</b>: ראה נזיר לט, א."],["557","224","<b>שיציאת</b>: בהמשך הנדפס: שמציאת."],["558","225","<b>התורה היא </b>[בהמשך הנדפס: הוא]<b> פי' וביאור המצות</b>: ראה (בנוסף להערה 1) הדרושים שבהערה 219.\n\n<b>ג</b>  נעתק לקמן בהמשך מצה זו פכ\"ד על יד הערה 715."]]],[2000470143,"חושן ואפוד<sup data-n=\"559\">226</sup> ותמונתו ושתי טבעות זהב<sup data-n=\"560\">227</sup> כו' וכדומה בכל פרטי המצות, א\"כ הנושא וסובלן הוא הלבנוניות שבגלגלתא שז\"ע המצות בחי' תרי\"ג ארחין דגלגלתא שעצם לובן שבגלגלתא א\"א לבוא לידי גילוי עכשיו בעוה\"ז כ\"א שע\"י פי' וביאור התורה מתגלה מן המצוה כמו י\"ב לחמים שבשבת<sup data-n=\"561\">228</sup> שהוא בחי' התגלות ע\"ק, משא\"כ עצם המצוה וכמארז\"ל שכר מצוה בהאי עלמא ליכא<sup data-n=\"562\">229</sup>, כי שכר מצוה היא המצוה עצמה<sup data-n=\"563\">230</sup> שזה א\"א לבוא בהתגלות עכשיו כ\"א לע\"ל, רק בחי' שמחה של מצוה הוא המתגלה גם עכשיו ע\"י אהרן כהנא רבא בחי' שושבינא דמטרוניתא שהוא מז' רועים<sup data-n=\"564\">231</sup> המפרנסי' נש\"י בחי' שמחה של מצוה כו'.\n<b></b>קיצור. השושבין הוא מהיכל המלך, כי מפני רוממות המלך נופל פחד עצום צריכי' לשושבין שיהי' לעזר וסעד, והוא אהרן נצח דאבא ועי\"ז נמשך שמחה ש\"מ כי המצוה שרשה גבוה לבנוניות שבגלגלתא, וא\"א להיות נמשך בעוה\"ז כ\"א הארה וזהו שש\"מ כו'.\n(יב) <b>והנה</b> ענין הרועה הרועה צאן במרעה טוב, אין פירושו שנותן משל עצמו כ\"א הוא הוא הבוחר עשבים טובים למרעה, אבל עצם העשבים הם של בעל הצאן כו', ועד\"ז יובן דכתי' ונתתי עשב בשדך לבהמתך<sup data-n=\"565\">232</sup>, שהעשב הוא מן שדך, ועכ\"ז הרועה הוא הנותן. והענין הוא דהנה עשב הוא בחי' המשכת הדעת<sup data-n=\"566\">233</sup> בנשמות דזרע בהמה<sup data-n=\"567\">234</sup>, והיינו נשמות דבי\"ע, והוא כי עשב הוא ע\"ב דחכ' ושין הם ג' מדות<sup data-n=\"568\">235</sup>, ולכן נק' המשכת הדעת כי הדעת מזווג חו\"ב<sup data-n=\"569\">236</sup>, ואמנם הנה המשכה זו זהו ע\"י אמירת קדוש שאומרים המלאכים ונשמות כמ\"ש מזה בת\"א בד\"ה ואלה",[["559","226","<b>ועשית </b>[בהמשך הנדפס: ועשיית, אבל במאמרי אדה\"ז כאן כבפנים]<b> חושן ואפוד</b>: תצוה כח, ד. טו ואילך. שם, ו ואילך."],["560","227","<b>ושתי טבעות זהב</b>: תצוה שם, כג ואילך. הלשון — שם ל, ד. ועוד."],["561","228","<b>י\"ב לחמים שבשבת</b>: ראה רע\"מ פינחס רמה, א. ת\"ז תמ\"ז פד, סע\"א. ז\"ח אחרי מח, ד. שער הכוונות ענין השלחן. פע\"ח שער השבת שי\"ח, פי\"ז. (בנוסף להערה 1) תו\"א ח\"ש טו, ג ואילך. סידור סדר סעודת שבת רג, ד ואילך. מאמרי אדה\"ז על מארז\"ל ע' רסה. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316520298\" data-slug=\"or-hatorah-hb\" data-id=\"8316520298\">אוה\"ת בשלח ס\"ע תרמא</a> ואילך."],["562","229","<b>שכר מצוה בהאי עלמא ליכא</b>: קדושין לט, ב. ראה מאמרי אדה\"א שמות ח\"ב ע' שטז. וש\"נ. קונטרסים ע' שיא ואילך. סה\"מ תרל\"ח ע' לב ואילך."],["563","230","<b>שכר מצוה היא המצוה עצמה</b>: אבות פ\"ד, מ\"ב. ראה תניא רפל\"ז. מאמרי אדה\"א דברים ח\"ג ע' תתצט. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540633\" data-slug=\"torat-chaim\" data-id=\"2300540633\">תו\"ח שמות ח\"א ז, ב</a>. וש\"נ. סה\"מ תרכ\"ט ע' כא. וש\"נ."],["564","231","<b>אהרן. . שהוא מז' רועים</b>: ראה תיקונים לז\"ח קד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201655\" data-slug=\"likkutei-sichot\" data-id=\"1300201655\">לקו\"ש חנוכה כרך כ ע' 643</a>. בהעלותך כרך לח ע' 193."],["565","232","<b>ונתתי עשב בשדך לבהמתך</b>: עקב יא, טו."],["566","233","<b>עשב. . הדעת</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370335\" data-slug=\"torah-or\" data-id=\"3901370335\">תו\"א משפטים עה, ב</a> — מובא בסמוך בפנים."],["567","234","<b>בנשמות דזרע בהמה</b>: תו\"א שם עד, ג ואילך. ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 29."],["568","235","<b>עשב הוא ע\"ב דחכ' ושין הם ג' מדות</b>: ראה גם תו\"א שם עה, ב. מאמרי אדה\"א דברים ח\"ג ע' תתקיד. וש\"נ. אוה\"ת משפטים ע' א'קיד."],["569","236","<b>הדעת מזווג חו\"ב</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380055\" data-slug=\"likkutei-torah\" data-id=\"4001380055\">לקו\"ת</a> להאריז\"ל שמות ג, ד. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370334\" data-slug=\"torah-or\" data-id=\"3901370334\">תו\"א שם עה, א</a>. ב."]]],[2000470144,"המשפטים<sup data-n=\"570\">237</sup>, א\"כ זהו בשדך, שדה הוא בחי' חקל תפוחין קדישין<sup data-n=\"571\">238</sup> שע\"י הוא ההעלאה כמ\"ש בזאת יבא אהרן<sup data-n=\"572\">239</sup>, וגם ההמשכה נמשך ע\"י שדה זו עצמה, והרועה הוא הנוטל את העשב המשכת החכ' ע\"י הדעת הנמשך בשדה דחקל תפוחין קדישין ונותן להבהמה כו'.\n&lt;17&gt;\nּ <b>ועפ\"ז</b> יובן שם אהרן שהוא אלף הר נו\"ן פשוטה, והיינו כי הר<sup data-n=\"573\">240</sup> הוא בחי' אהבה, ויש הר ויש הר ההר, שהם בחי' אהבת עולם ואה\"ר ואהרן נקבר בהר ההר<sup data-n=\"574\">241</sup> שהמשיך גם בחי' אה\"ר בנשמות דבי\"ע, אך אין זה שלו עצמו כ\"א שנטל זה מאלף הוא בחי' אאלפך חכ'<sup data-n=\"575\">242</sup> או בחי' הלבנוניות הנ\"ל וממשיך בנו\"ן פשוטה שרומז על בחי' אדם כמ\"ש במ\"א בתיבת שנא\"ן<sup data-n=\"576\">243</sup> שהם ר\"ת שור נשר ארי' והנו\"ן פשוטה זהו בחי' אדם והיינו בחי' אדם דבי\"ע וע\"ז רומז פשיטותה שנמשך בעשי' כמו בבריאה כו', ומ\"מ העשב זה עצמו זהו מן מה שמעלה מנש\"י דבי\"ע וכנ\"ל בענין מחוץ לפרוכת יערוך אותו אהרן כו', שהוא מה שאהרן מעלה נרות דנר ה' נשמת אדם שיאמרו קדוש כו' ואז יומשך העשב בשדך, וכמשל השדה קודם צמיחתה אין בה עשבים, וצמיחת העשבים ז\"ע נתינת העשב כו'.\n<b></b>קיצור. שהרועה נותן העשב להבהמה<sup data-n=\"577\">244</sup> אך אין זה שלו, וזהו אהרן אלף הר נו\"ן פשוטה כו'.\n(יג) <b>ואמנם</b> הנרות הם משמן זית<sup data-n=\"578\">245</sup>, אשר מצינו לרז\"ל שאמרו על שמן זית כשם שהזית<sup data-n=\"579\">246</sup> משכח תלמודו של ע' שנה כך שמן זית מחזיר תלמודו של ע' שנה, והענין הוא כי הזית עצמו הוא מנוגה בחי' משכא דחויא<sup data-n=\"580\">247</sup> עולם השכחה והשקר, שהוא מקלי' וסט\"א, ולכן פעולתו ג\"כ לשכח ולשקר, והיינו הגם כי למד ויודע את הענין שלמד עכ\"ז ישכח מה שלמד וישקר באיש האוכלו שמה שידע זהו שקר שהרי כשמשכח ה\"ה שקר שיודע שהרי אינו יודע כו', אך מן הזית הזה מוציאין שמן כתית למאור<sup data-n=\"581\">248</sup>, והו\"ע הבלא דגרמא<sup data-n=\"582\">249</sup> שיש בכל דבר, ולהיות כי",[["570","237","<b>אמירת קדוש. . בת\"א בד\"ה ואלה המשפטים</b>: עה, ב."],["571","238","<b>שדה. . חקל תפוחין קדישין</b>: ראה זהר ויחי רכד, ב."],["572","239","<b>בזאת יבא אהרן</b>: אחרי טז, ג."],["573","240","<b>הר. . בהר ההר</b>: ראה (בנוסף להערה 1) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380392\" data-slug=\"likkutei-torah\" data-id=\"4001380392\">לקו\"ת נשא כא, א</a>. מאמרי אדה\"ז תקס\"ג ח\"א ע' קכו ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540562\" data-slug=\"torat-chaim\" data-id=\"2300540562\">תו\"ח וארא ח\"א עז, ג</a> ואילך."],["574","241","<b>ואהרן נקבר בהר ההר</b>: חוקת כ, כח."],["575","242","<b>אאלפך חכ'</b>: איוב לג, לג [ושם: ואאלפך]."],["576","243","<b>שנא\"ן</b>: תהלים סח, יח. זהר בראשית יח, סע\"ב. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370319\" data-slug=\"torah-or\" data-id=\"3901370319\">תו\"א יתרו עא, סע\"ד</a> ובהנסמן במ\"מ לשם."],["577","244","<b>העשב להבהמה</b>: בהמשך הנדפס: את העשב לבהמה."],["578","245","<b>הנרות הם משמן זית</b>: ר\"פ תצוה. אמור כד, ב."],["579","246","<b>כשם שהזית</b>: ראה הוריות יג, ב (כגי' הע\"י)."],["580","247","<b>משכא דחויא</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א (מ, ב</a>) ובמ\"מ הגהות והע\"ק שם. ס' שיעורים בספר ה<a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא כאן (פמ\"ה</a>) ע' 613 הערה 3. הנסמן באוה\"ת חוקת כרך ו ע' א'תתצג מאמרי אדה\"א נ\"ך ע' תלד."],["581","248","<b>שמן כתית למאור</b>: ר\"פ תצוה אמור כד, ב [בדילוג]."],["582","249","<b>הבלא דגרמא</b>: ראה זהר שלח קסט, א. קע, א. ע\"ח שער מוחין דקטנות שכ\"ב, פ\"ב. מבו\"ש ש\"ב ח\"ב, פ\"ט. (בנוסף להערה 1) מאמרי אדה\"א בראשית ע' תקכא. וש\"נ. שמות ח\"א ע' ד."]]],[2000470145,"שמן יש בכל דבר<sup data-n=\"583\">250</sup> כנודע לכן גם בעצמות היבישות באנשי' שכבר מתו זמן רב פועלים שלא ירקבו העצמות לגמרי עד התחי' שיהי' בזמן תה\"מ והיא עצם לוז<sup data-n=\"584\">251</sup> הנשארת בלתי מרוקבת גם בכל העצמות יש איזהו רושם מהם, וזהו ג\"כ בחי' הבלא דגרמי' המקיימת וכמ\"ש ונפשו עליו תאבל<sup data-n=\"585\">252</sup>, והיינו כי הבלא דגרמי' זה הוא<sup data-n=\"586\">253</sup> מרפ\"ח ניצוצין שהם מד' שמות ע\"ב ס\"ג מ\"ה ב\"ן<sup data-n=\"587\">254</sup>, והיינו ב\"ן שבהם, שרפ\"ח ניצוצין הם הנשארים בכלים אחר שבירתן להחיותן כו'.\n<b>ושרש</b> הענין הוא דהנה השבירה היתה ממה שהי' מעולם התהו<sup data-n=\"588\">255</sup> לפני מלך מלך<sup data-n=\"589\">256</sup> כו', רק שאח\"כ ירדו ומתו וכמ\"ש וימלוך וימת<sup data-n=\"590\">257</sup>, והתחלת השבירה היתה וימת בלע<sup data-n=\"591\">258</sup>, שהוא מהדעת<sup data-n=\"592\">259</sup> ולמטה, אבל למעלה בחו\"ב לא היתה שבירה<sup data-n=\"593\">260</sup> כלל כמ\"ש ימותו ולא בחכמה<sup data-n=\"594\">261</sup>, כי החכמה תחי'<sup data-n=\"595\">262</sup> כו', והנה גם מהדעת ולמטה יש ג\"כ חכמה והיינו בחי' חכ' דז\"א, שהוא חכ' שבחסד וחכ' שבגבורה, ועד\"ז בכולן זהו<sup data-n=\"596\">263</sup> חיות הכלים הנשברים, והם הרפ\"ח ניצוצין שהם מבחי' השמות שהם חיות הכלים וזהו שיכולים להוציא &lt;18&gt;\nּ שמן מכל הדברים כנודע בחכמת הרפואה<sup data-n=\"597\">266</sup> ואפי' מאבנים<sup data-n=\"598\">264</sup>, וכמ\"ש בפרד\"ס<sup data-n=\"599\">267</sup> מהרמ\"ק ז\"ל<sup data-n=\"600\">265</sup>, והיינו לפי שהשמן הוא החכ', ולכן מחזיר<sup data-n=\"601\">268</sup> תלמודו כי החכ' הוא מוח הזכרון<sup data-n=\"602\">269</sup>, ולכן בפ' קדש",[["583","250","<b>שמן יש בכל דבר</b>: ראה להלן הערה 264."],["584","251","<b>עצם לוז</b>: ראה ב\"ר פכ\"ח, ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670474\" data-slug=\"torat-chaim\" data-id=\"2300670474\">תו\"ח נח נה, א</a> ובהערה 1. מאמרי אדה\"א הנחות תקע\"ז ע' ריח. וש\"נ."],["585","252","<b>ונפשו עליו תאבל</b>: איוב יד, כב."],["586","253","<b>זה הוא</b>: בהמשך הנדפס: זהו."],["587","254","<b>מרפ\"ח ניצוצין. . ב\"ן</b>: ראה ע\"ח שער רפ\"ח שי\"ח, פ\"ב. שער אנ\"ך שי\"ט, פ\"א. מבו\"ש ש\"ב ח\"ב, פ\"י. פי\"א. (בנוסף להערה 1) מאמרי אדה\"ז תקס\"ה ח\"א ע' רי. ח\"ב ע' תרמב. מאמרי אדה\"א במדבר ח\"ב ע' תשפה ואילך."],["588","255","<b>השבירה. . מעולם התהו</b>: ראה ע\"ח שער הכללים פ\"א. שער דרושי נקודות ש\"ח, פ\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670078\" data-slug=\"torat-chaim\" data-id=\"2300670078\">תו\"ח נח סד, ב</a> הערה 10. לקמן פי\"ט."],["589","256","<b>לפני מלך מלך</b>: וישלח לו, לא."],["590","257","<b>וימלוך וימת</b>: שם לו, לב [בדילוג] ואילך."],["591","258","<b>וימת בלע</b>: וישלח שם, לג."],["592","259","<b>בלע שהוא מהדעת</b>: ראה ע\"ח שער הכללים פ\"א. שער דרושי נקודות ש\"ח, פ\"ד. (בנוסף להערה 1) <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540524\" data-slug=\"torat-chaim\" data-id=\"2300540524\">תו\"ח שמות ח\"א מב, ב</a>. וש\"נ."],["593","260","<b>בחו\"ב לא היתה שבירה</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. מאמרי אדה\"א דברים ח\"א ע' ט. וש\"נ."],["594","261","<b>ימותו ולא בחכמה</b>: איוב ד, כא. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' רצט. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אל יתהלל על יד הערה 15."],["595","262","<b>החכמה תחי'</b>: קהלת ז, יב."],["596","263","<b>זהו</b>: בהמשך הנדפס: וזה."],["597","266","<b>בחכמת הרפואה</b>: וכן מובא בשם חכמי המחקר ס' חקירה ס' הטבע — ראה ש\"א לט, ב הערה 16."],["598","264","<b>שמן מכל הדברים. . מאבנים</b>: והוא הנקרא א ל ים <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380480\" data-slug=\"likkutei-torah\" data-id=\"4001380480\">לקו\"ת שלח מב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380469\" data-slug=\"likkutei-torah\" data-id=\"4001380469\">ראה ש\"א לט, ב</a> הערה 20. באמ\"ב שער הק\"ש נב, ד: לבד ממשקין כיין ומים."],["599","267","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["600","265","<b>שמן מכל הדברים. . בפרד\"ס מהרמ\"ק ז\"ל</b>: כ\"ה בכ\"מ — ראה גם ראשית חכמה שער האהבה ספ\"ה (סו, ד) בשם מורי. ראה (בנוסף להערה 1) מאמרי אדה\"א בראשית ע' רנב. וש\"נ."],["601","268","<b>מחזיר</b>: בהמשך הנדפס: יחזור."],["602","269","<b>החכ' הוא מוח הזכרון</b>: ראה (בנוסף להערה 1) לקמן המשך מצה זו פ\"ג (ובהנחה שם). מאמרי אדה\"ז כאן ע' שנב. וש\"נ. מאמרי אדה\"א שמות ח\"ב ע' תקמא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540083\" data-slug=\"torat-chaim\" data-id=\"2300540083\">תו\"ח שמות ח\"א כג, ד</a>. וש\"נ."]]],[2000470146,"שהיא חכ'<sup data-n=\"603\">270</sup> כנודע נא' בה ולזכרון בין עיניך<sup data-n=\"604\">271</sup>, ובחי' השמן הזה הוא נכלל ובטל באין שנמשך אחר הפתילה, וממנו עיקר האור, כי מראה האור הוא לפי השמן, אם הוא עכור אזי האור אינו מבהיק כ\"כ<sup data-n=\"605\">272</sup>, ואם הוא צלול אזי יש בהאור בהיקות יותר כו', וגם השמן כולו נשרף ואינו נשאר ממנו<sup data-n=\"606\">273</sup> מאומה כלל וכלל, כי צ\"ל דבר שבטל לאין כי יש מיש א\"א להתהוות<sup data-n=\"607\">274</sup> כו', ועיקר בחי' הביטול הוא בחכ', שזהו שם חכמה כח מ\"ה<sup data-n=\"608\">275</sup> ונק' אחד האמת כמ\"ש בסש\"ב פל\"ה בהג\"ה בשם הה\"מ נ\"ע, והגם שאהרן הוא הממשיך אוא\"ס בחי' אורה ושמחה כנ\"ל, מ\"מ אין אוא\"ס שורה אלא במי שבטל<sup data-n=\"609\">276</sup>, והיינו בחי' חכמה שנכלל באין כו', ולכן הוצרך להביא שמן זית זה להעלות בהם את הנרות.\n<b></b>קיצור. שמן זית מחזיר תלמודו, כי מה שהזית משכח זהו להיותו מנוגה עולם השכחה ומהבלא דגרמי' שבו יוצא השמן והוא מרפ\"ח ניצוצין אשר מתבררי' ועולים כו', ושרש הענין שהשבירה הי' מדעת ולמטה, והשמן הוא חכ', ויש חכ' שבחסד כו', ולכן שמן מחזיר להיותו מוח הזכרון וגם בטל לאין אשר בו יכול להיות השראת אוא\"ס אורה ושמחה כו'.",[["603","270","<b>בפ' קדש שהיא חכ'</b>: בא יג, א ואילך. ראה זהר ואתחנן רסב, א."],["604","271","<b>ולזכרון בין עיניך</b>: בא יג, ט."],["605","272","<b>כ\"כ</b>: בהמשך הנדפס: ליתא."],["606","273","<b>ממנו</b>: בהמשך הנדפס: ליתא."],["607","274","<b><a class=\"ft-cite\" href=\"#/read/torah-or/3901370028\" data-slug=\"torah-or\" data-id=\"3901370028\">יש מיש א</a>\"א להתהוות</b>: ראה (בנוסף להערה 1) תו\"א בראשית ז, ג. מאמרי אדה\"א נ\"ך ע' לח. וש\"נ. סה\"מ תרכ\"ז ע' ת. וש\"נ."],["608","275","<b>חכמה כח מ\"ה</b>: זהר רע\"מ צו כח, א. לד, א. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים ובהערה 39. ד\"ה וירא העם וינועו על יד הערה 66."],["609","276","<b>אין אוא\"ס שורה אלא במי שבטל</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא פ\"ו</a>."]]],[2000470147,"<h3>[מזבח אדמה] ויובן עוד כו' זית רענן</h3>\n<b>פ' יתרו</b>\n(יד) <b>ויובן</b> עוד<sup data-n=\"610\">277</sup> ענין מעלת שמן זית דוקא ע\"פ מארז\"ל במד\"ר ר\"פ תצוה<sup data-n=\"611\">278</sup> ע\"פ (ירמי' י\"ח<sup data-n=\"612\">279</sup> ) זית רענן יפה פרי תואר קרא ה' שמך וכי לא נקראו",[["610","277","<b>ויובן עוד כו' זית רענן</b>: מאמר זה הוא מאמר הו' מההמשך וכולל פרקים יד-טז.\nמאמר זה מיוסד על מאמר ד\"ה וידבר וגו' וארא וגו' שנדפס באוה\"ת וארא כרך ז ע' ב'תקסג. ע' ב'תקסז ואילך. וראה גם סה\"מ תרכ\"ו ע' קיד בשולי הגליון [במהדורת תשמ\"ט]. ע' קיז ואילך. סה\"מ תרנ\"ה ע' צה<sup data-n=\"e42\">א</sup>. ע' ק ואילך. לקמן פי\"ט על יד הערה 481.\nמאמר זה נזכר ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061024\" data-slug=\"likkutei-sichot\" data-id=\"1300061024\">לקו\"ש שמות כרך ו ע' 24</a> בהערה.\nהנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה נדפסה לקמן (בחלק הנחותיו) ושם הפתיחה: מזבח אדמה תעשה לי<sup data-n=\"e43\">ב</sup>."],["611","278","<b>במד\"ר ר\"פ תצוה</b>: בשינויים וכו'."],["612","279","<b>י\"ח</b>: כנצ\"ל: יא, טז.\n\n<b>א</b>  נדפס גם בסה\"מ תרס\"ח ע' רכא.\n\n<b>ב</b>  ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470148,"ישראל אלא בזית הזה בלבד, והלא בכל מיני אילנות נאים ומשובחים נק' ישראל בגפן ובתאנה ובתמר<sup data-n=\"613\">280</sup>, שנא' גפן ממצרים<sup data-n=\"614\">281</sup>, כבכורה בתאנה<sup data-n=\"615\">282</sup>, זאת קומתך<sup data-n=\"616\">283</sup> דמתה לתמר, כארז בלבנון<sup data-n=\"617\">284</sup>, אל גינת אגוז<sup data-n=\"618\">285</sup> כו', וכתי' שלחייך פרדס רמונים<sup data-n=\"619\">286</sup>, ובא ירמי' לומר זית רענן כו' אלא מה הזית הזה עד שהוא באילנו מגרגרי' אותו ואח\"כ מורידין אותו מן הזית ונחבט, ומשחובטין אותו מעלין אותו לגת ונותנין אותו במטחן, וטוחנין ומקיפי' אותו בחבלים ומביאים אבנים להכביד עליהם, ואח\"כ נותני' שמנן כך ישראל כו' וחובטין אותם, וחובשי' וכופתי' אותם בקולרין, ומקיפי' אותם טרטיוטין ואח\"כ עושין תשובה והקב\"ה עונה להן מנין שנא' ויאנחו<sup data-n=\"620\">287</sup> כו' בצר לך<sup data-n=\"621\">288</sup> כו' כי אל רחום<sup data-n=\"622\">289</sup> ה' אלקיך כו' הוי זית רענן, ונמצא ענין הוצאת השמן מן הזיתים נמשל לחוטא שהיצר לו ה' מאד עד ששב לה' בכל לבו ובכל נפשו ובכל מאודו וז\"ע השמן היוצא מן הזתים ע\"י כתישה וטחינה וכבישה כו'.\n<b>ויובן</b> זה ע\"פ מה שנודע בדרז\"ל במד\"ר שטען משה על ישראל שבגלות מצרים אלו מה חטאו, &lt;19&gt;\nּ וא' נטלתי ס' בראשית<sup data-n=\"623\">290</sup> ומדה\"ד היתה פי' המת\"כ דין אמת אבל אלו מה חטאו, ותי' בפע\"ח שישראל שבמצרים הי' גלגול דור הפלגה<sup data-n=\"624\">291</sup>, וא\"כ א\"מ כלל טענת משה<sup data-n=\"625\">292</sup>, וזהו שא' להם פרעה ותוכן לבנים תתנו<sup data-n=\"626\">293</sup> היינו תוכן מספר הלבנים שעשיתם בהעיר והמגדל אשר בנו בני האדם<sup data-n=\"627\">294</sup> תתנו עכשיו לתקן אתכם<sup data-n=\"628\">295</sup>, ולכאו' יש להקשות על הפע\"ח הנ\"ל מהמשנה שבסנהדרין דור הפלגה<sup data-n=\"629\">296</sup> אין להם חלק לעוה\"ב ואין עומדין בדין<sup data-n=\"630\">297</sup>, אך הענין שבאמת קאי על לע\"ל שנק' עוה\"ב, שפי' שגופן לא יתוקן לעולם, אבל נשמתן נזדכך בחומר ולבנים שעבדו במצרים, ותמורת",[["613","280","<b>ובתמר</b>: בהמשך הנדפס ניתוסף: כו'."],["614","281","<b>גפן ממצרים</b>: תהלים פ, ט."],["615","282","<b>כבכורה בתאנה</b>: הושע ט, י."],["616","283","<b>זאת קומתך</b>: שה\"ש ז, ח."],["617","284","<b>כארז בלבנון</b>: תהלים צב, יג."],["618","285","<b>אל גינת אגוז</b>: שה\"ש ו, יא."],["619","286","<b>שלחייך פרדס רמונים</b>: שה\"ש ד, יג."],["620","287","<b>ויאנחו</b>: שמות ב, כג."],["621","288","<b>בצר לך</b>: ואתחנן ד, ל."],["622","289","<b>כי אל רחום</b>: ואתחנן שם, לא."],["623","290","<b>במד\"ר. . נטלתי ס' בראשית</b>: ראה שמו\"ר ספ\"ה. ראה גם אוה\"ת וארא כרך ז ע' ב'תקסג. סה\"מ תרכ\"ו ע' קיד בשולי הגליון [במהדורת תשמ\"ט]. המשך מים רבים תרל\"ו ע' קסד ומציין לד\"ה וארא בס' תרי\"ח<sup data-n=\"e44\">ג</sup>. סה\"מ תרנ\"ה ע' צה<sup data-n=\"e45\">ד</sup>."],["624","291","<b>בפע\"ח שישראל. . גלגול דור הפלגה</b>: ראה שם שער חג המצות שכ\"א, פ\"א. מאמרי אדה\"א ויקרא ח\"א ע' עג. וש\"נ. שמות ח\"א ע' כה. וש\"נ."],["625","292","<b>א\"מ כלל טענת משה</b>: ראה המשך מים רבים שם: ”ולא ידע משה כי הגם<sup data-n=\"e46\">ה</sup> עצמם אותם האנשים אשר חטאו בדור הפלגה\". סה\"מ תרכ\"ו שם."],["626","293","<b>ותוכן לבנים תתנו</b>: שמות ה, יח. ראה גם אוה\"ת וארא כרך ז ריש ע' ב'תקנד."],["627","294","<b>בהעיר והמגדל. . האדם</b>: נח יא, ה."],["628","295","<b>אתכם</b>: בהמשך הנדפס: עכשיו."],["629","296","<b>מהמשנה שבסנהדרין דור הפלגה</b>: פ\"י, מ\"ג. (פי\"א) קז, סע\"ב. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300031007\" data-slug=\"likkutei-sichot\" data-id=\"1300031007\">לקו\"ש נח כרך ג</a> הערה 12 ואין מי שיחלוק ע\"ז."],["630","297","<b>ואין עומדין בדין</b>: וכ\"ה לקמן רפי\"ז. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 24. סה\"מ תרכ\"ו ס\"ע קיז [במהדורת תשמ\"ט]. אבל בסה\"מ תרנ\"ה ס\"ע קג: ”ע' ברש\"י ובתוי\"ט שעומדי' בדין\".\n\n<b>ג</b>  ויש להוסיף דרוש זה ברשימת מאמרי דא\"ח של כ\"ק אדמו\"ר הצ\"צ שנת הנ\"ל.\n\n<b>ד</b>  נדפס גם בסה\"מ תרס\"ח ע' רכא.\n\n<b>ה</b>  <b>אוצ\"ל</b>: הם."]]],[2000470149,"חטאם שחטאו בבנין העיר והמגדל דכתי' בהם ותהי להם הלבינה לאבן<sup data-n=\"631\">298</sup> והחמר הי' להם לחומר, תיקנו במה שעבד בהם פרעה בחומר ובלבנים כו'. והענין יובן ע\"פ מה שמבואר בזהר ס\"פ נח ענין העיר והמגדל<sup data-n=\"632\">299</sup> שזהו כמו שבקדושה האלקי' נמשך השפע ע\"י עיר ומגדל, עיר הוא<sup data-n=\"633\">301</sup> בחי' ירושלים עיר אלקינו<sup data-n=\"634\">300</sup> ומגדל היינו בחי' ציון כמגדל דוד צוארך<sup data-n=\"635\">302</sup>, והם בקשו לעקור את הכל ולעשות דוגמתם בהבקעה הטמאה בארץ שנער, שנער בגימ' כרת<sup data-n=\"636\">303</sup> שהיא הקלי' שכנגד הכתר<sup data-n=\"637\">304</sup>, ורצו שישרה עליהם שתי בחי' אלו שבקלי' לעומ\"ז דעיר ומגדל שבקדושה, והיינו בחי' עיר ומגדל שבקלי', ע' מזה בזהר שם ובס' זה\"ח שם<sup data-n=\"638\">305</sup> ובמהרמ\"א ס\"פ נח<sup data-n=\"639\">306</sup>, וביאור ענין בחי' עיר ומגדל שבקדושה יובן ע\"פ משנ\"ת בת\"א פ' וארא בד\"ה וידבר אלקי' כו' וארא אל אברהם<sup data-n=\"640\">307</sup> שהוא בחי' עולם הדבור, כי האותיות נק' בשם אבנים, וכמ\"ש בס\"י שתי אבנים בונות שני בתים<sup data-n=\"641\">308</sup> שלשה אבנים בונות ששה בתים וכו', והיינו שכמו מקבוץ הרבה אבנים יחד נעשה בית, ובהקבץ הרבה בתים ביחד נעשה עיר, כך מצירוף ג' או ד' אותיות או יותר נעשה תיבה, וכנודע שצירוף התיבה מתחלת מב' אותיות עד עשרה אותיות<sup data-n=\"642\">309</sup> וה\"ז כמו הבית הנעשה מאבנים, ובהקבץ הרבה בתים יחד נעשה עיר, וה\"ז משל להבין בחי' עולם הדבור שלמעלה, כמו ע\"מ שהם מאמרים כללי' שמהם נבראו כל מה שנברא בשי\"ב, שהם קיבוץ תיבות רבות שכל תיבה יש בה צירופי אותיות הרבה<sup data-n=\"643\">310</sup> כו', וכתי' גדול ה' ומהולל מאד בעיר אלקינו<sup data-n=\"644\">311</sup> שבבחי' עיר אלקינו הנ\"ל בה מאיר בחי' ש' הוי' וכמ\"ש במ\"א שע\"י בחי' עיר אלקינו נודע גדולת הוי', או שגדולת ה' נעשה ע\"י עיר אלקינו משא\"כ מלכא בלא מטרוניתא לאו",[["631","298","<b>ותהי להם הלבינה לאבן</b>: נח יא, ג. ראה גם סה\"מ תרכ\"ו שם."],["632","299","<b>בזהר ס\"פ נח ענין העיר והמגדל</b>: עד, ב (בס\"ת)<sup data-n=\"e47\">ו</sup>."],["633","301","<b>הוא</b>: בהמשך הנדפס: היינו."],["634","300","<b>עיר. . ירושלים עיר אלקינו</b>: תהלים מח, ב ובתרגום ומפרשים שם. ועד\"ז באוה\"ת כאן ע' ב'תקסז. ובזהר שם הובא הכתוב: עיר דוד היא ציון וגו' [שמואל-ב ה, ז ושם: מצודת ציון היא עיר דוד. אבל בזהר ואתחנן רסב, ב מציין: מל\"א ח, א ושם: מעיר]."],["635","302","<b>כמגדל דוד צוארך</b>: שה\"ש ד, ד."],["636","303","<b>שנער בגימ' כרת</b>: מובא גם באוה\"ת כאן ע' ב'תקסז. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 32."],["637","304","<b>שנער. . שהיא </b>[בהמשך הנדפס: שהוא]<b> הקלי' שכנגד הכתר</b>: מובא גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490065\" data-slug=\"or-hatorah-hb\" data-id=\"8316490065\">אוה\"ת</a> כאן. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 33. ובאוה\"ת לך כרך ד ע' תשב: שנער גימט' תר\"ך כתר דקליפה. בסה\"מ תרמ\"ג ע' ז: דשנער בגימ' כתר והוא כתר דקליפה."],["638","305","<b>ובס' זה\"ח שם</b>: מובא גם באוה\"ח ס\"פ נח בס\"ת (סט, ד ואילך)<sup data-n=\"e48\">ז</sup>."],["639","306","<b>ובמהרמ\"א ס\"פ נח</b>: חלקו הועתק באוה\"ת נח כרך ג' ע' 1308 ואילך."],["640","307","<b>בת\"א פ' וארא. . אברהם</b>: נו, סע\"ב."],["641","308","<b>בס\"י שתי אבנים. . בתים </b>[בהמשך הנדפס ניתוסף: כו']: ראה שם פ\"ד, מי\"ב."],["642","309","<b>התיבה. . עשרה אותיות</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן למשפחותיכם — וראה בהערה 40 שם."],["643","310","<b>הרבה</b>: בהמשך הנדפס: התורה."],["644","311","<b>גדול הוי'. . בעיר אלקינו</b>: תהלים מח, ב. ראה לעיל מאמר ד\"ה כמגדל דוד צוארך. וש\"נ.\n\n<b>ו</b>  הועתק באוה\"ת נח כרך ג' ע' תרנה. ע' תרסג ואילך. כרך ו' ע' תתרע.\n\n<b>ז</b>  הועתק באוה\"ת שבהערה 299 אות ו."]]],[2000470150,"איהו מלך ולאו איהו גדול כמ\"ש בזהר פ' ויקרא<sup data-n=\"645\">312</sup> כו', וז\"ע גדול הוי' שבעיר אלקינו וזהו דכתי' מגדל עוז ש' הוי'<sup data-n=\"646\">313</sup> בו ירוץ צדיק וזהו הנק' ציון שהוא פנימיות ירושלים<sup data-n=\"647\">314</sup> בחי' גדול הוי' שבעיר אלקינו, ועז\"נ מי יתן מציון ישועת ישראל<sup data-n=\"648\">315</sup>, כי שם צוה ה' את הברכה<sup data-n=\"649\">316</sup> וכדומה רבות, אך הנה כדי לקבל מבחי' זו שבקדושה עז\"נ את האלקי' ירא<sup data-n=\"650\">317</sup> ואת מצותיו שמור שצ\"ל &lt;20&gt;\nּ בבחי' יראה וביטול לקבל ע\"ע בחי' עומ\"ש ועול מצות, והם רצו לילך בשרירות לבם הרע, ומ\"מ יומשך להם שפע ותענוגי עוה\"ז מלמעלה, וזה ידעו שעיקר השפע בא מלמעלה רק שבכדי לקבל מההכרח להיות בבחי' הביטול כו', והם לא רצו בזה וכנ\"ל, ע\"כ נתייעצו שיומשך להם השפע ע\"י בחי' עיר ומגדל שבלעו\"ז שהם נגד בחי' עיר ומגדל שבקדושה, והיינו אותיות אחרים שלא מבחי' העיר והמגדל שבקדושה ולכן נא' ותהי להם הלבינה לאבן שתמורת האבן הוא אותיות שבבחי' הקדושה האלקית וכנודע שאבן הוא בחי' א'<sup data-n=\"651\">318</sup> בן, והוא בריאה בידי שמים, לקחו להם הלבינה<sup data-n=\"652\">319</sup> שהיא הנעשית בידי אדם, והיינו בחי' מל' דנוגה<sup data-n=\"653\">320</sup>, וענין שנעשית בידי אדם הגם כי ישנה גם קודם אלא שאינה נחשב ליש ודבר כ\"כ כ\"א ע\"י האדם שמחשבה ליש ודבר כו' וכנודע מענין ע\"ז של ישראל<sup data-n=\"654\">321</sup>, וזהו ותהי להם הלבינה שהם לקחו לעצמם בחי' לבינה תמורת האבן דקדושה וכענין שארז\"ל זקף לבינה והשתחוה לה<sup data-n=\"655\">322</sup>, וע' בפרד\"ס<sup data-n=\"656\">323</sup> ערך לבינה וז\"ל לבינה היא<sup data-n=\"657\">324</sup> סט' דמסאבותא וזהו זקף לבינה, והיינו כמ\"ש לעיל.\n<b></b>קיצור. זית רענן שיציאת השמן מן הזית הוא ע\"י כתישה וטחינה, ועד\"ז בישראל כו', ויובן זה ע\"פ מ\"ש בזהר בחטא דור הפלגה שבנו עיר ומגדל דלעו\"ז ורצו להרוס בנין הקדושה וזהו ותהי להם הלבינה מל' דנוגה תמורת האבן מל' דקדושה ע\"ד זקף לבינה כו'.\n(טו) <b>ויובן</b> עוד ותהי להם הלבינה לאבן, דהנה פי' אבן היינו כמ\"ש בזח\"ג פ' שלח דקכ\"ח<sup data-n=\"658\">325</sup> ע\"א שהוא בחי' אבן בוחן<sup data-n=\"659\">326</sup>, והיינו שע\"י אבן זה נבחנו",[["645","312","<b>מלכא בלא מטרוניתא. . בזהר פ' ויקרא</b>: ה, א. הובא לעיל שם על יד הערה 39."],["646","313","<b>מגדל עוז ש' הוי'</b>: משלי יח, י. ראה סה\"מ תר\"ל ס\"ע ו ואילך."],["647","314","<b>ציון. . ירושלים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380716\" data-slug=\"likkutei-torah\" data-id=\"4001380716\">לקו\"ת דברים א, ג</a>."],["648","315","<b>מי יתן מציון ישועת ישראל</b>: תהלים יד, ז."],["649","316","<b>כי שם צוה ה' את הברכה</b>: תהלים קלג, ג."],["650","317","<b>את האלקי' ירא</b>: קהלת יב, יג."],["651","318","<b>שאבן. . א' ב\"ן</b>: ראה שער היחוה\"א פ\"ז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540064\" data-slug=\"torat-chaim\" data-id=\"2300540064\">תו\"ח בא ח\"א קטו, ג</a>. וש\"נ."],["652","319","<b>שאבן. . הלבינה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370344\" data-slug=\"torah-or\" data-id=\"3901370344\">תו\"א משפטים עז, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370347\" data-slug=\"torah-or\" data-id=\"3901370347\">עח סע\"ב</a> ואילך."],["653","320","<b>הלבינה. . מל' דנוגה</b>: ראה גם לקמן רפי\"ז. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 49. סה\"מ תרכ\"ו כאן ע' קיח. אוה\"ת צפני' כרך ב' ע' תתקה. נח כרך ג ס\"ע 1314 ס\"ע 1324 (מ' דקליפה)."],["654","321","<b>ע\"ז של ישראל</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 51."],["655","322","<b>זקף לבינה והשתחוה לה</b>: ע\"ז מו, א. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061016\" data-slug=\"likkutei-sichot\" data-id=\"1300061016\">לקו\"ש שמות כרך ו ע' 16</a> הערה 33."],["656","323","<b>וע' בפרד\"ס</b>: שעה\"כ שכ\"ג, פי\"ב."],["657","324","<b>היא</b>: וכ\"ה באוה\"ת נח כרך ג' ע' 1314. בפרדס באוה\"ת שם ע' 1324 וארא כאן ס\"ע ב'תקסז ובהמשך הנדפס: הוא."],["658","325","<b>דקכ\"ח</b>: כנצ\"ל כבאוה\"ת וארא כאן: דקס\"ח."],["659","326","<b>אבן בוחן</b>: ישעי' כח, טז. הובא בפרדס הנ\"ל. ראה גם לקמן פט\"ז. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 53. וראה גם מאמרי אדה\"א שמות ח\"ב ע' תקכו. וש\"נ. שע\"ת סה, א ובהערה 1."]]],[2000470151,"ישראל, ועש\"ז נק' ג\"כ אבן ישראל<sup data-n=\"660\">327</sup>, וז\"ע אבן שתיה<sup data-n=\"661\">328</sup> שממנו הושתת העולם שכל תכלית הבריאה הוא בשביל זה כו' כמ\"ש במ\"א, והענין הוא שעיקר המכוון הוא להעלות האותיות והניצוצי' שנפלו בשבה\"כ להעלותם שיעלו בבחי' הביטול לאלקות כו', וזהו שא' יעקב והאבן הזאת<sup data-n=\"662\">329</sup> אשר שמתי מצבה יהי' בית אלקי', ואבן זה לקח מאבני המקום<sup data-n=\"663\">330</sup> דהנה נת' לעיל שאבנים הם בחי' אותיות כמ\"ש לעיל במשל צירוף התיבות, ונק' עוד בשם אותיות שהאותיות הם בחי' דומם<sup data-n=\"664\">331</sup> שהוא בחי' האחרונה, כן האותיות הם בחי' אחרונה מעשר כחות הנפש כו', ומאותיות שנבראו בהם שמו\"א נשתלשלו כ\"כ למטה עד שנעשה מהם חרן שזהו בחי' נחר גרוני<sup data-n=\"665\">332</sup> היפך האותיות שבהם מתלבש הקול, שאז נשמעים האותיות בהברתם, משא\"כ כשניחר הגרון אין נשמעי' האותיות כלל, שבנמשל ענין שמיעת האותיות זהו הוראה על בחי' גילוי האלקות שנמשך בהעולמות להיות בבחי' הביטול, ולהיפך העדר שמיעת האותיות זהו כשחיות האלקי עם היותו שמחי' ומהוה כמ\"ש ואתה מחי' את כולם א\"ת מחי' אלא מהוה<sup data-n=\"666\">333</sup> &lt;21&gt;\nּ עכ\"ז הנה זהו בלבוש שק המעלים ומסתיר לגמרי, ע\"ד שא' פרעה לי יאורי<sup data-n=\"667\">334</sup> כו', וכאשר הלך יעקב חרנה<sup data-n=\"668\">335</sup> בירר שם בירורי' ותחילת הבירור שלו הי' שלקח מאבני המקום נא' אבני לשון רבים והיינו שהאבנים להיותם במקום הפירוד לכן היו רבים, וכאשר העלה אותם עשה מריבוי האבנים אבן א' כמ\"ש וישם אותה מצבה<sup data-n=\"669\">336</sup> לשון יחיד, וכן אמר אח\"כ והאבן הזאת לשון יחיד, והיינו שרומז על בחי' היו\"ד דש' הוי' וכמ\"ש בזהר אבנא למשקל בה דא יו\"ד<sup data-n=\"670\">337</sup>, יו\"ד הוא בחי' חכ'<sup data-n=\"671\">338</sup> שהוא בחי' ביטול, שתמורת שהיו תחלה בבחי' הפירוד נעשו לאחדים ע\"י בחי' הביטול שהאיר בהם ואז האיר בהם אוא\"ס, וכמ\"ש בסש\"ב פל\"ה בהג\"ה הטעם על השראת אוא\"ס בחכ' לפי שהוא אחד האמת כו', אך הנה לא כל האבנים באפשר להעלותם לכן אמר ויקח מאבני המקום ולא כל אבני<sup data-n=\"672\">339</sup> מטעם הנ\"ל כי יש אותיות שא\"א להעלותם כלל כ\"א צריכי' לדחות אותם כו'.",[["660","327","<b>אבן ישראל</b>: ויחי מט, כד. וראה גם לקמן פט\"ז ובהקיצור שם."],["661","328","<b>אבן שתיה</b>: יומא נג, ב. נד, ב. ראה גם לקמן פט\"ז."],["662","329","<b>והאבן הזאת</b>: ויצא כח, כב."],["663","330","<b>ואבן זה לקח מאבני המקום</b>: ויצא שם, יא."],["664","331","<b>שאבנים. . ונק'. . אותיות. . בחי' דומם</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370103\" data-slug=\"torah-or\" data-id=\"3901370103\">תו\"א ויצא כב, א</a>. תו\"ח שם קסד, סע\"א ואילך."],["665","332","<b>חרן. . נחר גרוני</b>: תהלים סט, ד. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370101\" data-slug=\"torah-or\" data-id=\"3901370101\">תו\"א ויצא כא, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370104\" data-slug=\"torah-or\" data-id=\"3901370104\">כב, ב</a>. תו\"ח שם קסו, ב ובהערה 30."],["666","333","<b>ואתה מחי'. . אלא מהוה</b>: נחמי' ט, ו. ראה שער היחוה\"א פ\"ב ובמ\"מ, הגהות והע\"ק שם. הערה בסה\"מ תש\"ד ע' 20."],["667","334","<b>לי יאורי</b>: יחזקאל כט, ג."],["668","335","<b>הלך יעקב חרנה</b>: ויצא כח, י."],["669","336","<b>וישם אותה מצבה</b>: ויצא שם, יח."],["670","337","<b>אבנא למשקל בה דא יו\"ד</b>: זהר רע\"מ ר\"פ תשא. ראה ביאוה\"ז שם נג, ב ואילך."],["671","338","<b>יו\"ד. . חכ'</b>: ראה זהר בראשית לא, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשסד ובהנסמן לשם."],["672","339","<b>מאבני המקום ולא כל אבני</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370103\" data-slug=\"torah-or\" data-id=\"3901370103\">תו\"א ויצא כב, א</a>."]]],[2000470152,"<b>ויובן</b> זה בעבודה בנה\"א דהנה היצה\"ר נק' אבן כמ\"ש לע\"ל והסירותי<sup data-n=\"673\">340</sup> את לב האבן<sup data-n=\"674\">341</sup> מבשרכם, ונתתי לכם לב בשר, פי' לב האבן קאי על היצה\"ר<sup data-n=\"675\">342</sup> שנק' אבן שקשה כאבן, ומטמטם הלב והמוח<sup data-n=\"676\">343</sup> עד שנעשה לבו כלב האבן, וענין היצה\"ר נת\"ל<sup data-n=\"677\">344</sup> שבעצם אינו רע, רק כשנמשכי' אחר הסתתו עי\"ז נעשה רע, ונמצא כי ע\"י פעולת האדם עי\"ז<sup data-n=\"678\">345</sup> נעשה אבן כו', והנה תאוות היצה\"ר מתלבשים באותיות המח' שמהרהר בתאוה שמתאוה, ואח\"כ מדבר בה שנמצא מלביש את תאוות לבו בהרבה לבושי', אך הנה בתאוות היצה\"ר לא כל התאוות שוים וממילא לא כל ההתלבשות באותיות המח' ואותיות הדבור שוים, דהנה כמו בחולי הגוף יש שהם חולים ועכ\"ז אינם חולי שיש בו סכנה, ויכולים לחיות זמן הרבה בחליים הגם שאינם חיים טובים ושלוים, עכ\"ז לעצם חיותם אינו נוגע חלים זה, רק לעת אשר יקרה לו חולאת גדולה הנה מחמת חלישותו לא יוכל להתגבר על החולאת כו', ויש חלאים שהם חולי שיב\"ס, שהחולאת גדולה כ\"כ עד שמפרדת חיות הנפש מן הגוף, ויש חולי בדקות היינו שלפעמים יקרה לו שמרגיש חלישות בעצמו כו', ועד\"ז יובן בענין חולי הנפש, שיש חולה בדקות והוא כמ\"ש בכהאריז\"ל חולה בגימט' מ\"ט<sup data-n=\"679\">346</sup> והיינו כשחסר לו שער הנו\"ן הוא ג\"כ חולה אבל חולי זה הוא בדקות בעבודה האלקי' שהרי גם במשה נא' ותחסרהו מעט מאלקי'<sup data-n=\"680\">347</sup> פי' מאלקי' חיים דבינה<sup data-n=\"681\">348</sup> כי מ\"ט שערים נמסרו למשה<sup data-n=\"682\">349</sup> ושעה\"נ לא השיג עד הסתלקותו שאז השיג גם שעה\"נ<sup data-n=\"683\">350</sup> ג\"כ, ולכן ארז\"ל לעליונים נדמה להם למטה<sup data-n=\"684\">351</sup> ולתחתוני' נדמה להם למעלה, להיותו ספון בשעה\"נ דבינה ולכן עליונים מהחכ' ולמעלה נדמה להם למטה, ולתחתוני' היינו מהבינה ולמטה נדמה להם למעלה כי שעה\"נ הוא למעלה מהשגת הבינה כו', ונמצא אשר",[["673","340","<b>לע\"ל והסירותי</b>: ראה גם שע\"ת סג, סע\"ב ובהערה 20. ש\"א פז, א. אוה\"ת שבהערה 342."],["674","341","<b>והסירותי את לב האבן</b>: יחזקאל לו, כו."],["675","342","<b>והסירותי. . לב האבן. . היצה\"ר</b>: ראה סוכה נב, א. זהר ואתחנן רסז, ב. אוה\"ת יחזקאל כרך א ס\"ע תיז ואילך."],["676","343","<b>ומטמטם הלב והמוח</b>: ראה יומא לט, א. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 75. ד\"ה ואלא עלמא אמאי קאים על יד הערה 49. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פכ\"ה. מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 127. (בחלק ההנחות) הנחה ד\"ה אני לדודי הא' פיסקא אך כ\"ז. ד\"ה שובה ישראל הא' פיסקא וזהו אתה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540229\" data-slug=\"torat-chaim\" data-id=\"2300540229\">תו\"ח שמות ח\"א ב, ב</a>. וש\"נ. סה\"מ תרכ\"ו ע' לא. תרל\"ד ס\"ע קסד ואילך. המשך והחרים תרל\"א ע' ג."],["677","344","<b>נת\"ל</b>: פ\"ב."],["678","345","<b>עי\"ז</b>: ניתוסף ע\"פ המשך הנדפס."],["679","346","<b>חולה בגימט' מ\"ט</b>: ראה טעמי המצות להאריז\"ל ר\"פ וירא. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381116\" data-slug=\"likkutei-torah\" data-id=\"4001381116\">לקו\"ת</a> להאריז\"ל ויחי מח, ב. מאו\"א מערכת חולה סל\"ה. לקו\"ת ברכה צז, ב. המשך וככה תרל\"ז ספס\"ג."],["680","347","<b>ותחסרהו מעט מאלקי'</b>: תהלים ח, ו. ראה מאמרי אדה\"א במדבר ח\"ב ע' תלד."],["681","348","<b>מאלקי' חיים דבינה</b>: ואתחנן ה, כג. ראה זהר יתרו סח, ב ובהגהות הרח\"ו שם. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'קסח קונטרסים ע' תקמ."],["682","349","<b>מ\"ט שערים נמסרו למשה</b>: ראה ר\"ה כא, ב."],["683","350","<b>למשה. . הסתלקותו. . שעה\"נ</b>: ראה לקו\"ת וס' הליקוטים להאריז\"ל ואתחנן ג, כו. מג\"ע אופן כט. מאמרי אדה\"א במדבר ח\"ב ע' תלד וע' תלה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241257\" data-slug=\"likkutei-sichot\" data-id=\"1300241257\">לקו\"ש ברכה כרך כד ע' 257</a> הערה 33. ר\"ה כרך יד ע' 451 בהערה. בהערה הבאה."],["684","351","<b>לעליונים נדמה להם למטה</b>: ראה סוטה יד, רע\"א. מאמרי אדה\"ז תקס\"ה ח\"א ע' קפד <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380356\" data-slug=\"likkutei-torah\" data-id=\"4001380356\">לקו\"ת במדבר יב, א</a> ואילך (בשם המגיד)."]]],[2000470153,"בשאר כל אדם חולה כזה הוא חולה בדקות, ויש חולה שהוא &lt;22&gt;\nּ חולה היותר גדול והיינו שמלא בתאוות היתר, ועם היות שהוא דבר המותר, פי' שאינו אסור וקשור בידי החיצוני'<sup data-n=\"685\">352</sup>, וע\"י עבודה בשמחה אפשר להעלותם עכ\"ז כשעושה הדבר ההוא למלאות תאוות נפשו כי ירעב גם אחר עשותו הרבה וכמארז\"ל אבר קטן יש באדם<sup data-n=\"686\">353</sup> כו'<sup data-n=\"687\">354</sup> משביעו רעב שגם אחרי השובע הנה הוא רעב וכן בכל פרטי מיני תאות, כמו הזולל וסובא שלא יש די כלל גם אחרי שממלא תאוות לבו היינו אחרי אכלו ואחרי שתו, ורוחא לבסומי שכיחא<sup data-n=\"688\">355</sup> כו' ועם היות שזהו דבר המותר עכ\"ז התאוות היתר הנ\"ל מגשמיים האדם העושה אותם עד שמתבטל מהותו לגמרי, שהרי האדם הוא בחיר הנבראים<sup data-n=\"689\">*356</sup> וכל מה שברא הקב\"ה בעולמו<sup data-n=\"690\">356</sup> לא נברא אלא לצוות לזה, פי' לצוות שיהי' לו צוותא וחיבור<sup data-n=\"691\">357</sup> וזהו עלייתם וכמ\"ש לעיל<sup data-n=\"692\">358</sup> בענין דאכיל קרבנין שעלייה גדולה היא לצומח וחי שיוכלו להיות מבשר גוף המדבר, וכ\"ש שהם יחזקו העבודה אשר ע\"י האכילה עובד לה' בתורה ותפלה כו', משא\"כ כשמתאוה לאכול או התאוה בשארי פרטי' הנה כשתאב לאיזה דבר נעשה הוא המקבל העונג מהדבר ההוא, והדבר ההוא נעשה דבר המשפיע לו שפע העונג, והרי ירד הוא עשר מעלות אחורנית<sup data-n=\"693\">359</sup> שתמורת היותו גדול ובחיר הנבראי' נעשה שפל מן החי והצומח שהוא מקבל ענג מהם והם משפיעים לו ענג וחיות, והוא אינו מעלה אותם כלל, כ\"א שהם מורידים אותו ומגשמים אותו להיות פחות במעלה מן הצומח והחי, ועד\"ז בכל פרטי התאוות היתר שהיותו קשור ותאוב לדבר ההוא מוריד אותו ממהותו לגמרי להיות למטה היינו בחי' מקבל מן הדבר ההיא כו', ואי לזאת הגם כי החולה הזה אין בו סכנה כי מאחר שהם דברים המותרים ע\"פ דרכי וחוקי התורה שנמצא אינם מורידים אותו לבור שחת<sup data-n=\"694\">360</sup> לשחת נפשו לגמרי ולכרות אותה משרשה בחיי החיים<sup data-n=\"695\">361</sup> אוא\"ס ב\"ה, עכ\"ז ה\"ה כמו החולה שאין בו סכנה היינו הגם שאין בו סכנה שימות לגמרי ויפרד חיות הנפש מן הגוף, מ\"מ א\"א לכחש שהוא חולה וסובל יסורים קשים ועינויים מחולי הגוף המייגעים אותו ואינם מניחים אותו לפעול פעולתו ולעסוק בעסקי' כידוע ומובן לכל, וגם מזה עצמו הוא מלא דאגות ואנחות שתאוותו מתגברת עליו בכ\"י ואינו יכול להוציא מכאה\"פ כו', ועכ\"ז חולה זה הוא חולה שאב\"ס, ובקל יכול להתרפאות, אמנם הנה יש חולה שהוא חולה גדול כ\"כ עד שיש בו סכנת מות",[["685","352","<b>דבר המותר. . החיצוני'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא</a> פ\"ז. אגה\"ק סכ\"ו (קמג, ב)."],["686","353","<b>אבר קטן יש באדם</b>: סנהדרין קז, א."],["687","354","<b>כו'</b>: בהמשך הנדפס: ליתא."],["688","355","<b>ורוחא לבסומי שכיחא</b>: ראה ערובין פב, ב."],["689","*356","<b>האדם הוא בחיר הנבראים</b>: ראה גם עבודת הקודש חלק התכלית פ\"ב — פ\"ו. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ויאמר כו' לך לך על יד הערה 26. ד\"ה ויובן כו' הני ששה ועשרים הודו על יד הערה 62. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה הא'. (ובחלק ההנחות) בהנחה שם על יד הערה 32."],["690","356","<b>וכל מה שברא הקב\"ה בעולמו</b>: ראה ברכות ו, ב."],["691","357","<b>לצוות. . צוותא וחיבור</b>: ראה גם מאמרי אדה\"ז תקס\"ז ע' רצ. אוה\"ת מטות ע' א'רנח. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 95. סה\"מ תרמ\"ד ס\"ע רעג ואילך."],["692","358","<b>לעיל</b>: פ\"ה."],["693","359","<b>עשר מעלות אחורנית</b>: ע\"פ מל\"ב כ, י. יא. ישעי' לח, ח."],["694","360","<b>לבור שחת</b>: ע\"פ תהלים נה, כד."],["695","361","<b>בחיי החיים</b>: יומא עא, א."]]],[2000470154,"שיפרד נפשו מן הגוף לגמרי ולא ישוב עוד להחיותו, והיינו שזה כשנלכד בתאוות איסור ונפל בתאוה חמורה כזו וכ\"ש כשנכשל בה לעשות אחת ממצות ה' אשר לא תעשינה ואשם<sup data-n=\"696\">362</sup>, פי' ואשם שנאשם נפשו לה' בעברו על ציוויו, ויש בכללם דברים האסורים שחייבים עליהם כרת ומיתה היינו שנכרת נפשו לגמרי מאלקי' חיים חיי החיים האמיתי' הנה חולה כזה הוא חולה גדול שיש בו סכנת מות שימות נפשו\n&lt;23&gt;\nּ לגמרי כו', והגם כי אין לך דבר שעומד בפני התשו'<sup data-n=\"697\">363</sup>, אמנם צריכים לזה תשובה גדולה תשובה עילאה מעומקא דלבא כו', וכמו תשובת ראב\"ד שיצאה נפשו מבכי'<sup data-n=\"698\">364</sup> על היותו נפרד כו', שזהו מדה במדה שלא בטלה<sup data-n=\"699\">365</sup> שכשם שע\"י החטא ועון כרת נפשו מחיי החיים, כן בתשובתו החזקה הלזה נפרד נפשו מכל תאוות שבעולם להעלותה ולקשרה באוא\"ס חיי החיים וה' יסלח לו<sup data-n=\"700\">366</sup> ויכפר על נפשו מאשר פגם, לעלות במעלות ולקשר נפשו בה' אחד ומקום שבע\"ת עומדי'<sup data-n=\"701\">367</sup> כו'.\n<b></b>קיצור. אבן הוא אבן בוחן, יעקב עשה מאבני המקום אבן א' יו\"ד ביטול כו', וכמ\"כ בעבודה בנה\"א אבן הוא היצה\"ר, ויש ג' מיני חולי הנפש חולה שאב\"ס וחולה שיב\"ס, וחולי בדקות, והיינו חולה מ\"ט שחסר שעה\"נ, ותאוות היתר, ותאוות איסור, ועכ\"ז אין לך דבר שעומד בפני התשובה כו'.\n(טז) <b>וכמו</b> שהוא בענין החולה עצמו שהוא היותו חולה שנוגע לנפשו אם רב ואם מעט אבל זהו בעצם נפשו, כן יובן<sup data-n=\"702\">368</sup> דבר זה בלבושי מחו\"ד שהם מלבושי הנפש, שהחולה שבדקות שחסר לו שעה\"נ הנה יקרה אצלו מחשבות זרות המונעי' ומעכבים אותו בעבודה ולפי ערך מיעוט החולי כן הוא מיעוט המח\"ז, וכמאמר ר\"ח יומא חד בעי לאכוונא<sup data-n=\"703\">369</sup> והתחיל להרהר אלקפתא<sup data-n=\"704\">370</sup> וריש גלותא מאן אעיל קדם לגבי מלכא, והגם שגם בזה יש כוונה עמוקה וכמ\"ש במ\"א בהגהות לד\"ה ונשב בגיא<sup data-n=\"705\">371</sup>, עכ\"ז לגבי כונתו בתפלתו שבהתקשרותו הי' יכול להביא מב\"ד בלא זמנו<sup data-n=\"706\">372</sup> ג\"ז נחשב לו למח\"ז<sup data-n=\"707\">373</sup>, ולפי ערך זה כל איש ישראל העובד בעבודה שבלב זו",[["696","362","<b>אחת ממצות ה'. . ואשם</b>: ויקרא ד, כז."],["697","363","<b>אין לך דבר שעומד בפני התשו'</b>: ראה תניא פכ\"ה. פיה\"מ להרמב\"ם אבות פ\"ג, מי\"א. סה\"מ תש\"ט ע' 42 (הא') בהערה. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061066\" data-slug=\"likkutei-sichot\" data-id=\"1300061066\">לקו\"ש בא כרך ו ע' 66</a> הערה 54."],["698","364","<b>ראב\"ד שיצאה נפשו מבכי'</b>: ע\"ז יז, א. ראה סה\"מ תרמ\"ו ע' יט."],["699","365","<b>מדה במדה שלא בטלה</b>: ראה שבת קה, ב. סוטה ח, ב."],["700","366","<b>וה' יסלח לו</b>: ע\"פ מטות ל, ו. ט. יג."],["701","367","<b>ומקום שבע\"ת עומדי'</b>: ראה ברכות לד, ב. לקו\"ש נצבים כרך יד ע' 361 וע' 363. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a>. וש\"נ. סה\"מ מלוקט ד' ס\"ע יח."],["702","368","<b>נפשו כן יובן</b>: בהמשך הנדפס: נפשו כן, וכן."],["703","369","<b>יומא חד בעי לאכוונא</b>: ראה ירושלמי ברכות פ\"ב, סה\"ד."],["704","370","<b>אלקפתא</b>: וכ\"ה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 109. בהמשך הנדפס: אקלפתא. באוה\"ת שבהערה הבאה: ארקפסא. בפלח הרמון ויקרא ע' קו: אלקפטא. ראה מערכת הערוך בירושלמי שם."],["705","371","<b>בהגהות לד\"ה ונשב בגיא</b>: אוה\"ת ואתחנן ע' קנה. פלה\"ר שם ע' קיט ואילך."],["706","372","<b>להביא מב\"ד בלא זמנו</b>: ב\"מ פה, ב."],["707","373","<b>נחשב לו למח\"ז</b>: ראה גם כש\"ט קה\"ת סקס\"ב."]]],[2000470155,"תפלה כשנופל לו מח\"ז מורה על היותו חולה עדיין בדקות, ואם מתגברי' עליו ריבוי מח\"ז עד שא\"י מה שהוא מדבר זהו מצד היותו חולה יותר גדול כו' וכמשי\"ת<sup data-n=\"708\">374</sup>, ויש חולה שהוא חולה שאין בו סכנה אבל עכ\"ז הוא חולה ממש, ולאיש כזה מלבישי' אותו המחשבות וההרהורי' בתאוות לבו עד שהולך משומם ולבו בל עמו שמחשב בטיב<sup data-n=\"709\">375</sup> הדבר ההוא, ואם תעלה לו להשיגה ומתי ישיגנה והאיך הוא הדרך לבוא לזה, וכשישיגנה יעשה כך וכך, הנה הרהורים ומחשבות כאלו מטמאים הנפש ומלבישים אותה מכף ראשה ועד רגלה<sup data-n=\"710\">376</sup> ועד בכלל עד שמתלבשת בלבושי' צואים כאלו שא\"א לו כלל לעבוד את השי\"ת, ומה בגדי' שבישל בהם קדירה לרבו לא ימזוג בהם כוס לרבו<sup data-n=\"711\">377</sup> כ\"ש לבושי' צואים ומלוכלכים כאלו א\"א לו כלל וכלל לעלות בהיכל המלך, וה\"ה נדחה ממחיצתו של הקב\"ה עבורם, וכמ\"ש כי אין לבוא אל המלך<sup data-n=\"712\">378</sup> בלבוש שק, ש\"ק בגימ' ד' מאות<sup data-n=\"713\">379</sup>, והוא הלבוש דעשי'<sup data-n=\"714\">380</sup> שהוא גס, אך שמ\"מ הוא נקי ועכ\"ז אין לבוא בו אל המלך כ\"ש בלבושים צואים מהרהורים ומחשבות זרות ורעות גם בתאוות היתר ה\"ה נדחה גם מחצר החיצונה ג\"כ כי א\"א לטהור עינים &lt;24&gt;\nּ לראות בלבושי' רעים ומזוהמי' כאלה כו', וכ\"ש מי שנלכד ונכשל בתאוות איסור שההרהורי' והמחשבות פוגמי' ומטמאים הנפש עד שכשל כוחה לגמרי והם מקיפי' אותה עד שא\"א להרהר בתשובה כלל, פי' שגם ההרהור תשו' שהוא לבוש לבחי' התשובה ג\"כ א\"א לבוא לו מפני אשר הוטמאה נפשו במחשבות רעים וחטאים לה' בחטאת נעורים וזקנים אשר פגמו נפשו ודבוקי' ואחוזים בו עד שאין מקום כלל לנפשו לצאת ושיהי' לו מקום פנוי שתפול לו הרהור תשובה, ולכן ארז\"ל הרהורי עבירה קשה מעבירה<sup data-n=\"715\">381</sup> להיות כי אינו מניח לו לשוב לה' בתשו' אמיתית גם הרהור תשובה אינו נופל לו כלל מחמת ההרהורי' הרעים וחטאים לה' מאד שלבשו נפשו ופגמו אותה כ\"כ כנ\"ל.\n<b>והנה</b> נת\"ל שהאותיות הן אותיות המחשבה והן אותיות הדבור נקראי' אבנים, וע\"ז<sup data-n=\"716\">382</sup> שא' הכתוב ויקח יעקב מאבני המקום<sup data-n=\"717\">383</sup> ולא כל האבנים כי בחרן",[["708","374","<b>וכמשי\"ת</b>: בהמשך הנדפס: וכמשנ\"ת."],["709","375","<b>שמחשב בטיב</b>: שם: עד שמחשב בטוב."],["710","376","<b>מכף ראשה ועד רגלה</b>: ראה גם לעיל מאמר ד\"ה ואעשך לגוי גדול ובהערה 66. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 112: מכף רגלו ועד ראשו."],["711","377","<b>בגדי' שבישל. . כוס לרבו</b>: שבת קיד, רע\"א."],["712","378","<b>כי אין לבוא אל המלך</b>: אסתר ד, ב [בדילוג]."],["713","379","<b>ש\"ק בגימ' ד' מאות</b>: ראה שער רוח הקדש כונת שק. מבוא שערים ש\"ג ח\"ב, פ\"ט. לקו\"ת להאריז\"ל ישעי' עה\"פ (מ, יב) מי מדד הא'. מאמרי אדה\"ז תקס\"ה ח\"א ע' פה (נו\"א). ע' פג (נו\"ש). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370115\" data-slug=\"torah-or\" data-id=\"3901370115\">תו\"א וישלח כד, ג</a>. תו\"ח שם קפג, ריש ע\"ב."],["714","380","<b>הלבוש דעשי'</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרנב ואילך (נו\"א). ס\"ע תרנד ואילך (נו\"ש)."],["715","381","<b>הרהורי עבירה קשה מעבירה</b>: ראה יומא כט, א. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פי\"ז (ובשתי ההנחות שם). (בחלק ההנחות) הנחה ד\"ה שובה ישראל הא' על יד הערה 71 ואילך. מאמרי אדה\"א דברים ח\"א ע' קיד. וש\"נ. נ\"ך ע' פח. וש\"נ. שע\"ת ד, ד ובהערה 29."],["716","382","<b>וע\"ז</b>: בהמשך הנדפס: וע\"ד."],["717","383","<b>ויקח יעקב מאבני המקום</b>: ויצא כח, יא [בהוספת תיבת: יעקב]."]]]]});
